var e=JSON.parse(`{"wrist-circles":{"name":"Handgelenkskreise","description":"Steh aufrecht, Ellbogen locker, Unterarme vor dir. Zeichne langsame Kreise mit beiden Handgelenken, vier Zählzeiten in die eine, vier in die andere Richtung, Finger locker lassen.","goodFor":"Wärmt Handgelenke und Unterarme auf, die bei jedem Prop die Hauptarbeit leisten.","alignmentCues":["Ellbogen bleiben still; nur die Handgelenke bewegen sich.","Halte die Kreise groß und flüssig."],"commonMistakes":["Die Kreise hetzen, sodass sie zu Schnippern werden."]},"arm-circles":{"name":"Armkreise","description":"Füße hüftbreit, Arme lang. Schwing beide Arme vier Zählzeiten lang in großen Vorwärtskreisen, dann vier rückwärts, und lass die Schulterblätter gleiten.","goodFor":"Öffnet die Schultern für Staff-Spins und Hoop-Arbeit über dem Kopf.","alignmentCues":["Rippen bleiben unten, während die Arme über den Kopf ziehen.","Atme beim Abschwung aus."]},"shoulder-rolls":{"name":"Schulterrollen","description":"Arme entspannt an den Seiten. Heb die Schultern zu den Ohren, roll sie nach hinten und unten, und wiederhole das in einer langsamen Schleife.","goodFor":"Löst Spannung, die Würfe steif und kurz macht."},"neck-rolls":{"name":"Halbe Nackenkreise","description":"Senk das Kinn zur Brust und führ es langsam in einem Halbkreis von Schulter zu Schulter. Kopf nicht nach hinten kippen lassen.","goodFor":"Entlastet den Nacken, bevor du lange nach oben zu Würfen schaust.","avoidIf":["Nackenverletzung oder Schwindel bei Kopfbewegungen."]},"hip-circles":{"name":"Hüftkreise","description":"Hände an die Hüften, Knie weich. Kreis die Hüften langsam zwei Takte in die eine und zwei in die andere Richtung, Kopf bleibt waagerecht.","goodFor":"Bereitet die Hüften auf Waist Hooping vor und den Körper auf Flow."},"torso-twists":{"name":"Rumpfdrehungen","description":"Füße weit, Arme locker. Dreh die Rippen nach links und rechts und lass die Arme schwingen und um dich wickeln wie leere Ärmel.","goodFor":"Weckt die Rotation für Staff-Weaves und Hoop-Pässe."},"knee-bounce":{"name":"Knie-Bounce","description":"Steh mit den Füßen unter den Hüften und federe sanft auf jeder Zählzeit durch die Knie, Arme schwingen locker. Finde die Musik in deinen Beinen.","goodFor":"Bringt den Beat in deinen Körper, bevor du einen Prop aufnimmst."},"one-ball-toss":{"name":"Ein-Ball-Wurf","description":"Halte einen Ball in der rechten Hand auf Hüfthöhe. Schöpf ihn ein und wirf ihn dann in einem Bogen, der knapp über Augenhöhe seinen Scheitelpunkt hat und in die linke Hand fällt. Wirf ihn auf dieselbe Weise zurück. Blick auf den Scheitelpunkt, nicht auf die Hände.","goodFor":"Baut den Bogen auf, aus dem jedes Jongliermuster besteht.","alignmentCues":["Ellbogen an den Seiten, Unterarme waagerecht.","Der Scheitelpunkt ist bei jedem Wurf gleich hoch.","Fang auf Hüfthöhe und lass die Hand ein wenig nachgeben."],"commonMistakes":["Nach vorne werfen, sodass du dem Ball nachsteigen musst.","Auf die Hände schauen statt auf den Scheitelpunkt."]},"two-ball-exchange":{"name":"Zwei-Ball-Austausch","description":"Ein Ball in jeder Hand. Wirf den rechten Ball in seinem Bogen; wenn er den Scheitelpunkt erreicht, wirf den linken Ball darunter auf der Innenseite. Fang beide und halte kurz inne. Dann beginne mit der linken Hand.","goodFor":"Lehrt den Austausch: Der zweite Wurf kommt, wenn der erste den Scheitelpunkt erreicht.","alignmentCues":["Zweiter Wurf am Scheitelpunkt, niemals früher.","Wirf den zweiten Ball innerhalb des ersten."],"commonMistakes":["Den zweiten Ball rübergeben statt ihn zu werfen.","Beide gleichzeitig werfen."]},"cascade":{"name":"Drei-Ball-Kaskade","description":"Zwei Bälle in der rechten Hand, einer in der linken. Wirf von rechts; wenn er den höchsten Punkt erreicht, wirf von links; wenn der seinen höchsten Punkt erreicht, wirf wieder von rechts. Jeder Wurf kommt auf den Beat und kreuzt in einem Achterbogen zur anderen Hand.","goodFor":"Das Grundmuster des Jonglierens.","modifications":["Übe den Flash: drei Würfe, drei Fänge, Stopp."],"deepen":["Jongliere zu einem schnelleren Tempo mit niedrigeren Gipfeln.","Zähle 20 Fänge ohne Drop."],"alignmentCues":["Wirf von innen, fange außen.","Gipfel auf gleicher Höhe, auf Augenhöhe.","Stell dich an eine Wand, wenn du immer nach vorne läufst."],"commonMistakes":["Nach vorne werfen und dem Muster hinterherjagen.","Hetzen, sobald ein Wurf schiefgeht."]},"reverse-cascade":{"name":"Umgekehrte Kaskade","description":"Die Kaskade von innen nach außen gedreht: Jeder Ball wird von außen über die Spitze des Musters geworfen und fällt in der Mitte in die andere Hand.","goodFor":"Trainiert Würfe von außen und öffnet Tricks wie den Mills Mess.","alignmentCues":["Würfe schleifen über den ankommenden Ball.","Fang in der Mitte."]},"siteswap-423":{"name":"423","description":"Ein Drei-Ball-Muster: ein hoher Eigenwurf (4), ein gehaltener Ball (2), dann ein Kaskadenwurf (3). Die 4 geht auf derselben Seite hoch; die 2 wird einfach einen Beat lang gehalten.","goodFor":"Dein erster Siteswap-Trick: lehrt hohe Würfe und Halten."},"siteswap-441":{"name":"441","description":"Zwei hohe Würfe, die auf ihrer eigenen Seite bleiben (4, 4), gefolgt von einem schnellen Zip rüber (1) von Hand zu Hand.","goodFor":"Baut Timing zwischen hohen Würfen und schnellen Pässen auf."},"two-in-one":{"name":"Zwei in einer Hand","description":"Jongliere zwei Bälle in einer Hand in nebeneinanderliegenden Säulen oder kleinen Kreisen nach außen, ein Wurf auf jedem zweiten Beat. Übe jede Hand.","goodFor":"Der Baustein des Vier-Ball-Jonglierens."},"siteswap-531":{"name":"531","description":"Ein sehr hoher Kreuzwurf (5), ein Kaskadenwurf (3) und ein schneller Zip (1). Die 5 geht hoch, während die anderen zwei Bälle darunter weiterarbeiten.","goodFor":"Höhenkontrolle und ein Showtrick mit drei Bällen."},"shower":{"name":"Drei-Ball-Shower","description":"Die Bälle wandern im Kreis: Die rechte Hand wirft jeden Ball hoch nach links, und die linke Hand gibt jeden direkt zurück nach rechts.","goodFor":"Klassisches kreisförmiges Muster; trainiert schnelle Hand-zu-Hand-Pässe."},"mills-mess":{"name":"Mills Mess","description":"Eine Drei-Ball-Kaskade, bei der die Arme sich ständig kreuzen und wieder öffnen, sodass jeder Wurf von der gegenüberliegenden Körperseite kommt. Die Ballwege zeichnen ein webendes Muster.","goodFor":"Ein berühmter Publikumsliebling, der die Koordination schärft."},"four-ball-fountain":{"name":"Vier-Ball-Fountain","description":"Jede Hand jongliert zwei Bälle in ihrer eigenen Säule, die Hände wechseln sich mit den Würfen ab, sodass das Muster nie kreuzt.","goodFor":"Dein erstes Vier-Ball-Muster."},"sync-fountain":{"name":"Synchrone Fountain","description":"Vier Bälle, bei denen beide Hände genau im selben Moment werfen, jede auf ihre eigene Seite.","goodFor":"Baut Symmetrie auf und führt zu Sync-Tricks."},"five-ball-cascade":{"name":"Fünf-Ball-Kaskade","description":"Die Cascade mit fünf Bällen: hohe, schnelle Würfe in einem hohen überkreuzenden Muster. Rechne mit Monaten des Übens.","goodFor":"Ein Meilenstein für engagierte Jongleure."},"tennis":{"name":"Tennis","description":"Eine Kaskade, bei der ein Ball – der „Tennisball“ – immer oben über das Muster fliegt statt durch die Mitte. Welche Hand ihn auch hält: Sie wirft ihn von außen, sodass er oben hin- und herfliegt wie ein Ballwechsel über ein Netz.","goodFor":"Der erste Schritt zu Außenwürfen, während das Timing eine normale Kaskade bleibt.","alignmentCues":["Behalte einen Ball als Tennisball im Blick.","Wirf ihn von außen, auf derselben Höhe wie die anderen."],"commonMistakes":["Den Überblick verlieren, welcher Ball oben fliegt.","Den Tennisball höher werfen als die anderen."]},"half-shower":{"name":"Halber Shower","description":"Eine Hand wirft jeden Ball oben über das Muster, die andere wirft jeden Ball unten durch. Die beiden Bögen trennen sich in eine hohe Außenbahn und eine tiefe Innenbahn, und die Bälle jagen einander im Kreis.","goodFor":"Die Hände in zwei Rollen aufteilen, während der Rhythmus gleichmäßig bleibt.","alignmentCues":["Die Oberhand wirft außen und einen Tick höher.","Die Unterhand hält ihre Würfe eng und innen."],"commonMistakes":["Beide Hände driften zurück in normale Kaskadenwürfe.","Zusammenstöße in der Mitte, wenn beide Bögen gleich hoch sind."]},"claw-cascade":{"name":"Claw-Kaskade","description":"Die Kaskade mit Handflächen nach unten gefangen. Jede Hand greift nach oben, schnappt den Ball von oben aus der Luft, zieht ihn nach unten und dreht das Handgelenk für den Wurf. Die Hände wirken wie Pfoten, die nach den Bällen schnappen.","goodFor":"Trainiert aktive Greiffänge und eine kräftige Handgelenksdrehung.","alignmentCues":["Greif nach oben dem Ball entgegen, Finger gespreizt.","Zieh nach unten und kippe das Handgelenk in einer Bewegung."],"commonMistakes":["Zu spät zugreifen, sodass der Ball auf den Handrücken trifft.","Zu niedrig werfen, weil die Drehung zu lange dauert."]},"chops":{"name":"Koteletten","description":"Nach jedem Fang trägt die Hand den Ball hoch über den Körper und hackt nach unten, der Wurf kommt von der anderen Seite. Die Arme schwingen aneinander vorbei wie beim Schneiden, und die Bälle fallen darunter in eine enge Kaskade.","goodFor":"Große Armbewegungen, während unten das Kaskaden-Timing weiterläuft.","alignmentCues":["Hoch fangen, rübertragen, runterhacken und werfen.","Wirf von der anderen Seite deines Körpers."],"commonMistakes":["Zu weit tragen, sodass der nächste Fang zu spät kommt.","Die Arme stoßen in der Mitte zusammen."]},"penguin-cascade":{"name":"Pinguin-Kaskade","description":"Die Arme hängen gestreckt seitlich am Körper, die Handflächen zeigen nach unten. Jeder Fang passiert tief und weit außen, und die Würfe schnippen von der Hüfte nach oben. Du siehst aus wie ein Pinguin, der im Takt flattert.","goodFor":"Wurfe aus dem Handgelenk und Fänge weit weg von der gewohnten Handposition.","alignmentCues":["Ellbogen durchgestreckt, Hände an der Hüfte.","Schnippe aus dem Handgelenk, Handflächen nach hinten."],"commonMistakes":["Ellbogen beugen und zurück in die normale Kaskade fallen.","Würfe driften nach vorn, weil das Handgelenk abgeknickt ist."]},"under-the-leg":{"name":"Unter dem Bein","description":"Eine Kaskade, bei der jeder sechste Wurf unter dem rechten Bein hindurchgeht. Heb das Knie, wenn der Ball ankommt, greif unter den Oberschenkel und wirf von außen nach oben, dann stell den Fuß für den nächsten Fang wieder ab.","goodFor":"Der erste Körperwurf: Beinheben und Armzug auf genau einen Beat getimt.","alignmentCues":["Hebe das Knie vor dem Wurf, nicht währenddessen.","Wirf etwas höher, um die größere Reichweite auszugleichen."],"commonMistakes":["Sich zum Bein vorbeugen, statt das Knie zu heben.","Den nächsten Wurf überstürzen, sobald das Bein wieder unten ist."]},"behind-the-back":{"name":"Hinter dem Rücken","description":"Bei jedem sechsten Wurf schwingt die rechte Hand hinter die Hüfte und wirft den Ball über die gegenüberliegende Schulter nach oben, sodass er vorne wieder im Muster landet. Alle anderen Würfe bleiben eine normale Kaskade.","goodFor":"Blind in ein Muster werfen, das du nicht sehen kannst.","alignmentCues":["Schwing die Hand früh nach hinten, sobald der Ball landet.","Ziele über die gegenüberliegende Schulter, etwas höher als sonst."],"commonMistakes":["Zu weit nach vorne werfen, sodass der Ball vor dir landet.","Den ganzen Oberkörper verdrehen."]},"over-the-shoulder":{"name":"Über die Schulter","description":"Bei jedem sechsten Wurf schickt die rechte Hand ihren Ball hoch von vorne, nach oben und zurück über die linke Schulter. Die linke Hand schwingt hinter ihrer Hüfte herum, fängt sie blind auf und wirft dann ihren nächsten Ball von der Hüfte nach oben. Alles andere ist eine schlichte Kaskade.","goodFor":"Eine blinde Falle hinter dem Rücken, getaktet mit Gefühl statt Sehvermögen.","alignmentCues":["Wirf hoch genug, um deinen Kopf frei zu bekommen, direkt hinter der linken Schulter.","Holen Sie sich die Fanghand frühzeitig hinter die Hüfte, die Handfläche wird hochgekrempelt."],"commonMistakes":["Den Kopf drehen, um nach dem Ball zu suchen.","Zu tief werfen, damit die Kugel den Kopf oder die Schulter klemmt."]},"knee-bounce-cascade":{"name":"Knie-Bounce","description":"Bei jedem sechsten Wurf lässt die rechte Hand ihren Ball aufs rechte Knie fallen, während das Knie hochkommt. Der Ball prallt oben am Oberschenkel ab, fliegt hoch und rüber zur linken Hand, und der Fuß geht für den nächsten Fang wieder runter.","goodFor":"Auf einem Bein balancieren, während das Knie im Takt ins Muster einsteigt.","alignmentCues":["Hebe das Knie dem Ball entgegen, auf Oberschenkelhöhe.","Lass den Ball fallen, wirf ihn nicht nach unten."],"commonMistakes":["Mit dem Fuß nach dem Ball treten, sodass er nach vorn wegfliegt.","Sich zum Knie herunterbeugen, statt es anzuheben."]},"head-bounce-cascade":{"name":"Kopf-Bounce","description":"Jeder sechste Wurf geht hoch über deinen Kopf. Neige den Kopf zurück, sodass der Ball auf deiner Stirn landet, und nick ihn dann nach unten und vorn in die linke Hand. Die anderen Würfe bleiben darunter eine ganz normale Kaskade.","goodFor":"Den Ball direkt über dir verfolgen, während die Hände die Kaskade weiterlaufen lassen.","alignmentCues":["Neige den Kopf früh zurück und behalte den Ball im Blick.","Beuge die Knie leicht, um den Bounce abzufedern."],"commonMistakes":["Den Ball aktiv köpfen, statt ihn landen zu lassen.","Die Kaskade geht beim Hochschauen verloren."]},"crossed-arm-cascade":{"name":"Kaskade mit gekreuzten Armen","description":"Kreuze die Unterarme, sodass die rechte Hand auf der linken Seite ist, und lass sie gekreuzt. Jongliere aus dieser Position eine Kaskade. Die Würfe fühlen sich gespiegelt an, obwohl das Muster normal aussieht.","goodFor":"Die Gewohnheit durchbrechen, wo jede Hand ihren Platz hat.","alignmentCues":["Halte die Kreuzung an den Handgelenken, nicht an den Ellbogen.","Die Würfe gipfeln wie gewohnt auf Augenhöhe."],"commonMistakes":["Die Arme zwischen den Würfen wieder lösen.","Die Hände kollidieren beim Seitenwechsel."]},"burkes-barrage":{"name":"Re: Burke's Barrage","description":"Baut auf 423 auf. Der Ball, der als 4 geworfen wird, wird mit einer Claw gefangen und hinübergetragen, die 2 ist ein kurzes Anheben in derselben Hand, und die 3 wird mit einem Chop nach unten ins Muster geschlagen. Die Arme wirbeln dabei lebhaft umeinander.","goodFor":"Carries und Claws über einem Siteswap kombinieren, den du schon kennst.","alignmentCues":["Lerne zuerst das Timing des 423, dann kommt der Carry dazu.","Die 2 verlässt die Hand kaum."],"commonMistakes":["Die 2 so hoch werfen, dass der Rhythmus bricht.","Den Chop bei der 3 vergessen."]},"rubensteins-revenge":{"name":"Rubensteins Rache","description":"Ein Gewirr aus Carries über 52233. Ein hoher Wurf verschafft Zeit, während die Hände clawen, choppen und sich umeinander kreuzen – dann windet sich das Muster wieder in eine Kaskade zurück. Lern es langsam, eine Hand nach der anderen.","goodFor":"Ein Prunkstück, das Carries, Claws und Armkreuzen zusammen trainiert.","alignmentCues":["Die 5 ist der einzige hohe Wurf.","Lerne den Handweg zuerst ohne den hohen Ball."],"commonMistakes":["Während der Carries in Panik geraten und zu früh werfen.","Der hohe Wurf driftet nach vorne."]},"siteswap-42":{"name":"Zwei-Ball 42","description":"Zwei Bälle: Jede Hand wirft einen hohen Ball zu sich selbst und hält den anderen für einen Beat. Die hohen Bälle steigen auf jeder Seite in Säulen auf, während die Hände abwechselnd werfen. Eine ruhige Art, Selbstwürfe zu lernen.","goodFor":"Selbstwürfe auf 4er-Höhe – der Grundbaustein für Zwei in einer Hand.","alignmentCues":["Die Würfe bleiben auf ihrer eigenen Seite.","Die 2 ruhig in der Handfläche halten."],"commonMistakes":["Die Würfe driften über die Mitte.","Den gehaltenen Ball versehentlich werfen."]},"snake":{"name":"Schlange","description":"Drei Bälle als hohe kreuzende 5er geworfen, nach jedem ein leerer Beat. Die Bälle ziehen nacheinander über denselben hohen Bogen – wie eine Schlange, die über deinen Kopf gleitet.","goodFor":"Konstante hohe Würfe – ganz ohne den Druck eines vollen Fünf-Ball-Rhythmus.","alignmentCues":["Alle 5er auf gleicher Höhe.","Nutze den leeren Beat, um die Hand neu auszurichten."],"commonMistakes":["Die 5er driften nach vorne.","Aus Gewohnheit auf dem leeren Beat werfen."]},"grace":{"name":"Zahlungsfrist","description":"Ein sanfter Multiplex: Eine Hand wirft zwei Bälle gleichzeitig – einen normalen Kreuzwurf und einen kleinen Pass direkt in die andere Hand. Dann ein gehaltener Beat und zurück zur Kaskade.","goodFor":"Ein sanfter Einstieg, um zwei Bälle aus einer Hand zu werfen.","alignmentCues":["Beide Bälle gleichzeitig loslassen.","Der kleine Ball steigt kaum auf."],"commonMistakes":["Die beiden Bälle zu unterschiedlichen Zeitpunkten loslassen.","Den kleinen Ball zu hoch werfen."]},"orinoco-flow":{"name":"Orinoco-Fluss","description":"Zwei Runden 42 mit einem Kaskadenwurf hinten dran, sodass die Selbstwürfe jedes Mal die Seite wechseln. Das Muster wogt zwischen Säulen und Kaskade hin und her.","goodFor":"Sanfter Wechsel zwischen Selbstwürfen und Kreuzwürfen.","alignmentCues":["Die 4er steigen senkrecht neben dir auf.","Die 3 ist ein normaler Kaskadenwurf."],"commonMistakes":["Die 4er neigen sich nach innen.","Den Überblick über den Fünf-Wurf-Zyklus verlieren."]},"relfs-rhythm":{"name":"Relf 'scher Rhythmus","description":"Ein Selbstwurf und ein Halten, dann drei Kaskadenwürfe. Da der Zyklus ungerade ist, landet der Selbstwurf bei jedem Durchlauf in der anderen Hand.","goodFor":"Einen Trick in eine laufende Kaskade einbauen – auf beiden Seiten.","alignmentCues":["Erst Kaskade, dann die 42 einstreuen.","Halte die 4 auf ihrer eigenen Seite."],"commonMistakes":["Es immer nur mit der starken Hand machen.","Die Kaskade wird danach schneller."]},"frostbite":{"name":"Erfrierung","description":"Zwei schnelle 4er, ein schneller Pass quer rüber, dann zwei Kaskadenwürfe. Der Pass huscht unten durch, während die 4er oben schweben.","goodFor":"Schnelle Pässe mit hohen Würfen in einem Zyklus mischen.","alignmentCues":["Die 1 ist ein kurzer Flick gerade rüber.","Die 4er bleiben senkrecht."],"commonMistakes":["Die 1 loben statt sie zu passen.","Die zweite Vier vergessen."]},"siteswap-52512":{"name":"52512","description":"Zwei hohe Fünfer mit einem gehaltenen Beat dazwischen, dann ein Fünfer, ein schneller Pass und ein Halten. Das Muster mischt hohe kreuzende Würfe mit kurzen, tiefen Würfen.","goodFor":"Präzise Hoch-Tief-Kontrolle mit drei Bällen.","alignmentCues":["Alle Fünfer erreichen dieselbe Höhe.","Die Zweier bleiben in der Hand."],"commonMistakes":["Die 2er werfen.","Ungleiche Fünfer."]},"high-low-shower":{"name":"Hoch-Tief-Shower","description":"Ein Shower mit Twist: Ein Ball steigt sehr hoch, während die anderen unten flach und schnell hinübersausen. Der Rhythmus klingt wie ein Galopp.","goodFor":"Großer Höhenkontrast und schnelle Hände in einem Drei-Ball-Muster.","alignmentCues":["Der Siebener geht hoch und gerade.","Einser sind flache Pässe."],"commonMistakes":["Siebener driften nach vorn.","Einser fliegen in zu hohem Bogen."]},"siteswap-612":{"name":"612","description":"Ein hoher Eigewurf, ein schneller Pass und ein Halten. Die Sechs steigt neben dir auf derselben Seite hoch, während die anderen beiden Bälle unten die Seiten tauschen.","goodFor":"Hohe Eigewürfe im Wechsel mit schnellen, tiefen Pässen.","alignmentCues":["Die Sechs bleibt auf ihrer Seite.","Gib die 1 flach und schnell rüber."],"commonMistakes":["Die Sechs kreuzt auf die andere Seite.","Die 2 zu lange halten."]},"three-in-one":{"name":"Drei in einer Hand","description":"Drei Bälle, jongliert nur mit der rechten Hand, in hohen Säulen oder einem kleinen Fountain. Jeder Wurf ist hoch, sodass Zeit bleibt zu fangen und wieder zu werfen.","goodFor":"Einhandkontrolle und gleichmäßige Höhe.","alignmentCues":["Die Würfe gipfeln deutlich über Kopf.","Beweg die Hand in einem kleinen Kreis weiter."],"commonMistakes":["Würfe driften nach außen.","Würfe zu niedrig, um drei Bälle am Laufen zu halten."]},"columns":{"name":"Säulen","description":"Drei Bälle steigen in senkrechten Säulen auf. Beide Hände werfen ihre äußeren Bälle zusammen, dann wirft die rechte den mittleren Ball allein. Hoch, hoch, hoch, wie Kolben.","goodFor":"Erste gleichzeitige Würfe und eine Basis für viele Sync-Tricks.","alignmentCues":["Die äußeren Säulen gehen zusammen hoch.","Mittlere Säule gerade hoch aus der Mitte."],"commonMistakes":["Säulen kippen, sodass die Bälle kollidieren.","Ungleiches Timing beim Paar."]},"infinity":{"name":"Unendlichkeit","description":"Ein Säulenmuster, bei dem der einzelne Wurf rübergeht statt gerade hoch, sodass der mittlere Ball jedes Mal die Seite wechselt. Die Bälle zeichnen eine liegende Acht.","goodFor":"Ein Sync-Muster zwischen den Seiten wechseln.","alignmentCues":["Paar gerade hoch, Einzelwurf rüber.","Die Seiten wechseln sich jeden Zyklus ab."],"commonMistakes":["Der Einzelwurf geht aus Gewohnheit gerade hoch.","Das Paar driftet auseinander."]},"rainbow-cross":{"name":"Regenbogenkreuz","description":"Zwei Bälle kreuzen sich als Paar, dann steigt einer gerade durch die Mitte nach oben. Die kreuzenden Bahnen zeichnen einen Regenbogen über deinem Kopf.","goodFor":"Kreuzende Sync-Würfe ohne Kollisionen.","alignmentCues":["Ein Kreuzwurf fliegt leicht vor dem anderen.","Der Mittelwurf geht gerade nach oben."],"commonMistakes":["Die kreuzenden Bälle kollidieren.","Der Mittelwurf kippt."]},"crossunder":{"name":"Ueberstroemrohr unter Flur","description":"Jeder Wurf kreuzt: erst ein kreuzendes Paar, dann ein einzelner Kreuzwurf, der in jedem Durchlauf die Seite wechselt. Die Bälle kreisen über- und untereinander.","goodFor":"Kontrolle über durchgehend kreuzende Sync-Würfe.","alignmentCues":["Halte die Kreuzwürfe in leicht versetzten Ebenen.","Durchgehend gleiche Höhe."],"commonMistakes":["Zusammenstöße in der Mitte.","Der Einzelwurf kommt zu kurz."]},"yo-yo":{"name":"Jo-Jo","description":"Eine Hand wirft Columns, während die andere einen Ball hält und unter einem davon auf und ab bewegt, als wären die beiden Bälle mit einer Schnur verbunden.","goodFor":"Eine Illusion, die trainiert, einen gehaltenen Ball neben einer Column zu bewegen.","alignmentCues":["Der gehaltene Ball spiegelt den Column-Ball.","Die Columns bleiben senkrecht."],"commonMistakes":["Der gehaltene Ball hinkt nach.","Die Columns driften auseinander."]},"box":{"name":"Box","description":"Die Bälle zeichnen ein Quadrat. Eine Hand wirft einen Ball senkrecht nach oben, während die andere einen Ball quer hinüberwirft, dann wechseln die Rollen. Hohe Seiten, flache Ober- und Unterseite.","goodFor":"Ein klassisches Sync-Pattern, das horizontale Querwürfe trainiert.","alignmentCues":["Die Querwürfe gehen auf Handhöhe gerade hinüber.","Die Vertikalwürfe steigen senkrecht auf."],"commonMistakes":["Die Querwürfe steigen in zu hohem Bogen.","Die Columns kippen nach innen."]},"broken-box":{"name":"Kaputte Schachtel","description":"Eine Box, bei der jeder Wurf die Seite wechselt: Vertikalwurf und Querwurf wechseln ständig die Hand, sodass das Quadrat immer wieder über sich selbst klappt.","goodFor":"Schneller Rollenwechsel im Sync.","alignmentCues":["Wechsle den Vertikalwurf bei jedem Beat die Hand.","Wirf den Querwurf flach und zügig."],"commonMistakes":["Der Vertikalwurf wiederholt sich auf derselben Seite.","Der Querwurf wird überstürzt."]},"als-slide":{"name":"Al's Slide","description":"Ein hoher Kreuzwurf gepaart mit einem flachen Querwurf, dann ein Hold und noch ein hoher Kreuzwurf. Die Bälle gleiten oben und unten in einer sanft rollenden Bahn hin und her.","goodFor":"Kreuzende Sync-Würfe im Wechsel mit Querwürfen und Holds.","alignmentCues":["Die kreuzenden Vierer gipfeln gleichzeitig.","Halte die 2 still."],"commonMistakes":["Den gehaltenen Ball werfen.","Die Bälle prallen in der Mitte zusammen."]},"factory":{"name":"Fabrik","description":"Eine Hand arbeitet wie ein Fließband und trägt die Bälle auf Hüfthöhe rüber, während die andere Hand Säulen wirft. Die Bälle laufen wie in einer Maschine im Kreis.","goodFor":"Tragen und Werfen im Sync-Rhythmus koordinieren.","alignmentCues":["Die tragende Hand bewegt sich in einer weiten Schleife.","Die Vertikalen bleiben hoch."],"commonMistakes":["Die tragende Hand lässt die Bälle in die Säule fallen.","Die Säulen kippen."]},"broken-shower":{"name":"Zerbrochene Dusche","description":"Ein synchroner Shower: Die rechte Hand wirft hoch hinüber, während die linke gleichzeitig tief hinüber passt. Die Bälle kreisen in einer engen Schleife.","goodFor":"Eine synchrone Version des Shower-Loops.","alignmentCues":["Beide Hände lassen gleichzeitig los.","Hoher Bogen rechts, flacher Pass links."],"commonMistakes":["Nacheinander loslassen.","Der Pass steigt im Bogen zum hohen Ball auf."]},"crossed-arm-shower":{"name":"Shower mit gekreuzten Armen","description":"Der Shower wird mit gekreuzten Unterarmen jongliert. Die hohen Würfe kommen von der linken Körperseite, die schnellen Pässe gehen unten drunter zurück.","goodFor":"Shower-Kontrolle in einer ungewohnten Armposition.","alignmentCues":["Bleib die ganze Zeit gekreuzt.","Wirf den Pass nah am Körper."],"commonMistakes":["Die Arme werden zum Fangen entkreuzt.","Pässe zu hoch."]},"siteswap-534":{"name":"534","description":"Ein Vier-Ball-Muster aus einem kreuzenden Fünfer, einem Kaskaden-Dreier und einem Selbst-Vierer. Es fühlt sich an wie ein 423 mit vier Bällen und geht sauber in die Fountain über.","goodFor":"Der beliebteste Vier-Ball-Trick – und dein Einstieg in höhere Siteswaps.","alignmentCues":["Fünfer am höchsten, Dreier am tiefsten.","Der Vierer bleibt auf seiner Seite."],"commonMistakes":["Die Wurfhöhen gleichen sich an.","Der Dreier wird überstürzt geworfen."]},"siteswap-552":{"name":"552","description":"Zwei kreuzende Fünfer und ein Halt. Vier Bälle werden im Fünf-Ball-Rhythmus jongliert – mit einem Beat zum Durchatmen.","goodFor":"Würfe auf Fünferhöhe mit Zeit zum Erholen.","alignmentCues":["Beide Fünfer identisch.","Die 2 ruhig halten."],"commonMistakes":["Der Halt wird geworfen.","Fünfer driften nach vorn."]},"siteswap-5551":{"name":"5551","description":"Drei Fünfer hintereinander und ein schneller Pass. Ein gutes Sprungbrett zur Fünf-Ball-Kaskade.","goodFor":"Fünfer-Serien mit vier Bällen üben.","alignmentCues":["Alle Fünfer auf gleicher Höhe.","Flacher, schneller Pass für die 1."],"commonMistakes":["Fünfer werden langsam tiefer.","Die Eins lobben."]},"siteswap-55550":{"name":"55550","description":"Vier Fünfer und eine leere Hand. Eine Fünf-Ball-Kaskade mit einem Ball zu wenig – die perfekte Generalprobe für fünf Bälle.","goodFor":"Der letzte Schritt vor der Fünf-Ball-Kaskade.","alignmentCues":["Nutze die Lücke zum Durchatmen.","Fünfer konstant."],"commonMistakes":["In die Lücke werfen.","Fünfer driften."]},"siteswap-633":{"name":"633","description":"Ein hoher eigener Wurf, dann zwei Kaskadenwürfe. Der Sechser schwebt darüber, während die Kaskade darunter läuft.","goodFor":"Hohe eigene Würfe, eingewoben in einen Vier-Ball-Rhythmus.","alignmentCues":["Der Sechser bleibt über seiner eigenen Hand.","Dreier bleiben tief."],"commonMistakes":["Der Sechser driftet hinüber.","Dreier zu hoch."]},"siteswap-53":{"name":"53","description":"Eine Hand wirft hohe kreuzende Fünfer, während die andere tiefe Kaskaden-Dreier wirft. Ein halber Shower mit vier Bällen.","goodFor":"Höhenkontrolle zwischen beiden Händen.","alignmentCues":["Rechte Hand hoch, linke Hand tief.","Gleichmäßiger Rhythmus."],"commonMistakes":["Die Höhen gleichen sich an.","Dreier zu hastig."]},"wimpy":{"name":"Wimpy-Muster","description":"Vier Bälle, bei denen jedes Paar gleichzeitig kreuzt. Die Bögen wechseln auf jedem Schlag die Seite – ein weites Über-Kreuz.","goodFor":"Gleichzeitiges Kreuzen bei vier Bällen.","alignmentCues":["Eine Hand wirft ein wenig nach vorne.","Gleichzeitig loslassen."],"commonMistakes":["Kollision in der Mitte.","Das Loslassen leicht versetzen."]},"four-ball-shower":{"name":"Vier-Ball-Shower","description":"Vier Bälle im Kreis: sehr hohe Würfe von einer Hand, flache Pässe von der anderen.","goodFor":"Konstant hohe Würfe bei vier Bällen.","alignmentCues":["Siebener gerade und hoch.","Pässe schnell und flach."],"commonMistakes":["Siebener driften nach vorne.","Pässe steigen an."]},"tsunami":{"name":"Tsunami","description":"Ein hoher Siebener, ein Halten, ein eigener Vierer, ein Pass und ein hoher eigener Sechser. Höhenwellen brechen durch das Muster.","goodFor":"Fortgeschrittene Vier-Ball-Kontrolle mit gemischten Höhen.","alignmentCues":["Lerne die Würfe langsam der Reihe nach.","Siebener und Sechser gehen beide hoch."],"commonMistakes":["Höhen uneinheitlich.","Den Takt verlieren."]},"siteswap-645":{"name":"645","description":"Die Fünf-Ball-Variante von 534: ein hoher Self-Sechser, ein Self-Vierer und ein kreuzender Fünfer.","goodFor":"Ein erster Trick aus der Fünf-Ball-Kaskade.","alignmentCues":["Sechser am höchsten.","Der Vierer bleibt auf seiner Seite."],"commonMistakes":["Höhen werden flach.","Driften."]},"siteswap-744":{"name":"744","description":"Ein sehr hoher kreuzender Siebener, gefolgt von zwei Self-Vierern.","goodFor":"Einschub eines Hochwurfs bei fünf Bällen.","alignmentCues":["Siebener gerade und hoch.","Vierer senkrecht."],"commonMistakes":["Siebener driften.","Vierer kreuzen."]},"five-ball-shower":{"name":"Fünf-Ball-Shower","description":"Fünf Bälle im Kreis: turmhohe Neuner von einer Hand und flache Passes darunter zurück.","goodFor":"Höhe und Präzision am oberen Ende der Skala.","alignmentCues":["Neuner gerade und gleichmäßig.","Passes flach."],"commonMistakes":["Neuner wandern.","Passes steigen an."]},"five-ball-half-shower":{"name":"Fünf-Ball-Half-Shower","description":"Synchron geworfene, kreuzende Würfe, eine Hand höher als die andere, mit fünf Bällen.","goodFor":"Kontrolle beim synchronen Kreuzen mit fünf Bällen.","alignmentCues":["Rechts höher, links tiefer.","Gleichzeitig abwerfen."],"commonMistakes":["Höhen laufen zusammen.","Kollisionen."]},"martins-one-count":{"name":"Martins Muster","description":"Ein Multiplex: ein hoher Sechser und ein gehaltener Ball werden zusammen abgeworfen, dann ein Halten und ein kreuzender Fünfer.","goodFor":"Multiplex-Timing bei fünf Bällen.","alignmentCues":["Das Multiplex löst sich sauber auf.","Fünfer kreuzt."],"commonMistakes":["Das Multiplex teilen.","Sechser driften."]},"six-ball-fountain":{"name":"Sechs-Ball-Fontäne","description":"Drei Bälle in jeder Hand, in hohen Fontänen nebeneinander jongliert.","goodFor":"Der Sechs-Ball-Meilenstein.","alignmentCues":["Jede Hand läuft in ihrer eigenen Fontäne.","Würfe hoch und gleichmäßig."],"commonMistakes":["Fontänen driften gemeinsam.","Würfe zu niedrig."]},"club-swing":{"name":"Keulen-Einzelspin","description":"Halte eine Keule am Griff, den Knauf im Handballen. Schwing sie aus der Hüfte nach oben, sodass sie sich einmal in der Luft dreht und mit dem Griff zuerst in der anderen Hand ankommt. Wirf sie genauso zurück.","goodFor":"Du lernst den Einzelspin, aus dem jedes Keulenmuster besteht.","alignmentCues":["Hebe aus dem Ellenbogen, lass das Handgelenk die Keule drehen.","Fang den Griff auf Hüfthöhe."],"commonMistakes":["Schnippen mit dem Handgelenk, sodass die Keule zu viel Drehung bekommt.","Nach vorn werfen, sodass der Griff zu weit weg landet."]},"club-exchange":{"name":"Zwei-Keulen-Wechsel","description":"Eine Keule in jeder Hand. Wirf von rechts einen Einzelspin; auf seinem Höhepunkt wirfst du die linke Keule darunter. Fange beide an den Griffen und mach kurz Pause – dann führt die andere Hand.","goodFor":"Timing zweier drehender Keulen ohne Kollisionen.","alignmentCues":["Die zweite Keule kommt auf den Höhepunkt der ersten.","Wirf die zweite Keule innerhalb der Bahn der ersten."],"commonMistakes":["Die Keulen klappern in der Mitte aneinander.","Ungleicher Spin zwischen den Händen."]},"club-cascade":{"name":"Drei-Keulen-Kaskade","description":"Die Kaskade mit Keulen, jede dreht sich einmal. Die Würfe kommen von der Körpermitte und ziehen über die Mitte, die Griffe zeigen dabei immer zu dir.","goodFor":"Das Grundmuster des Keulenjonglierens.","alignmentCues":["Wirf aus dem Ellenbogen, halte die Handgelenke locker.","Die Keulen bleiben parallel zu deiner Brust."],"commonMistakes":["Die Keulen kippen und drehen sich seitwärts.","Zu schneller Spin – die Keule trifft den Körper."]},"club-doubles":{"name":"Keulen-Doubles","description":"Eine Drei-Keulen-Kaskade, bei der jede Keule sich zweimal in der Luft dreht. Die Würfe sind höher und langsamer, und die Keulen verschwimmen zu großen Kreisen.","goodFor":"Spinkontrolle und die Höhe, die du für vier Keulen brauchst.","alignmentCues":["Hebe mehr aus dem Arm, nicht aus dem Handgelenk.","Halte den Doppelspin flüssig und gleichmäßig."],"commonMistakes":["Das Handgelenk schnippt, die Keule bekommt zu viel Drehung.","Doubles zu niedrig werfen."]},"club-flats":{"name":"Keulen-Flats","description":"Eine Kaskade, bei der die Keulen sich gar nicht drehen. Jede Keule schwebt mit dem Griff nach unten über die Bahn, wird von einem gestreckten Handgelenk hochgedrückt und aufrecht gefangen.","goodFor":"Handgelenkskontrolle – und ein einfacher Kontrast zu drehenden Würfen.","alignmentCues":["Halte das Handgelenk fest und drück aus dem Ellenbogen.","Die Keule bleibt die ganze Zeit aufrecht."],"commonMistakes":["Unbeabsichtigte halbe Drehungen.","Zu hoch werfen, sodass die Keule wackelt."]},"club-under-leg":{"name":"Keule unter dem Bein","description":"Eine Keulen-Kaskade, bei der jeder sechste Wurf unter dem rechten Bein hindurchgeht. Hebe das Knie, schwing die Keule unter dem Oberschenkel hindurch und lass sie mit einer Drehung ins Muster zurücksteigen.","goodFor":"Der erste Körperwurf mit Keulen.","alignmentCues":["Knie früh hoch.","Gib dem Beinwurf ein wenig extra Höhe."],"commonMistakes":["Die Keule trifft das Bein.","Du beugst dich, statt das Knie zu heben."]},"club-behind-back":{"name":"Keule hinter dem Rücken","description":"Eine Keulenkaskade, bei der jeder sechste Wurf hinter der Taille geschwungen und über die gegenüberliegende Schulter ins Muster geschickt wird.","goodFor":"Blinde Keulenwürfe hinter dem Körper.","alignmentCues":["Schwing den Arm früh nach hinten.","Ziele über die gegenüberliegende Schulter."],"commonMistakes":["Die Keule landet zu weit vorne.","Du verdrehst den Oberkörper."]},"club-four-fountain":{"name":"Vier-Keulen-Fountain","description":"Zwei Keulen in jeder Hand, jede Hand wirft Doubles in ihrem eigenen Fountain. Die Keulen kreuzen nie die Mitte.","goodFor":"Der Vier-Keulen-Meilenstein.","alignmentCues":["Doubles auf der eigenen Seite.","Die Hände wechseln sich gleichmäßig ab."],"commonMistakes":["Die Keulen driften in die Mitte.","Ungleichmäßiges Drehen zwischen den Händen."]},"ring-cascade":{"name":"Drei-Ring-Kaskade","description":"Die Kaskade mit Ringen, die auf der Kante gehalten werden – wie ein Lenkrad von der Seite. Jeder Ring fliegt ohne Drehung durchs Muster, sodass die Kanten sauber durch die Luft schneiden.","goodFor":"Ein einfacher Weg, Ringe auszuprobieren und zu spüren, wie sie schweben.","alignmentCues":["Halte den Ring mit der Kante zu dir.","Lass mit geradem Handgelenk los."],"commonMistakes":["Die Ringe wackeln durch ein abgeknicktes Handgelenk.","Du wirfst sie mit der Fläche nach vorn, sodass sie Wind fangen."]},"ring-pancakes":{"name":"Ring-Pancakes","description":"Eine Ringkaskade, bei der jeder Ring am Scheitelpunkt flach kippt und für den Fang wieder auf die Kante zurückkippt – wie ein Pfannkuchen in der Pfanne.","goodFor":"Handgelenkskontrolle und eine effektvolle Ring-Einlage.","alignmentCues":["Eine schnelle Handgelenksdrehung beim Loslassen.","Fang den Ring wieder auf der Kante."],"commonMistakes":["Zu starkes Kippen.","Du wirfst zu tief, sodass der Ring nicht kippen kann."]},"ring-four-fountain":{"name":"Vier-Ring-Fountain","description":"Zwei Ringe in jeder Hand, jongliert in getrennten Fountains – die Kanten schneiden senkrecht auf und ab.","goodFor":"Vier Objekte mit einem leichten, schwebenden Prop.","alignmentCues":["Die Ringe bleiben auf der Kante.","Jede Hand wirft ihre eigene Säule."],"commonMistakes":["Die Ringe berühren sich in der Mitte.","Die Würfe driften nach vorn."]},"hoop-juggle-single":{"name":"Einzel-Hoop-Toss","description":"Halte einen Hoop an der Kante, sodass er seitlich neben dir herabhängt. Wirf ihn in einem sanften Bogen zur anderen Hand – er fliegt dabei auf der Kante und kommt auf derselben Höhe an, auf der er losgeflogen ist.","goodFor":"Erst fühlen, wie ein Reifen in voller Größe fliegt, bevor mehr dazukommt.","alignmentCues":["Halte den Reifen mit der Kante zur Brust.","Wirf aus der Schulter, nicht aus dem Handgelenk."],"commonMistakes":["Mit der Fläche nach vorn werfen, damit er ruhig davonschwebt.","Tief werfen und zugreifen."]},"hoop-juggle-exchange":{"name":"Zwei-Reifen-Wechsel","description":"Ein Reifen in jeder Hand. Wirf den rechten Reifen; wenn er den höchsten Punkt erreicht, wirf den linken darunter. Die Reifen passieren sich eng, einer vor dem anderen.","goodFor":"Zwei-Reifen-Timing und Kollisionen vermeiden.","alignmentCues":["Zweiter Reifen auf dem Höhepunkt des ersten.","Wirf den zweiten leicht davor."],"commonMistakes":["Die Reifen kollidieren.","Beide zu schnell geworfen."]},"hoop-juggle-cascade":{"name":"Drei-Reifen-Kaskade","description":"Die Kaskade mit Reifen in voller Größe. Die Hände bleiben breit, die Würfe sind groß und langsam, und jeder Reifen dreht sich mit der Kante nach vorn durch das Muster.","goodFor":"Das Grundmuster fürs Reifenjonglieren.","alignmentCues":["Arme breit, Ellbogen weich.","Jeder Reifen in derselben Ebene."],"commonMistakes":["Die Reifen driften nach vorn.","Überstürzte Würfe."]},"hoop-juggle-reverse":{"name":"Umgekehrte Reifen-Kaskade","description":"Reifen werden von außen über den Scheitel geworfen und innen gefangen – die umgekehrte Kaskade, nur größer.","goodFor":"Würfe von außen mit Reifen.","alignmentCues":["Wirf von außen über den Scheitel.","Fang nahe der Mitte."],"commonMistakes":["Die Reifen landen zu weit außen.","Ungleiche Bögen."]},"hoop-juggle-shower":{"name":"Reifen-Shower","description":"Drei Reifen im Kreis: hohe Würfe aus einer Hand und schnelle Übergaben unten zurück.","goodFor":"Höhe und Übergaben mit Reifen kontrollieren.","alignmentCues":["Hohe Würfe gerade nach oben und rüber.","Übergib nah am Körper."],"commonMistakes":["Hohe Würfe driften weg.","Die Übergaben steigen an."]},"hoop-juggle-two-in-one":{"name":"Zwei Reifen in einer Hand","description":"Zwei Reifen, nur mit der rechten Hand jongliert, steigen in Säulen neben dir auf.","goodFor":"Reifenkontrolle mit einer Hand.","alignmentCues":["Die Säulen bleiben senkrecht.","Wirf hoch, um Zeit zu gewinnen."],"commonMistakes":["Die Reifen driften nach außen.","Zu tief."]},"hoop-juggle-423":{"name":"Hoop 423","description":"Der 423-Siteswap mit drei Hoops: eine Vier als Selbstwurf, eine gehaltene Zwei und eine kreuzende Drei.","goodFor":"Siteswap-Abwechslung mit Hoops.","alignmentCues":["Die Vier bleibt auf ihrer Seite.","Halte die 2."],"commonMistakes":["Die 2 werfen.","Die Vier driftet rüber."]},"hoop-juggle-441":{"name":"Reifen 441","description":"Zwei Selbst-Vierer und eine schnelle Übergabe mit Hoops. Die Übergabe gleitet unter dem hohen Paar hindurch.","goodFor":"Schnelle Übergaben zwischen hohen Hoop-Würfen.","alignmentCues":["Vierer senkrecht.","Übergabe flach."],"commonMistakes":["Übergabe im Bogen.","Vierer driften."]},"hoop-juggle-four":{"name":"Vier-Hoop-Fontäne","description":"Zwei Hoops in jeder Hand, jongliert in zwei Fontänen nebeneinander.","goodFor":"Der Vier-Hoop-Meilenstein.","alignmentCues":["Jede Seite für sich.","Gleichmäßiger Rhythmus."],"commonMistakes":["Hoops driften zusammen.","Würfe zu niedrig."]},"hoop-juggle-under-leg":{"name":"Hoop unter dem Bein","description":"Eine Hoop-Kaskade, bei der jeder sechste Wurf unter dem angehobenen rechten Bein hindurchgeht.","goodFor":"Körperwürfe mit einem großen Prop.","alignmentCues":["Hebe das Knie hoch.","Wirf etwas höher."],"commonMistakes":["Hoop streift den Fuß.","Nach vorne gelehnt."]},"hoop-juggle-back-throw":{"name":"Hoop-Wurf hinter dem Rücken","description":"Eine Hoop-Kaskade, bei der jeder sechste Wurf hinter dem Rücken über die andere Schulter fliegt.","goodFor":"Blinde Würfe mit Hoops.","alignmentCues":["Schwing früh nach hinten.","Über die andere Schulter."],"commonMistakes":["Hoop landet vorne.","Verdrehung."]},"hoop-juggle-body-hoop":{"name":"Jonglieren beim Hüft-Hooping","description":"Lass einen Hoop an der Hüfte kreisen, während du drei weitere in einer Kaskade jonglierst. Die Hüften behalten ihren eigenen Rhythmus unter den Armen.","goodFor":"Aufmerksamkeit zwischen Hüft-Hooping und Jonglieren aufteilen.","alignmentCues":["Die Hüften treiben den Hoop an, die Arme bleiben unabhängig.","Halte die Jonglierebene vor dem Hoop an der Hüfte."],"commonMistakes":["Der Body-Hoop wird langsamer, während du dich aufs Jonglieren konzentrierst.","Die Arme sinken in den Body-Hoop ab."]},"pass-one-ball":{"name":"Passen mit einem Ball","description":"Stellt euch einander gegenüber, etwa zweieinhalb Meter entfernt. Wirf einen Ball aus deiner rechten Hand in einem sanften Bogen zur linken Hand deines Gegenübers. Dein Gegenüber reicht ihn zur eigenen rechten Hand hinüber und wirft ihn zurück zu deiner linken – und du reichst ihn wieder zu deiner rechten hinüber.","goodFor":"Höhe und Weite des Passes einüben, bevor es mit der Jonglage losgeht.","alignmentCues":["Wirf gerade hinüber, nicht überkreuz.","Der höchste Punkt liegt knapp über Kopfhöhe, auf halbem Weg zwischen euch.","Schau zu deinem Gegenüber, nicht auf den Ball in deiner Hand."],"commonMistakes":["Auf das Gesicht des Gegenübers werfen statt in einem Bogen nach oben.","Auf die rechte Hand zielen, sodass der Pass kreuzt."]},"pass-hand-across":{"name":"Passen mit zwei Bällen","description":"Je zwei Bälle. Ihr passt beide von rechts auf denselben Beat. Die linke Hand fängt den ankommenden Pass und reicht ihn gerade hinüber zur rechten, bereit für den nächsten Pass. Es gibt keine Selbstwürfe, also kommt es ganz auf das gemeinsame Timing der Pässe an.","goodFor":"Gemeinsam auf dem Beat passen, bevor die Kaskade dazukommt.","alignmentCues":["Passt zusammen: die rechten Hände auf den Beat.","Fang mit links, reich flach und schnell hinüber."],"commonMistakes":["Einer passt zu früh, sodass sich die Pässe in der Luft zu unterschiedlichen Zeitpunkten kreuzen.","Den Ball von links nach rechts werfen, statt ihn zu reichen."]},"pass-six-count":{"name":"Sechser","description":"Ihr jongliert beide eine Drei-Ball-Kaskade und passt jeden sechsten Wurf – immer von der rechten Hand zur linken deines Gegenübers. Zwischen den Pässen hast du fünf Selbstwürfe, um das Muster zu stabilisieren.","goodFor":"Das erste vollständige Passmuster: viel Zeit zwischen den Pässen.","alignmentCues":["Zähl laut mit: Pass, zwei, drei, vier, fünf, sechs.","Wirf deine Selfs genauso hoch wie den Pass.","Schau zu deinem Partner, nicht auf deine eigenen Hände."],"commonMistakes":["Die Zählung verlieren und im falschen Takt passen.","Zu kurz passen, sodass dein Partner einen Ausfallschritt machen muss."]},"pass-four-count":{"name":"Vierer","description":"Passe jeden vierten Wurf, jeden zweiten Wurf aus der rechten Hand. Pass, Self, Self, Self, dann wieder Pass. Das ist die Standard-Aufwärmübung fürs Keulenpassen und die Basis der meisten Variationen.","goodFor":"Das Passmuster für den Alltag; die meisten Tricks starten von hier.","alignmentCues":["Die rechten Hände passen gleichzeitig.","Drei Selfs, dann ist der Pass wieder dran."],"commonMistakes":["Die Selfs absacken lassen, um Zeit für den Pass zu gewinnen.","Beim Werfen die Schultern mitdrehen statt den Unterarm zu nutzen."]},"pass-three-count":{"name":"Dreier","description":"Passe jeden dritten Wurf, sodass die Pässe die Hände wechseln: rechts, dann links, dann wieder rechts. Jeder Pass aus der linken Hand geht gerade rüber zur rechten Hand deines Partners.","goodFor":"Aus beiden Händen passen und Pässe mit beiden fangen.","alignmentCues":["Pässe aus der linken Hand gehen gerade rüber, wie aus der rechten.","Halte die Passhöhe aus beiden Händen gleich."],"commonMistakes":["Ein schwacher Linkshand-Pass, der zu kurz landet.","Den linken Pass zur linken Hand deines Partners kreuzen."]},"pass-two-count":{"name":"Zweier","description":"Jeder Wurf aus der rechten Hand ist ein Pass, jeder aus der linken ein Self. Pass, Self, Pass, Self. Doppelt so viele Pässe wie im Vierer, bei gleicher Fußarbeit.","goodFor":"Schneller, gleichmäßiger Passrhythmus; der Einstieg in Muster mit sieben Objekten.","alignmentCues":["Rechte Hand passt, linke Hand wirft Selfs.","Halte den linken Self innen, unter dem ankommenden Pass."],"commonMistakes":["Die Selfs immer tiefer werden lassen.","Pässe zu nah am Körper fangen."]},"pass-left-two-count":{"name":"Zweier mit links","description":"Der Zweier gespiegelt: Jeder Wurf aus der linken Hand ist ein Pass, gerade rüber zur rechten Hand deines Partners, und die rechte Hand wirft Selfs.","goodFor":"Deine schwächere Passhand angleichen.","alignmentCues":["Linke Pässe gerade rüber, nicht kreuzen.","Gleiche Höhe und derselbe Schwung wie bei deinen Rechtshand-Pässen."],"commonMistakes":["Zu kurze Pässe aus der schwachen Hand.","Aus Gewohnheit wieder mit rechts passen."]},"pass-ultimates":{"name":"Ultimates","description":"Jeder Wurf ist ein Pass. Die rechten Hände passen gerade rüber zu den linken, die linken gerade rüber zu den rechten; niemand wirft einen Self. Die Bälle bilden einen ständigen Strom zwischen euch.","goodFor":"Passgenauigkeit und Rhythmus unter Druck.","alignmentCues":["Jeder Wurf geht rüber: rechts, links, rechts, links.","Fangen und passen in einem fließenden Schwung."],"commonMistakes":["Einen Ball festhalten und den Strom unterbrechen.","Die Pässe werden flacher, wenn das Tempo steigt."]},"club-pass-four-count":{"name":"Keulen-Vierer","description":"Der Vierer mit Keulen. Jeder Pass ist ein Single Spin, geworfen aus der rechten Hand zur linken Hand deines Partners – er kommt mit dem Griff zuerst an. Zwischen den Pässen drei Selfs mit Single Spin.","goodFor":"Der klassische Einstieg in jede Keulen-Passing-Session.","alignmentCues":["Der Pass startet neben der rechten Hüfte und schwingt gerade nach vorn.","Ein Single Spin: Der Griff sollte in der Hand deines Partners landen."],"commonMistakes":["Zu viel Spin – der Pass kommt mit dem Knopf zuerst an.","Der Pass geht quer über deinen Körper zur rechten Hand deines Partners."]},"club-pass-two-count":{"name":"Keulen-Zweier","description":"Jeder Wurf mit rechts ist ein Single Pass, jeder mit links ein Single Self. Der Grundrhythmus des Keulenpassens.","goodFor":"Gleichmäßiger Passing-Rhythmus mit Keulen.","alignmentCues":["Pass, Self, Pass, Self – auf den geraden Beats.","Halte den linken Self eng und nah am Körper."],"commonMistakes":["Der Spin geht beim linken Self verloren.","Die Pässe wandern nach links und rechts."]},"club-pass-three-count":{"name":"Keulen-Dreier","description":"Jeder dritte Wurf ist ein Pass, die Pässe kommen also abwechselnd aus beiden Händen. Pässe mit links gehen gerade hinüber zur rechten Hand deines Partners.","goodFor":"Keulenpässe mit der schwachen Hand.","alignmentCues":["Derselbe Schwung aus beiden Händen.","Rechts, dann links, dann rechts – zähl es laut durch."],"commonMistakes":["Zu wenig Spin bei Pässen mit der linken Hand.","Den Körper beim Pass mit links mitdrehen."]},"club-pass-doubles":{"name":"Keulen-Vierer mit Doubles","description":"Ein Vierer, bei dem jeder Pass ein Double Spin ist – höher geworfen, damit er einen Beat später ankommt. Damit Platz entsteht, hält die linke Hand ihre Keule nach dem Pass einen Beat lang, statt zu werfen.","goodFor":"Der Double Pass – der erste Schritt zum Passen mit sieben Keulen.","alignmentCues":["Ein Double Pass ist höher und langsamer: zwei volle Drehungen.","Halte die linke Keule über den Pass hinweg und mach dann weiter."],"commonMistakes":["Der Double wird so schnell wie ein Single geworfen und überdreht dadurch.","Die linke Keule wird geworfen statt gehalten."]},"club-pass-ultimates":{"name":"Keulen-Ultimates","description":"Jeder Wurf ist ein Single Pass mit Keulen, abwechselnd rechts und links. Sechs Keulen strömen ohne Selfs zwischen euch hin und her.","goodFor":"Passgenauigkeit mit Keulen im vollen Tempo.","alignmentCues":["Fangen und passen in einem Schwung.","Gerade Pässe: rechts nach links, links nach rechts."],"commonMistakes":["Die Pässe driften in die Mitte und kollidieren.","Eine Keule wird gehalten und der Fluss bricht ab."]},"club-pass-seven-doubles":{"name":"Crossing Doubles mit sieben Keulen","description":"Sieben Keulen zwischen euch. Deine rechte Hand passt bei jedem zweiten Wurf ein Crossing Double zur rechten Hand deines Partners, und dessen linke Hand antwortet einen Wurf später mit einem Crossing Double zu deiner linken Hand. Singles füllen die Lücken.","goodFor":"Ein erstes Muster mit sieben Keulen, aufgebaut auf Doubles.","alignmentCues":["Deine Doubles kreuzen zur rechten Hand deines Partners.","Fang das Double der anderen Person in deiner Linken, direkt nach deinem eigenen Pass."],"commonMistakes":["Gerade Pässe statt sich kreuzender Pässe.","Doubles zu niedrig für zwei volle Drehungen."]},"staff-wheel-spin":{"name":"Zwei-Hand-Rad-Spin","description":"Halte den Staff in der Mitte mit beiden Händen, Handflächen nach unten, auf Brusthöhe. Drehe ihn an deiner Seite wie ein Rad, indem du die Rotation zwischen den Händen weitergibst und ihn neben deinem Körper hältst.","goodFor":"Der erste Staff-Spin; baut Griff und Handgelenksrotation auf.","alignmentCues":["Der Staff bleibt parallel zu deinem Körper, ohne zu kippen.","Sanfter Griff: lass ihn durch die Finger rollen."],"props":["Staff"],"commonMistakes":["Zu fest zudrücken, sodass der Spin stockt.","Die Ebene nach vorne kippen."]},"staff-front-spin":{"name":"Front-Windmill","description":"Drehe den Staff vor dir wie einen Propeller, in der Wall Plane, und gib ihn sanft von Hand zu Hand um sein Zentrum weiter.","goodFor":"Fügt die Wall Plane und das Hand-über-Hand-Weitergeben hinzu.","props":["Staff"]},"staff-figure-8":{"name":"Achter-Weave","description":"Drehe den Staff in der Wheel Plane auf deiner rechten Seite, kreuze ihn dann auf deine linke Seite und drehe dort, wobei du eine Acht vor dir ziehst.","goodFor":"Verbindet beide Körperseiten; das Rückgrat des Staff Flow.","alignmentCues":["Wechsle die Seiten, wenn die Enden den Boden passieren.","Drehe den Oberkörper mit jeder Seite ein wenig mit."],"props":["Staff"]},"staff-pass-through":{"name":"Durchgehend","description":"Drehe in der Wall Plane, aber lass bei jeder halben Umdrehung los: Eine Hand lässt den Staff los und die andere fängt ihn in der Mitte, sodass der Staff zwischen deinen Händen durchgeht.","goodFor":"Lehrt das Timing von Loslassen und Fangen.","props":["Staff"]},"staff-one-hand-spin":{"name":"Einhand-Spin","description":"Drehe den Staff vor dir mit einer Hand und rolle ihn über den Handrücken und durch die Finger. Übe beide Hände.","goodFor":"Finger- und Handgelenkskraft; macht die andere Hand für Tricks frei.","props":["Staff"]},"staff-helicopter":{"name":"Overhead-Helicopter","description":"Hebe den Staff über den Kopf und drehe ihn flach in der Floor Plane mit einer Hand, wie Hubschrauberrotorblätter.","goodFor":"Führt die Floor Plane ein.","props":["Staff"]},"staff-butterfly":{"name":"Schmetterling","description":"Drehe vor dir, falte den Staff dann hinter deine Schulter und wieder heraus, wobei du auf jeder Seite vorne und hinten wie Flügel abwechselst.","goodFor":"Schultermobilität und ein fließender Übergang von vorne nach hinten.","props":["Staff"]},"staff-behind-back-pass":{"name":"Pass hinter dem Rücken","description":"Gib den sich drehenden Staff am unteren Punkt des Spins hinter deinem Rücken von einer Hand in die andere und bring ihn dann nach vorne.","goodFor":"Body Wraps und Show-Pässe.","props":["Staff"]},"staff-isolation":{"name":"Staff-Isolation","description":"Halte den Staff nahe an einem Ende und kreise deine Hand um die Mitte des Staffs, sodass die Mitte scheinbar an derselben Stelle in der Luft bleibt, während sich der Staff um sie dreht.","goodFor":"Illusionsarbeit und präzise Handwege.","props":["Staff"]},"staff-antispin-flower":{"name":"Vierblättriger Antispin","description":"Kreise deine Hand in eine Richtung, während der Staff dreimal so schnell in die andere Richtung spinnt, sodass der Staff eine vierblättrige Blume zeichnet.","goodFor":"Die ikonische VTG-Blume; tiefe Timing-Kontrolle.","props":["Staff"]},"staff-neck-roll":{"name":"Nackenrolle","description":"Lass den Staff auf deinen Schulterrücken fallen und rolle ihn über den Nacken zur anderen Hand. Fang langsam an mit einem gepolsterten Staff.","goodFor":"Contact Staff: Der Staff bewegt sich am Körper ohne Hände.","avoidIf":["Nackenschmerzen."],"props":["Staff"]},"staff-reverse-wheel":{"name":"Rückwärtsdrehen des Rades","description":"Der Wheel Spin dreht in die andere Richtung: Das vordere Ende des Staffs steigt auf und läuft über den Scheitel zurück. Beide Hände bleiben in der Mitte und rollen ihn durch, genau wie beim Vorwärtsspin.","goodFor":"Beide Spin-Richtungen ausbalancieren, damit jede spätere Bewegung in beide Richtungen funktioniert.","alignmentCues":["Dasselbe flache Rad neben dir, nur die Richtung ändert sich.","Führe mit den Knöcheln, während sie nach hinten abrollen."],"props":["Staff"],"commonMistakes":["Die Ebene driftet über deinen Körper.","Du wechselst unbemerkt zurück zum Vorwärtsspin."]},"staff-reverse-front-spin":{"name":"Rückwärtsdrehung vorne","description":"Ein beidhändiger Front Spin, der in die andere Richtung herumläuft. Das obere Ende fällt nach rechts statt nach links.","goodFor":"Beide Richtungen des Front Spins, bevor es mit Passes oder Weaves weitergeht.","alignmentCues":["Halte den Staff flach vor der Brust.","Die Hände wechseln auf dieselbe Weise, nur umgekehrt."],"props":["Staff"],"commonMistakes":["Die Enden kippen zu dir hin.","Du verlierst den Rhythmus beim Handwechsel."]},"staff-one-hand-wheel":{"name":"Einhand-Wheel Spin","description":"Drehe den Staff mit nur einer Hand neben dir in der Wheel-Ebene, indem du ihn über den Handrücken und durch die Finger rollst.","goodFor":"Einhandkontrolle neben dem Körper: die Basis für Wheel-Isolationen und Double Staff.","alignmentCues":["Der Staff zieht knapp außerhalb der Hüfte vorbei.","Der Ellbogen bleibt nah an den Rippen."],"props":["Staff"],"commonMistakes":["Das Ende streift das Bein.","Das Handgelenk blockiert."]},"staff-wheel-pass":{"name":"Spin-Rad-Pass","description":"Ein Wheel Spin, der bei jeder halben Drehung die Hand wechselt. Jede Hand nimmt den Staff auf, wenn er waagerecht liegt, trägt ihn herum und gibt ihn weiter.","goodFor":"Flüssige Handwechsel neben dem Körper.","alignmentCues":["Fang ihn waagerecht.","Die freie Hand wartet nah daneben."],"props":["Staff"],"commonMistakes":["Du greifst zu, bevor der Staff waagerecht liegt.","Die Ebene wandert bei jedem Wechsel."]},"staff-two-hand-helicopter":{"name":"Zweihand-Helicopter","description":"Der Staff dreht sich flach über deinem Kopf, beide Hände halten ihn, eine Hand überkreuzt die andere wie bei einem Rotor.","goodFor":"Ein sanfter erster Blick auf die Bodenebene.","alignmentCues":["Arme locker, der Staff knapp über dem Kopf.","Die Hände überkreuzen sich vor dem Gesicht."],"props":["Staff"],"commonMistakes":["Der Staff kippt nach vorn.","Die Schultern ziehen sich hoch."]},"staff-overhead-pass":{"name":"Überkopf-Wechsel","description":"Der Helicopter wird über dem Kopf von Hand zu Hand weitergegeben, jede Hand trägt ihn eine halbe Drehung lang.","goodFor":"Handwechsel in der Bodenebene.","alignmentCues":["Wechsel, wenn der Staff nach vorn und hinten zeigt.","Halte die Ellenbogen locker."],"props":["Staff"],"commonMistakes":["Der Staff fällt hinter den Kopf.","Zu früh zugreifen."]},"staff-one-hand-reverse":{"name":"Einhand-Reverse-Spin","description":"Ein Einhand-Frontspin in die Gegenrichtung, der zuerst über die Daumenseite rollt.","goodFor":"Einhand-Kontrolle in beide Richtungen.","alignmentCues":["Gleiche Ebene, gleiches Tempo, umgekehrt.","Die Finger entspannen sich, während der Staff rollt."],"props":["Staff"],"commonMistakes":["Das Handgelenk verkrampft.","Der Spin wird auf einer Hälfte langsamer."]},"staff-reverse-helicopter":{"name":"Rückwärtshubschrauber","description":"Der Einhand-Helicopter dreht über dem Kopf in die andere Richtung.","goodFor":"Überkopf in beide Richtungen.","alignmentCues":["Der Staff bleibt waagerecht.","Die Hand bleibt über der Stirn."],"props":["Staff"],"commonMistakes":["Kippt nach vorn.","Der Arm wird ganz durchgestreckt."]},"staff-extension":{"name":"Erweiterung","description":"Halte den Staff nahe einem Ende und lass ihn einen großen Kreis um deine Hand ziehen, die sich kaum bewegt. Das ferne Ende zeichnet einen großen Ring vor dir.","goodFor":"Große Formen und das Rollen aus dem Handgelenk, das du für Isolationen brauchst.","alignmentCues":["Die Hand ist der Drehpunkt des Kreises.","Drehe aus dem Handgelenk, schwing nicht mit dem Arm."],"props":["Staff"],"commonMistakes":["Schwingen aus der Schulter.","Der Kreis flacht zu einem Oval ab."]},"staff-wheel-extension":{"name":"Rad-Extension","description":"Eine Extension neben dem Körper: Der Staff schwingt auf Hüfthöhe ein großes Rad um die Hand.","goodFor":"Große Kreise in der Rad-Ebene.","alignmentCues":["Halte den Kreis außerhalb des Beins.","Handgelenk dreht, Arm bleibt ruhig."],"props":["Staff"],"commonMistakes":["Der Staff streift den Fuß.","Der Körper lehnt sich vom Staff weg."]},"staff-floor-extension":{"name":"Overhead-Extension","description":"Eine flache Extension über dem Kopf: Der Staff schwingt wie ein langes Rotorblatt um die erhobene Hand.","goodFor":"Reichweite über Kopf und eine dramatische Form in der Boden-Ebene.","alignmentCues":["Die Hand über dem Kopf.","Das Blatt bleibt waagerecht."],"props":["Staff"],"commonMistakes":["Der Staff sinkt hinten ab.","Der Arm driftet nach vorne."]},"staff-wheel-isolation":{"name":"Rad-Isolation","description":"Die Isolation neben dem Körper: Der Mittelpunkt des Staffs bleibt fix, während die Hand um ihn kreist.","goodFor":"Isolationskontrolle in einer zweiten Ebene.","alignmentCues":["Such dir einen Punkt neben deiner Hüfte als Mittelpunkt.","Die Hand bewegt sich in einem kleinen Kreis."],"props":["Staff"],"commonMistakes":["Der Mittelpunkt wandert.","Die Ebene kippt."]},"staff-floor-isolation":{"name":"Overhead-Isolation","description":"Eine Isolation flach über dem Kopf, bei der der Staff um einen fixen Punkt schwenkt, während die Hand kreist.","goodFor":"Overhead-Isolationen.","alignmentCues":["Fixer Punkt über dir.","Kleiner Handkreis."],"props":["Staff"],"commonMistakes":["Der Mittelpunkt driftet.","Der Handkreis wird größer."]},"staff-isolation-pass":{"name":"Isolations-Übergabe","description":"Eine Isolation, die bei jeder halben Drehung zwischen den Händen übergeben wird, sodass der fixe Punkt stillsteht, während die Hände wechseln.","goodFor":"Isolationskontrolle mit beiden Händen.","alignmentCues":["Übergabe am tiefsten Punkt des Kreises.","Halte den Mittelpunkt während der Übergabe fix."],"props":["Staff"],"commonMistakes":["Der Mittelpunkt springt bei der Übergabe.","Hände stoßen zusammen."]},"staff-antispin-3":{"name":"Drei-Blütenblatt-Antispin","description":"Die Hand kreist in die eine Richtung, während der Staff in die andere spinnt – zusammen malen sie eine Blume mit drei Blütenblättern.","goodFor":"Die erste Antispin-Blume.","alignmentCues":["Handkreis langsam und rund.","Der Staff spinnt dagegen."],"props":["Staff"],"commonMistakes":["Blütenblätter ungleichmäßig.","Der Handkreis kollabiert."]},"staff-antispin-5":{"name":"Fünf-Blütenblatt-Antispin","description":"Eine feinere Antispin-Blume mit fünf Blütenblättern – die Hand kreist langsamer, entgegen der Spinrichtung.","goodFor":"Präzises Antispin-Timing.","alignmentCues":["Zähl die Blütenblätter.","Die Hand bewegt sich langsam."],"props":["Staff"],"commonMistakes":["Blütenblätter verschmelzen.","Hastige Hand."]},"staff-wheel-antispin":{"name":"Wheel-Antispin","description":"Eine Antispin-Blume, die seitlich am Körper in der Wheel-Ebene gemalt wird.","goodFor":"Blumen in einer zweiten Ebene.","alignmentCues":["Aufrechte Ebene.","Blütenblätter gleichmäßig."],"props":["Staff"],"commonMistakes":["Die Ebene kippt.","Blütenblätter wandern nach vorn."]},"staff-floor-antispin":{"name":"Überkopf-Antispin","description":"Eine Antispin-Blume, die flach über dem Kopf gemalt wird.","goodFor":"Blumen über dem Kopf.","alignmentCues":["Waagerechte Ebene.","Hand über dem Kopf."],"props":["Staff"],"commonMistakes":["Es kippt.","Blütenblätter ungleichmäßig."]},"staff-inspin-3":{"name":"Drei-Blütenblatt-Inspin","description":"Die Hand kreist in dieselbe Richtung wie der Spin, nur langsamer – der Staff malt dabei drei Blütenblätter, die nach innen zeigen.","goodFor":"Die sanfteste Blume zum Lernen.","alignmentCues":["Hand und Staff drehen sich in dieselbe Richtung.","Handkreis weit und langsam."],"props":["Staff"],"commonMistakes":["Die Hand beschleunigt, um mit dem Staff gleichzuziehen.","Petals ungleichmäßig."]},"staff-inspin-4":{"name":"Vier-Petal-Inspin","description":"Eine Inspin-Blume mit vier nach innen gerichteten Petals.","goodFor":"Mehr Inspin-Kontrolle.","alignmentCues":["Zähle vier Petals.","Ruhige Hand."],"props":["Stab"],"commonMistakes":["Petals verschmelzen.","Die Hand wandert."]},"staff-wheel-inspin":{"name":"Wheel-Inspin","description":"Ein Drei-Petal-Inspin, der neben dem Körper gezeichnet wird.","goodFor":"Inspins in der Wheel-Plane.","alignmentCues":["Vertikale Ebene.","Langsame Hand."],"props":["Stab"],"commonMistakes":["Kippt.","Streift das Bein."]},"staff-reverse-figure-8":{"name":"Reverse Achter","description":"Die Figure 8 andersherum: Der Stab steigt vorne auf und fällt hinten auf beiden Seiten ab.","goodFor":"Beide Richtungen des Weave.","alignmentCues":["Kreuzung vor dem Körper.","Jede Seite vertikal."],"props":["Stab"],"commonMistakes":["Ebene bricht an der Kreuzung ein.","Oberkörper steif."]},"staff-front-weave":{"name":"Vordere Webart","description":"Ein Front Spin, der bei jeder Drehung von einer Körperseite zur anderen driftet, während die Brust mitdreht.","goodFor":"Den Spin quer über den Körper bewegen.","alignmentCues":["Die Brust folgt dem Stab.","Der Spin bleibt dir zugewandt."],"props":["Stab"],"commonMistakes":["Füße drehen sich mit.","Ebene kippt an der Kreuzung."]},"staff-overhead-weave":{"name":"Überkopf-Weave","description":"Ein zweihändiger Helicopter, der bei jeder Drehung von einer Kopfseite zur anderen schwingt.","goodFor":"Weaven in der Floor-Plane.","alignmentCues":["Blades durchgehend auf gleicher Höhe.","Der Oberkörper dreht sich mit dem Stab."],"props":["Stab"],"commonMistakes":["Sinkt auf einer Seite ab.","Kopf im Weg."]},"staff-fountain":{"name":"Fontäne","description":"Ein Split-Time-Weave in der Rad-Ebene: Die Enden sprühen abwechselnd links und rechts nach oben und darüber wie Wasser aus einem Brunnen.","goodFor":"Split-Timing neben dem Körper.","alignmentCues":["Die Enden steigen abwechselnd links und rechts auf.","Halte das Kreuzen zügig."],"props":["Staff"],"commonMistakes":["Fällt in einen schlichten Achter zusammen.","Ebene kippt."]},"staff-reel":{"name":"Rolle","description":"Ein Achter, bei dem die Hand bei jedem Kreuzen wechselt und der Staff von einer Seite zur anderen spult.","goodFor":"Weaves und Passes kombinieren.","alignmentCues":["Pass beim Kreuzen.","Jede Seite aufrecht."],"props":["Staff"],"commonMistakes":["Zu früh greifen.","Oberkörper steif."]},"staff-wall-wheel-hybrid":{"name":"Wand-Rad-Hybrid","description":"Mit jeder Umdrehung wechselt der Spin zwischen der Wand-Ebene vor dir und der Rad-Ebene neben dir – jeweils dann, wenn der Staff aufrecht steht.","goodFor":"Ebenenwechsel ohne Pause.","alignmentCues":["Wechsle, wenn der Staff senkrecht nach oben zeigt.","Handgelenk dreht ein Viertel."],"props":["Staff"],"commonMistakes":["Wechsel bei waagerechtem Staff.","Tempoverlust beim Wechsel."]},"staff-floor-wall-hybrid":{"name":"Wand-Boden-Hybrid","description":"Der Spin läuft abwechselnd vor deinem Körper und über deinem Kopf – und wechselt jedes Mal, wenn der Staff waagerecht liegt.","goodFor":"Front-Spins und Helicopters verbinden.","alignmentCues":["Wechsle, wenn der Staff waagerecht liegt.","Hebe den Arm flüssig an."],"props":["Staff"],"commonMistakes":["Wechsel bei senkrechtem Staff.","Ellbogen blockiert."]},"staff-floor-wheel-hybrid":{"name":"Boden-Rad-Hybrid","description":"Ein Helicopter, der bei jeder Umdrehung in die Rad-Ebene neben dir abtaucht und wieder hochsteigt.","goodFor":"Das komplette Set an Ebenenwechseln.","alignmentCues":["Arm hebt und senkt sich flüssig.","Ebenen sauber."],"props":["Staff"],"commonMistakes":["Mittlere Ebene matschig.","Tempo lässt nach."]},"staff-under-leg-pass":{"name":"Pass unter dem Bein","description":"Ein Pass-Through, der bei jedem zweiten Pass unter das angehobene rechte Bein taucht.","goodFor":"Die Beine ins Passing einbauen.","alignmentCues":["Hebe das Knie zum Staff.","Bleib aufrecht.","Kommen Sie wieder hoch, sobald der Stock das Bein passiert hat."],"props":["Staff"],"commonMistakes":["Oberkörper beugt sich vor.","Pass unter dem Bein wird überstürzt.","Eile beim Passieren unter dem Bein."]},"staff-reverse-behind-back":{"name":"Reverse Pass hinter dem Rücken","description":"Der Pass hinter dem Rücken läuft in die andere Richtung um den Körper, der Spin dreht rückwärts.","goodFor":"Den Staff in beide Richtungen um den Körper führen.","alignmentCues":["Die Hand hinten wartet tief.","Lass den Spin hinten weiterlaufen."],"props":["Staff"],"commonMistakes":["Ebene geht hinter dem Rücken verloren.","Der Spin bleibt stehen."]},"staff-fishtail":{"name":"Fishtail","description":"Der Staff schaukelt über die offene Handfläche hin und her wie ein Fisch, der mit dem Schwanz wedelt – ohne sich je ganz zu drehen.","goodFor":"Kontrolle mit offener Hand und Wechsel der Spinrichtung.","alignmentCues":["Pivot zwischen Daumen und Fingern.","Kleine Schnipser aus dem Handgelenk drehen den Schwung um."],"props":["Staff"],"commonMistakes":["Zu fest greifen.","Schwünge werden zu groß."]},"staff-wheel-fishtail":{"name":"Rad-Fishtail","description":"Ein Fishtail seitlich am Körper in der Wheel-Plane.","goodFor":"Fishtails in einer zweiten Ebene.","alignmentCues":["Aufrechte Ebene.","Offene Hand."],"props":["Staff"],"commonMistakes":["Staff kippt.","Greifen."]},"staff-steering-wheel":{"name":"Lenkrad","description":"Dreh den Staff Hand über Hand mit flachen, offenen Handflächen, als würdest du ein großes Lenkrad vor dir drehen.","goodFor":"Entspannte Hände und Kontakt mit offener Handfläche.","alignmentCues":["Handflächen flach, Finger weich.","Oben Hand über Hand wechseln."],"props":["Staff"],"commonMistakes":["Greifen statt führen.","Ellenbogen gehen nach außen."]},"staff-palm-spin":{"name":"Palm Spin","description":"Balanciere die Mitte des Stabs auf der flachen, angehobenen Handfläche und lass ihn dort wie einen Propeller drehen.","goodFor":"Balance und leichter Kontakt über Kopf.","alignmentCues":["Handfläche flach und waagerecht.","Kleine Kreise halten ihn in Bewegung."],"props":["Stab"],"commonMistakes":["Handfläche kippt.","Drücken statt leicht anzustoßen."]},"staff-hand-roll":{"name":"Handrolle","description":"Der Stab rollt über den Handrücken der offenen Hand und um den Daumen, ohne dass du ihn greifst.","goodFor":"Die erste echte Contact-Roll.","alignmentCues":["Hand offen und locker.","Lass den Stab die Arbeit machen."],"props":["Stab"],"commonMistakes":["Finger schließen sich.","Hand bewegt sich zu viel."]},"staff-forearm-roll":{"name":"Unterarmrolle","description":"Gib die Drehung auf den Unterarm ab, lass den Stab darüber weiterdrehen und nimm ihn dann wieder in den Hand Spin auf.","goodFor":"Eine Drehung auf den Arm übergeben und zurück.","alignmentCues":["Unterarm waagerecht und ruhig.","Öffne die Hand, wenn er ankommt."],"props":["Stab"],"commonMistakes":["Unterarm kippt.","Zu früh zugreifen."]},"staff-elbow-roll":{"name":"Ellenbogenrolle","description":"Die Drehung wandert in die Beuge des angewinkelten Ellenbogens, dreht dort mit angehobener Hand und kehrt in die Hand zurück.","goodFor":"Fortgeschrittene Contact-Kontrolle.","alignmentCues":["Unterarm senkrecht.","Ellenbogen ruhig halten."],"props":["Stab"],"commonMistakes":["Ellenbogen sinkt ab.","Stab rutscht ab."]},"staff-shoulder-roll":{"name":"Schulterrolle","description":"Ein Wheel Spin wird auf die Schulter gehoben und dreht dort neben dem Kopf, bevor er zurück in die Hand fällt.","goodFor":"Contact-Rolls hoch am Körper.","alignmentCues":["Schulter leicht angehoben.","Kopf neigt sich weg."],"props":["Stab"],"commonMistakes":["Kopf im Weg.","Schulter sinkt."]},"staff-chest-roll":{"name":"Brustrolle","description":"Der Staff rollt waagerecht über die Brust von einer Hand zur anderen und dann wieder zurück.","goodFor":"Körperkontakt an der Vorderseite.","alignmentCues":["Brust angehoben.","Staff bleibt waagerecht."],"props":["Staff"],"commonMistakes":["Brust sackt ein.","Staff kippt."]},"staff-angel-roll":{"name":"Engelsrolle","description":"Die Arme werden weit gespreizt, und der Staff rollt über die Rückseite der Schultern und an beiden Armen entlang von einer Hand zur anderen.","goodFor":"Eine Contact-Rolle als Showstück.","alignmentCues":["Arme waagerecht, Handflächen nach oben.","Schulterblätter zusammen."],"props":["Staff"],"commonMistakes":["Arme sinken.","Kopf nach vorn."]},"staff-toss":{"name":"Staffwurf","description":"Einen Einhand-Spin waagerecht loslassen, ihn einmal in der Luft drehen lassen und in denselben Spin wieder fangen.","goodFor":"Einen rotierenden Staff loslassen und fangen.","alignmentCues":["Loslassen, wenn er waagerecht ist.","In der Mitte fangen."],"props":["Staff"],"commonMistakes":["Wurf nach vorn.","An einem Ende fangen."]},"staff-double-toss":{"name":"Doppelwurf","description":"Ein höherer Wurf mit zwei vollen Drehungen vor dem Fangen.","goodFor":"Spin- und Höhenkontrolle in der Luft.","alignmentCues":["Mehr Höhe, gleicher Spin.","Augen auf die Mitte."],"props":["Staff"],"commonMistakes":["Zu viel Spin.","Driftet nach vorn."]},"staff-flat-toss":{"name":"Flacher Wurf","description":"Wirf den Helicopter gerade nach oben, sodass er sich in der Luft flach dreht, und fang ihn über dem Kopf.","goodFor":"Wurf in der Bodenebene.","alignmentCues":["Waagerecht loslassen.","Über dem Kopf fangen."],"props":["Staff"],"commonMistakes":["Kippt beim Loslassen.","Hinter dem Körper werfen."]},"double-staff-same-time":{"name":"Double Staff gleichzeitig","description":"Ein kurzer Staff in jeder Hand, beide drehen sich vor dir in dieselbe Richtung und im gleichen Takt.","goodFor":"Das erste Double-Staff-Pattern.","alignmentCues":["Staffs nebeneinander, einer leicht davor.","Beide Hände gleich schnell."],"props":["zwei kurze Staffs"],"commonMistakes":["Staffs kollidieren.","Eine Hand hinkt hinterher."]},"double-staff-split-time":{"name":"Double Staff versetzt","description":"Beide Staffs drehen in dieselbe Richtung, aber einer hängt eine Vierteldrehung hinten nach – steht einer aufrecht, ist der andere waagerecht.","goodFor":"Unabhängiges Timing zwischen den Händen.","alignmentCues":["Einer aufrecht, einer waagerecht.","Stetiger Versatz."],"props":["zwei kurze Staffs"],"commonMistakes":["Fällt zurück ins Same Time.","Kollision."]},"double-staff-wheels":{"name":"Doppelstab-Räder","description":"Je ein Wheel auf jeder Körperseite, beide drehen gemeinsam nach vorn.","goodFor":"Beide Staffs seitlich am Körper.","alignmentCues":["Jedes Wheel außen an der Hüfte.","Gleiches Tempo."],"props":["zwei kurze Staffs"],"commonMistakes":["Wheels kippen nach innen.","Hände driften auseinander."]},"double-staff-split-wheels":{"name":"Double Staff Wheels versetzt","description":"Wheels auf beiden Seiten, um eine Vierteldrehung versetzt – wie Beine beim Gehen.","goodFor":"Split Time seitlich am Körper.","alignmentCues":["Einer oben, einer waagerecht.","Stetiger Versatz."],"props":["zwei kurze Staffs"],"commonMistakes":["Gleichen sich an.","Kippen."]},"double-staff-windmill":{"name":"Doppelstab Windmühle","description":"Wheels auf beiden Seiten drehen in entgegengesetzte Richtungen – wie eine Windmühle von der Seite gesehen.","goodFor":"Entgegengesetzte Richtungen in den beiden Händen.","alignmentCues":["Einer vorwärts, einer rückwärts.","Gleichmäßiges Tempo."],"props":["zwei kurze Staffs"],"commonMistakes":["Beide driften in dieselbe Richtung.","Ungleichmäßiges Tempo."]},"double-staff-reverse":{"name":"Doppelstab Rückwärts","description":"Split-Time-Frontspins, beide Stäbe laufen rückwärts.","goodFor":"Beide Richtungen mit zwei Stäben.","alignmentCues":["Halte den Offset.","Beide in derselben Ebene."],"props":["zwei kurze Stäbe"],"commonMistakes":["Zusammenprallen.","Den Offset verlieren."]},"double-staff-helicopters":{"name":"Double Staff Helikopter","description":"Je ein Helicopter über jeder Schulter, beide drehen im Gleichtakt.","goodFor":"Double Staff über Kopf.","alignmentCues":["Beide Stäbe waagerecht.","Arme locker."],"props":["zwei kurze Stäbe"],"commonMistakes":["Stäbe berühren sich.","Arme werden müde und sinken."]},"double-staff-isolations":{"name":"Double Staff Isolationen","description":"Gleichzeitig eine Isolation in jeder Hand, beide Zentren nebeneinander fixiert.","goodFor":"Zwei Isolationen gleichzeitig.","alignmentCues":["Zwei Fixpunkte.","Hände kreisen zusammen."],"props":["zwei kurze Stäbe"],"commonMistakes":["Zentren driften.","Eine Hand hinkt nach."]},"hoop-waist":{"name":"Taillen-Hooping","description":"Steh mit einem Fuß leicht vor dem anderen. Halte den Hoop an deinen unteren Rücken, wirf ihn um deine Taille und stoße den Bauch nach vorne und hinten (nicht im Kreis) jedes Mal, wenn der Hoop vorne vorbeikommt.","goodFor":"Die erste Hoop-Fähigkeit; baut den Kernrhythmus auf.","modifications":["Nimm einen größeren, schwereren Hoop: Er dreht sich langsamer."],"alignmentCues":["Schwinge vorne und hinten, nicht im Kreis.","Drücke den Hoop, wenn er an deinem Bauch vorbeikommt."],"props":["Hoop"],"commonMistakes":["Die Hüften wie ein Hula-Tänzer kreisen lassen.","Ein Hoop, der zu klein oder zu leicht ist."]},"hoop-hand-spin":{"name":"Hand-Spin","description":"Halte den Hoop vor dir mit der Hand darin, Daumen nach oben. Stoße ihn in einen Spin um das Handnetz, wobei der Hoop flach vor dir bleibt.","goodFor":"Off-Body-Hoop-Grundlage.","props":["Hoop"]},"hoop-chest":{"name":"Brust-Hooping","description":"Hebe deine Arme über den Kopf und hoope um die Brust, wobei du den Brustkorb vorne und hinten schwingst und die Hüften ruhig hältst.","goodFor":"Isoliert den Brustkorb und baut Oberkörperkontrolle auf.","props":["Hoop"]},"hoop-lasso":{"name":"Lasso","description":"Halte den Hoop über dem Kopf und kreise ihn flach über deinem Kopf wie ein Lasso, wobei der Hoop um deine Hand spinnt.","goodFor":"Bodenebenen-Kontrolle über dem Kopf.","props":["Hoop"]},"hoop-wedgie":{"name":"Wedgie","description":"Spinne den Hoop in der Wandebene und fange ihn in der Mulde zwischen Daumen und Fingern, lass ihn dort rollen und schaukeln, bevor du weiterspinnst.","goodFor":"Griffkontrolle und ein sanfter Übergangshalt.","props":["Hoop"]},"hoop-knees":{"name":"Knie-Hooping","description":"Mit geschlossenen Füßen halte den Hoop um deine Knie in Bewegung, indem du die Knie nach vorne und hinten stößt.","goodFor":"Hula-Hoop für den Unterkörper und Escalator üben.","props":["Hoop"]},"hoop-pass":{"name":"Hand-zu-Hand-Pass","description":"Lass den Hoop vor dir kreisen und gib ihn bei jeder Umdrehung von einer Hand in die andere, während die Ebene stabil bleibt.","goodFor":"Links off-body Tricks auf beiden Seiten.","props":["Hoop"]},"hoop-isolation":{"name":"Hoop-Isolation","description":"Bewege deine Hand um den Hoop herum, sodass sein Mittelpunkt vor dir in der Luft stehen bleibt, während der Hoop um diesen Punkt kreist.","goodFor":"Die klassische Hoop-Illusion.","props":["Hoop"]},"hoop-escalator":{"name":"Rolltreppe","description":"Halte den Hoop in Bewegung, während du ihn von der Taille zu den Knien und wieder hoch zur Brust wanderst – eine Körperzone pro Takt.","goodFor":"Verbindet alle Body-Hooping-Zonen zu einem Flow.","props":["Hoop"]},"hoop-neck":{"name":"Hals-Hooping","description":"Neige den Kopf leicht und lass einen leichten Hoop um den Hals kreisen, geführt von kleinen Impulsen aus Kopf und Schultern.","goodFor":"Ein Show-Move, der kleine, präzise Impulse trainiert.","avoidIf":["Nackenschmerzen."],"props":["Hoop"]},"hoop-reverse-waist":{"name":"Taille-Hooping rückwärts","description":"Waist Hooping andersherum. Wechsle, welcher Fuß vorne steht, wirf den Hoop in die neue Richtung und behalte denselben Vor-zurück-Puls.","goodFor":"Beide Richtungen ausbalancieren, damit jeder spätere Trick in beide Richtungen klappt.","alignmentCues":["Wechsle deinen vorderen Fuß.","Gleicher Puls, neue Richtung."],"props":["Hoop"],"commonMistakes":["Hüften kreisen.","Auf der schwachen Seite zu früh aufgeben."]},"hoop-hips":{"name":"Hüft-Hooping","description":"Lass den Hoop von der Taille zu den Hüftknochen sinken und halte ihn dort mit einem tieferen, kleineren Puls aus dem Becken heraus.","goodFor":"Kontrolle unterhalb der Taille und ein Schritt Richtung Knie.","alignmentCues":["Knie weich.","Impuls aus dem Becken, nicht aus dem Bauch."],"props":["Hoop"],"commonMistakes":["Einfach nach unten gleiten lassen.","Impuls zu groß."]},"hoop-thighs":{"name":"Oberschenkel-Hooping","description":"Steh mit den Füßen nah beieinander und halte den Hoop mit schnellen, kleinen Knie-Bounces um die Oberschenkel in Bewegung.","goodFor":"Beinrhythmus und die Verbindung zwischen Hüften und Knien.","alignmentCues":["Füße zusammen.","Schnelle, kleine Bounces."],"props":["Hoop"],"commonMistakes":["Füße auseinander.","Bounce zu langsam."]},"hoop-reverse-chest":{"name":"Umgekehrtes Brust-Hooping","description":"Brust-Hooping in die andere Richtung, Arme erhoben und die Rippen treiben den Hoop an.","goodFor":"Beide Richtungen hoch am Körper.","alignmentCues":["Arme hoch und aus dem Weg.","Der Brustkorb schaukelt vor und zurück."],"props":["Hoop"],"commonMistakes":["Arme sinken in den Hoop.","Hüften machen die Arbeit."]},"hoop-shoulder":{"name":"Schulter-Hooping","description":"Der Hoop dreht sich um die Schultern und die obere Brust, während die Arme über dem Kopf erhoben sind.","goodFor":"Oberkörper-Hooping.","alignmentCues":["Arme gerade nach oben.","Kleine Schulter-Impulse."],"props":["Hoop"],"commonMistakes":["Arme biegen sich nach innen.","Hoop rutscht zur Brust."]},"hoop-arm":{"name":"Arm-Hooping","description":"Hebe einen Arm gerade nach oben und lass den Hoop um den Unterarm kreisen – die Hand zeichnet einen kleinen Kreis, damit er in Bewegung bleibt.","goodFor":"Hooping an Armen und Beinen und ein Lasso-Gefühl mit erhobenem Arm.","alignmentCues":["Arm gerade, Hand über dem Kopf.","Kleiner Handkreis."],"props":["Hoop"],"commonMistakes":["Der ganze Arm kreist.","Arm driftet nach vorne."]},"hoop-elbow":{"name":"Ellbogen-Hooping","description":"Der Arm wird seitlich ausgestreckt und im Ellbogen gebeugt gehalten, während der Hoop um das Ellbogengelenk kreist.","goodFor":"Kontrolle der Gliedmaßen weg vom Körper.","alignmentCues":["Oberarme waagerecht.","Kleine Ellenbogenkreise."],"props":["Hoop"],"commonMistakes":["Ellenbogen sinkt ab.","Hoop rutscht zur Schulter."]},"hoop-foot":{"name":"Bein-Hooping","description":"Hebe ein Bein an und lass den Hoop um das Schienbein kreisen – der Fuß zeichnet kleine Kreise, um ihn in Bewegung zu halten.","goodFor":"Gleichgewicht und Beinkontrolle.","alignmentCues":["Standbein stabil.","Kleine Fußkreise."],"props":["Hoop"],"commonMistakes":["Gleichgewicht geht verloren.","Kreise zu groß."]},"hoop-full-escalator":{"name":"Volle Rolltreppe","description":"Reite den Hoop von den Knien bis ganz hinauf zu den Schultern und wieder hinunter, ohne anzuhalten.","goodFor":"Die gesamte Strecke am Körper in einer durchgehenden Bewegung.","alignmentCues":["Steigere den Puls, je höher du kommst.","Die Arme steigen, wenn der Hoop steigt."],"props":["Hoop"],"commonMistakes":["Hoop geht beim Sprung von der Taille zur Brust verloren.","Arme im Weg."]},"hoop-vortex":{"name":"Wirbel","description":"Dreh den Hoop über Kopf als Lasso, lass ihn um Schultern und Brust fallen und fang ihn an der Taille auf – alles in einer spiralförmigen Abwärtsbewegung.","goodFor":"Off-Body- und On-Body-Hooping verbinden.","alignmentCues":["Behalte das Lasso-Tempo beim Loslassen.","Fang an zu pulsieren, bevor er landet."],"props":["Hoop"],"commonMistakes":["Zu langsam losgelassen.","Hoop kippt auf dem Weg nach unten."]},"hoop-duck-out":{"name":"Ente raus","description":"Lass den Hoop mit den Händen von der Taille über die Brust nach oben wandern, greif ihn über Kopf ins Lasso und bring ihn dann vor deinem Körper in einen Handspin hinunter.","goodFor":"Den Hoop sauber vom Körper lösen.","alignmentCues":["Mit den Rippen anheben.","Über Kopf im Takt greifen."],"props":["Hoop"],"commonMistakes":["Zu früh gegriffen.","Tempo geht verloren."]},"hoop-drop-in":{"name":"Dropdown","description":"Aus dem Lasso über Kopf loslassen, den Hoop an der Brust auffangen und ihn dann bis zur Taille fallen lassen.","goodFor":"Der einfachste Weg vom Off-Body zurück an den Körper.","alignmentCues":["Arme hoch, wenn er fällt.","Fang mit einem Puls."],"props":["Hoop"],"commonMistakes":["Zu schnell fallen lassen.","Arme pressen nach unten."]},"hoop-chest-lift":{"name":"Bruststraffung","description":"Hebe den Hoop mit einem stärkeren Puls von der Taille zur Brust und zurück.","goodFor":"Wechsel zwischen Körperzonen.","alignmentCues":["Schnellerer Puls zum Aufsteigen.","Arme früh hoch."],"props":["Hoop"],"commonMistakes":["Er geht im Wechsel verloren.","Arme sinken."]},"hoop-knee-drop":{"name":"Knielandung","description":"Lass den Hoop von der Taille zu den Knien sinken, halte ihn dort und lass ihn dann zur Taille zurückspringen.","goodFor":"Transitionen am Unterkörper.","alignmentCues":["Füße zusammen für die Knie.","Mehr Bounce zum Aufsteigen."],"props":["Hoop"],"commonMistakes":["Füße auseinander.","Er geht beim Aufsteigen verloren."]},"hoop-side-spin":{"name":"Seitendrehung","description":"Ein Handspin neben dem Körper in der Rad-Ebene, der Hoop dreht sich wie ein Rad neben dir.","goodFor":"Die Rad-Ebene für Hoops.","alignmentCues":["Hoop flach neben dir.","Hand auf Hüfthöhe."],"props":["Hoop"],"commonMistakes":["Hoop trifft das Bein.","Ebene kippt."]},"hoop-reverse-hand-spin":{"name":"Rückwärtsdrehung","description":"Der Handspin, der vor dir in die andere Richtung dreht.","goodFor":"Beide Richtungen off-body.","alignmentCues":["Gleiche Ebene, andere Richtung.","Daumen bleibt oben."],"props":["Hoop"],"commonMistakes":["Er wackelt.","Er wird langsamer."]},"hoop-reverse-lasso":{"name":"Umgekehrtes Lasso","description":"Das Überkopf-Lasso, das in die andere Richtung dreht.","goodFor":"Beide Lasso-Richtungen.","alignmentCues":["Hoop waagerecht.","Kleiner Handkreis."],"props":["Hoop"],"commonMistakes":["Kippen.","Große Armkreise."]},"hoop-palm-spin":{"name":"Palm Spin über Kopf","description":"Ein Handspin, der auf der offenen Handfläche über den Kopf gehoben wird – der Hoop dreht sich frontal über dir.","goodFor":"Off-body-Spins hoch oben erreichen.","alignmentCues":["Arm lang.","Handfläche offen."],"props":["Hoop"],"commonMistakes":["Hoop driftet nach hinten.","Arm beugt sich."]},"hoop-coin-flip":{"name":"Münzwurf","description":"Balance den Hoop aufrecht auf den Fingerspitzen und schnippe ihn an, sodass er sich wie eine geworfene Münze um seine aufrechte Mittelachse dreht.","goodFor":"Feine Fingerkontrolle und eine neue Achse.","alignmentCues":["Hoop aufrecht.","Schnippen, dann kreisen lassen."],"props":["Hoop"],"commonMistakes":["Hoop kippt.","Festklammern."]},"hoop-cateye":{"name":"Katzenauge","description":"Halte den Hoop seitlich am Ring und wiege ihn um seine aufrechte Mittelachse – von vorn wird er schmaler und breiter wie ein Katzenauge.","goodFor":"Wiegebewegung und eine eindrucksvolle Illusion.","alignmentCues":["Hand bleibt am Ring.","Gleichmäßig wiegen."],"props":["Hoop"],"commonMistakes":["Hand wandert.","Ungleichmäßiges Wiegen."]},"hoop-weave":{"name":"Weben","description":"Ein Handspin, der von einer Körperseite zur anderen gleitet, während die Ebene mit der Brust mitdreht.","goodFor":"Den Spin quer über den Körper führen.","alignmentCues":["Die Brust dreht mit.","Lass ihn weiterdrehen."],"props":["Hoop"],"commonMistakes":["Stoppt in der Mitte.","Kippen."]},"hoop-halo":{"name":"Halo","description":"Der Hoop kreist flach um den Kopf, die gehobene Hand gleitet am Ring über dir mit.","goodFor":"Orbits auf Kopfhöhe.","alignmentCues":["Hoop auf Kopfhöhe um den Kopf.","Hand nah am Kopf."],"props":["Hoop"],"commonMistakes":["Hoop taucht vorne ab.","Ducken."]},"hoop-toss":{"name":"Hoop-Wurf","description":"Wirf den Handspin gerade nach oben, lass ihn weiterdrehen und fang ihn wieder in den Spin.","goodFor":"Einen rotierenden Hoop loslassen und wieder fangen.","alignmentCues":["Wirf gerade nach oben.","Fang dort, wo du geworfen hast."],"props":["Hoop"],"commonMistakes":["Nach vorne werfen.","Den Rand spät greifen."]},"hoop-boomerang":{"name":"Boomerang","description":"Wirf den Hoop mit Backspin nach unten und von dir weg, sodass er am Boden entlangrollt und zu dir zurückkommt.","goodFor":"Backspin und ein spaßiger Bodentrick.","alignmentCues":["Schnippe das Handgelenk zurück.","Wirf tief und nach vorne."],"props":["Hoop"],"commonMistakes":["Zu wenig Backspin.","Zu hoch geworfen."]},"hoop-jump-through":{"name":"Durchspringen","description":"Halte den Hoop mit beiden Händen wie ein Springseil: Schwing ihn über den Kopf und spring durch, wenn er unter deinen Füßen durchgeht.","goodFor":"Rhythmus, Koordination und ein Cardio-Kick.","alignmentCues":["Kleiner Sprung, weiche Knie.","Schwing aus den Handgelenken."],"props":["Hoop"],"commonMistakes":["Zu früh gesprungen.","Zu große Armschwünge."]},"hoop-behind-back-pass":{"name":"Pass hinter dem Rücken","description":"Ein Handspin wird hinter dem Rücken von einer Hand zur anderen gereicht und dann vorne wieder zurück.","goodFor":"Der Pass geht einmal ganz um den Körper herum.","alignmentCues":["Lass ihn hinten weiterdrehen.","Die wartende Hand greift nach hinten."],"props":["Hoop"],"commonMistakes":["Hoop bleibt hinten stehen.","Hoop stößt gegen den Rücken."]},"hoop-under-leg-pass":{"name":"Pass unter dem Bein","description":"Ein Pass von Hand zu Hand, der unter dem angehobenen rechten Bein durchtaucht.","goodFor":"Die Beine in die Passes einbauen.","alignmentCues":["Heb das Knie zum Hoop.","Bleib aufrecht.","Erheben Sie sich wieder, sobald der Reifen auf der anderen Seite herauskommt."],"props":["Hoop"],"commonMistakes":["Nach vorne gebeugt.","Zu schnell.","Eile."]},"hoop-corkscrew":{"name":"Korkenzieher","description":"Ein Lasso, das spiralförmig bis auf Hüfthöhe sinkt und wieder aufsteigt, während der Hoop einen Korkenzieher zeichnet.","goodFor":"Das Lasso durch verschiedene Ebenen führen.","alignmentCues":["Beuge die Knie, um tiefer zu gehen.","Halte den Hoop waagerecht."],"props":["Hoop"],"commonMistakes":["Hoop kippt unten.","Drehung lässt nach."]},"hoop-barrel-roll":{"name":"Fass-rolle","description":"Eine Drehung auf der Hand, die alle vier Beats einmal um den Körper wandert, während der Hoop um dich herumrollt.","goodFor":"Off-Body-Flow im Vollkreis.","alignmentCues":["Dreh dich mit dem Hoop mit.","Dreh die ganze Zeit weiter."],"props":["Hoop"],"commonMistakes":["Hoop bleibt am Körper hängen.","Drehung stockt hinten."]},"hoop-chest-roll":{"name":"Brustrolle","description":"Lege den drehenden Hoop auf die Brust und lass ihn zur anderen Hand hinüberrollen.","goodFor":"Die erste Hoop-Rolle.","alignmentCues":["Brust angehoben.","Arme offen, während er rollt."],"props":["Hoop"],"commonMistakes":["Brust fällt ein.","Zu früh gegriffen."]},"hoop-back-roll":{"name":"Rückenrolle","description":"Der Hoop rollt über die hinteren Schultern von einer Hand zur anderen.","goodFor":"Rollt hinter dem Körper.","alignmentCues":["Schulterblätter zusammen.","Kopf leicht nach vorn."],"props":["Hoop"],"commonMistakes":["Rücken rundet sich.","Hoop fällt."]},"hoop-isopop":{"name":"Iso Pop","description":"Eine Isolation, bei der der Hoop alle zwei Beats kurz stoppt und zur Seite herausspringt, bevor es weitergeht.","goodFor":"Akzente und Stalls in Isolationen.","alignmentCues":["Pop auf den Beat.","Isolation bleibt zwischen den Pops sauber."],"props":["Hoop"],"commonMistakes":["Pops zu groß.","Zentrum wandert."]},"hoop-wheel-isolation":{"name":"Seitliche Isolation","description":"Eine Isolation neben dem Körper in der Rad-Ebene.","goodFor":"Isolationen in einer zweiten Ebene.","alignmentCues":["Festes Zentrum neben dir.","Hand kreist darum."],"props":["Hoop"],"commonMistakes":["Zentrum driftet.","Kippen."]},"hoop-floor-isolation":{"name":"Flache Isolation","description":"Eine Isolation mit flach liegendem Hoop – das Zentrum bleibt fix, während die Hand kreist.","goodFor":"Isolationen in der Boden-Ebene.","alignmentCues":["Hoop waagerecht.","Festes Zentrum."],"props":["Hoop"],"commonMistakes":["Kippen.","Zentrum driftet."]},"doubles-hand-spins":{"name":"Verdoppelt die Handdrehungen","description":"Ein Hoop in jeder Hand, beide drehen sich spiegelbildlich vor dir.","goodFor":"Der erste Doubles-Move.","alignmentCues":["Hoops nebeneinander.","Gleiche das Tempo an."],"props":["zwei Hoops"],"commonMistakes":["Hoops stoßen zusammen.","Einer wird langsamer."]},"doubles-offset-spins":{"name":"Doppelte Offset-Spins","description":"Doubles-Handspins, die in dieselbe Richtung drehen, um eine halbe Drehung versetzt.","goodFor":"Unabhängiges Timing zwischen den Händen.","alignmentCues":["Einer oben, der andere unten.","Gleiche Richtung."],"props":["zwei Hoops"],"commonMistakes":["Laufen synchron.","Zusammenstoßen."]},"doubles-side-spins":{"name":"Verdoppelt die Seitenspiele","description":"Ein Hoop dreht sich neben jeder Hüfte in der Rad-Ebene.","goodFor":"Doubles in der Rad-Ebene.","alignmentCues":["Hoops aufrecht.","Frei von den Beinen."],"props":["zwei Hoops"],"commonMistakes":["Trifft die Beine.","Kippt."]},"doubles-floor-spins":{"name":"Doppelt Lassos","description":"Ein Lasso über Kopf in jeder Hand, spiegelbildlich.","goodFor":"Doubles über Kopf.","alignmentCues":["Beide auf gleicher Höhe.","Kleine Handkreise."],"props":["zwei Hoops"],"commonMistakes":["Hoops berühren sich.","Arme werden müde."]},"doubles-wedgies":{"name":"Doppel-Wedgies","description":"Ein Wedgie in jeder Hand, beide Hoops schaukeln in den Daumenbeugen.","goodFor":"Doubles-Schaukelbewegungen.","alignmentCues":["Daumen nach außen.","Gleichmäßiges Schaukeln."],"props":["zwei Hoops"],"commonMistakes":["Hoops prallen aufeinander.","Ungleichmäßiges Timing."]},"doubles-coin-flips":{"name":"Doppelte Münzwürfe","description":"Ein Coin Flip auf jeder Hand gleichzeitig.","goodFor":"Fingerkontrolle bei Doubles.","alignmentCues":["Beide aufrecht.","Gleichzeitig schnippen."],"props":["zwei Hoops"],"commonMistakes":["Kippt.","Prallen aufeinander."]},"doubles-isolations":{"name":"Doubles Isolationen","description":"Eine Isolation in jeder Hand, beide Zentren fixiert nebeneinander.","goodFor":"Zwei Isolationen gleichzeitig.","alignmentCues":["Zwei ruhende Zentren.","Hände kreisen zusammen."],"props":["zwei Hoops"],"commonMistakes":["Zentren driften.","Hoops prallen aufeinander."]},"doubles-toss":{"name":"Doubles-Wurf","description":"Wirf beide rotierenden Hoops gleichzeitig hoch und fange sie wieder in Doubles-Spins.","goodFor":"Doubles-Releases.","alignmentCues":["Beide gleichzeitig gerade nach oben werfen.","Fange dort, wo du geworfen hast."],"props":["zwei Hoops"],"commonMistakes":["Ungleiche Würfe.","Driftet nach vorn."]},"doubles-waist-and-hand":{"name":"Hüft-Hoop und Handspin","description":"Lass einen Hoop auf der Hüfte rotieren, während du einen zweiten in der linken Hand drehst.","goodFor":"Geteilte Aufmerksamkeit zwischen Körper und Hand.","alignmentCues":["Die Hüften behalten ihren Puls.","Handspin vor dem Körper-Hoop."],"props":["zwei Hoops"],"commonMistakes":["Körper-Hoop wird langsamer.","Hand-Hoop trifft den Körper-Hoop."]},"doubles-chest-and-hand":{"name":"Chest-Hoop und Handspin","description":"Chest Hooping mit einem erhobenen Arm, während die andere Hand einen zweiten Hoop dreht.","goodFor":"Body Hooping hoch am Körper mit einem Hand-Trick.","alignmentCues":["Ein Arm oben.","Die Rippen treiben den Körper-Hoop an."],"props":["zwei Hoops"],"commonMistakes":["Der Arm sinkt in den Chest-Hoop.","Der Puls geht verloren."]},"doubles-waist-and-lasso":{"name":"Hüft-Hoop und Lasso","description":"Hüft-Hoop unten, Lasso über dem Kopf: zwei Hoops auf zwei Ebenen gleichzeitig.","goodFor":"Hoopen auf zwei Ebenen gleichzeitig.","alignmentCues":["Hüften pulsieren, Hand kreist.","Lasso über dem Kopf."],"props":["zwei Hoops"],"commonMistakes":["Körper-Hoop rutscht nach unten.","Lasso kippt."]},"poi-one-hand-spin":{"name":"Vorwärtsspin mit einem Poi","description":"Ein Poi kreist vor dir wie der Zeiger einer Uhr, der Kopf streicht an deiner Seite vorbei. Das Handgelenk macht einen kleinen, gleichmäßigen Kreis, und die Schnur bleibt straff.","goodFor":"Spüre den Zug der Schnur und den Rhythmus von einer Drehung pro Beat.","alignmentCues":["Kleine Kreise mit dem Handgelenk, große Kreise mit dem Poi.","Halte den Kreis flach vor dir wie eine Fensterscheibe."],"props":["ein Poi"],"commonMistakes":["Schwingen aus der Schulter.","Den Kreis zu dir kippen lassen."]},"poi-wall-spin":{"name":"Vorwärts-Wall Spin","description":"Beide Poi drehen gemeinsam vorwärts vor dir, je eines neben einer Schulter, nebeneinander wie zwei Räder auf einer Achse. Die erste Bewegung mit zwei Poi.","goodFor":"Zwei Poi im Takt zueinander und zum Beat.","alignmentCues":["Beide Köpfe erreichen den höchsten Punkt gemeinsam.","Hände etwa schulterbreit auseinander."],"props":["ein Paar Poi"],"commonMistakes":["Ein Poi hinkt dem anderen hinterher.","Die Kreise driften ineinander."]},"poi-reverse-wall-spin":{"name":"Rückwärts-Wall Spin","description":"Der Wall Spin umgekehrt: Die Köpfe steigen außen auf und fallen in der Mitte herunter.","goodFor":"Beide Richtungen, bevor du Weaves und Flowers lernst.","alignmentCues":["Dieselben flachen Ebenen, nur die Richtung ändert sich.","Führe die Kreise mit dem Handrücken."],"props":["ein Paar Poi"],"commonMistakes":["Zurückrutschen in den Vorwärtsspin.","Nach vorne geneigte Ebenen."]},"poi-split-time":{"name":"Split-Time-Wanddrehung","description":"Beide Poi drehen sich in dieselbe Richtung, aber um eine halbe Drehung versetzt: Ist das eine oben, ist das andere unten. Das Timing, auf dem jeder Weave aufbaut.","goodFor":"Unabhängiges Timing in beiden Händen.","alignmentCues":["Auf, ab, auf, ab: Die Köpfe wechseln sich ab.","Zähle den höchsten Punkt jedes Poi auf den Beat und das „Und“."],"props":["ein Paar Poi"],"commonMistakes":["Zurückdriften ins Same-Time.","Die Hände bewegen sich unterschiedlich schnell."]},"poi-butterfly":{"name":"Schmetterling","description":"Die Hände nah beieinander vor dem Körper, die Poi drehen sich entgegengesetzt und treffen sich oben und unten wie die Flügel eines Schmetterlings.","goodFor":"Entgegengesetzte Drehrichtungen und die Hände nah beieinander.","alignmentCues":["Die Köpfe küssen sich oben und unten.","Die Handgelenke berühren sich fast."],"props":["Poi-Paar"],"commonMistakes":["Die Köpfe kollidieren, wenn die Ebenen sich kreuzen.","Die Hände driften auseinander."]},"poi-reverse-butterfly":{"name":"Umgekehrter Schmetterling","description":"Der Butterfly, bei dem beide Flügel andersherum kreisen: Die Köpfe steigen zusammen in der Mitte auf und fallen an den Außenseiten wieder herab.","goodFor":"Den Butterfly in beide Richtungen ausbalancieren.","alignmentCues":["Oben in der Mitte zusammenführen.","Dieselben engen Hände wie beim Butterfly vorwärts."],"props":["Poi-Paar"],"commonMistakes":["Die Köpfe verheddern sich oben.","Ein Flügel hängt durch."]},"poi-chase-the-sun":{"name":"Verfolge die Sonne","description":"Hände vorne zusammen und Split-Time: Die beiden Köpfe folgen einander in einem großen Kreis, immer eine halbe Umdrehung auseinander.","goodFor":"Split-Time mit engen Händen, bereit für Weaves.","alignmentCues":["Ein Kopf immer gegenüber dem anderen.","Die Hände bewegen sich als Einheit."],"props":["Poi-Paar"],"commonMistakes":["Die Köpfe holen einander ein.","Die Hände trennen sich."]},"poi-wheels":{"name":"Wheels vorwärts","description":"Beide Poi drehen sich neben dir wie die Räder eines Fahrrads, die Oberseiten rollen nach vorne.","goodFor":"Die Wheel-Ebene, seitlich am Körper.","alignmentCues":["Die Kreise verlaufen parallel zu deinen Seiten.","Ellbogen weich und nah."],"props":["Poi-Paar"],"commonMistakes":["Die Poi streifen die Beine.","Die Wheels spreizen sich nach außen."]},"poi-reverse-wheels":{"name":"Wheels rückwärts","description":"Wheels rollen rückwärts neben dir, die Köpfe kommen vorne hoch und fallen hinten ab.","goodFor":"Beide Richtungen in der Wheel-Ebene.","alignmentCues":["Dieselben Wheels, umgekehrt.","Schultern locker und gesenkt."],"props":["Poi-Paar"],"commonMistakes":["Die Wheels driften hinter den Körper.","Die Handgelenke versteifen sich."]},"poi-fountain":{"name":"Fontäne","description":"Wheels im Split-Time: Ein Poi steigt, während der andere fällt, wie Wasser in einem Springbrunnen neben dir.","goodFor":"Split-Time in der Wheel-Ebene, die Grundlage des Walking Weaves.","alignmentCues":["Einer hoch, einer runter.","Halte den Rhythmus zwischen beiden Händen gleichmäßig."],"props":["Paar Poi"],"commonMistakes":["Timing kippt in Same Time.","Wheels kippen nach innen."]},"poi-opposite-wheels":{"name":"Gegenüberliegende Räder","description":"Ein Wheel rollt vorwärts, das andere zurück. Die Heads passieren sich oben und unten.","goodFor":"Koordination, während die Hände gegenläufig drehen.","alignmentCues":["Beide erreichen zusammen den höchsten Punkt.","Jede Hand behält ihre eigene Richtung."],"props":["Paar Poi"],"commonMistakes":["Beide Hände wechseln in dieselbe Richtung.","Ein Wheel wird kleiner."]},"poi-overhead":{"name":"Drehung am Boden über dem Kopf","description":"Beide Poi kreisen flach über deinem Kopf wie Hubschrauberrotoren und hängen außen leicht tiefer, während sie sich drehen.","goodFor":"Die Floorplane und stabile Schultern über Kopf.","alignmentCues":["Hände knapp über dem Kopf.","Lass die Poi die Ebene finden – nicht mit Muskelkraft."],"props":["Paar Poi"],"commonMistakes":["Die Schultern ziehen sich hoch.","Die Poi tauchen nach vorn ab."]},"poi-low-floor":{"name":"Bodendrehung in Hüfthöhe","description":"Die Floorplane, heruntergeholt auf Hüfthöhe: Die Poi schwingen in Taillenhöhe neben dir herum.","goodFor":"Die tiefe Floorplane, wie sie in Floor-to-Wall-Hybriden verwendet wird.","alignmentCues":["Hände seitlich neben den Hüften.","Halte die Kreise waagerecht."],"props":["Paar Poi"],"commonMistakes":["Die Poi schlagen an die Oberschenkel.","Nach vorne lehnen."]},"poi-three-beat-weave":{"name":"Drei-Beat-Weave","description":"Der Signature-Move mit Poi: Poi im Split Time schwingen von einer Körperseite zur anderen, während die Arme sich kreuzen und wieder lösen, wenn die Ebenen die Seite wechseln.","goodFor":"Der Flow-Move, auf dem dein ganzes Poi-Spielen aufbaut.","alignmentCues":["Drehe die Schultern im Weave mit.","Die Ebenen neigen sich leicht zur jeweiligen Seite."],"props":["Paar Poi"],"commonMistakes":["Die Hände bleiben in der Mitte.","Die Poi stoßen beim Kreuzen zusammen."]},"poi-reverse-three-beat-weave":{"name":"Reverse Drei-Beat-Weave","description":"Der Three-Beat Weave, bei dem beide Poi rückwärts kreisen. Die Arme kreuzen sich oben statt unten.","goodFor":"In beide Richtungen weaven.","alignmentCues":["Dasselbe Seitenwechsel-Muster, umgekehrter Spin.","Halte die Hände auf Brusthöhe."],"props":["Poi-Paar"],"commonMistakes":["Die Poi-Köpfe stoßen oben zusammen.","Der Weave zieht sich auf eine Seite zusammen."]},"poi-two-beat-weave":{"name":"Zwei-Beat-Weave","description":"Ein schnellerer Weave, der bei jedem Beat die Seite wechselt. Schnellere Kreuzungen machen ihn lebhafter und kompakter.","goodFor":"Schnelle Seitenwechsel.","alignmentCues":["Kleinere, schnellere Schulterdrehungen.","Kreuz die Handgelenke nah an der Brust."],"props":["Poi-Paar"],"commonMistakes":["Rückfall in den Drei-Beat-Takt.","Split geht verloren."]},"poi-five-beat-weave":{"name":"Fünf-Beat-Weave","description":"Ein längerer, weiterer Weave: Die Poi drehen auf jeder Seite mehr Runden, bevor sie zurückkreuzen.","goodFor":"Die Weave-Form über längere Phrasen halten.","alignmentCues":["Weite Schulterdrehungen.","Halte die Kreuzungen flüssig."],"props":["Poi-Paar"],"commonMistakes":["Zu frühes Kreuzen.","Die Ebenen werden flach."]},"poi-behind-back-weave":{"name":"Weave hinter dem Rücken","description":"Bei jedem zweiten Beat-Paar schwingt der rechte Poi hinter deinem Rücken herum und kehrt vorne zurück, ohne den Takt zu unterbrechen.","goodFor":"Body Passes, die den Look eines einfachen Musters verändern.","alignmentCues":["Greif tief hinter die Hüften.","Schau nach vorn und vertrau dem Timing."],"props":["Poi-Paar"],"commonMistakes":["Der Poi trifft den Rücken.","Der vordere Poi stoppt, während der hintere weiterläuft."]},"poi-crossers":{"name":"Crosser","description":"Wall Spins im Gleichtakt, während die Arme vor dir kreuzen und sich wieder öffnen – die Poi tauschen bei jedem Beat die Seiten.","goodFor":"Armkreuzungen im Takt der Poi.","alignmentCues":["Kreuz an den Handgelenken.","Halte beide Poi im Takt."],"props":["Poi-Paar"],"commonMistakes":["Die Tethers verheddern sich beim Kreuzen der Arme.","Ein Poi stockt."]},"poi-reels":{"name":"Rollen","description":"Beide Poi kreisen einen Takt lang zusammen auf einer Körperseite und schwingen dann zur anderen Seite hinüber.","goodFor":"Beide Poi als Einheit um den Körper bewegen.","alignmentCues":["Die Hände bleiben nah beieinander.","Drehe den Körper zu jeder Seite."],"props":["Poi-Paar"],"commonMistakes":["Hände gehen beim Kreuzen auseinander.","Kreuzen offbeat."]},"poi-thread-the-needle":{"name":"Nadel durchfädeln","description":"Gegenläufige Poi in Split Time, bei denen sich die Arme kreuzen: Ein Poi schlüpft durch die Lücke, die das andere gerade verlassen hat.","goodFor":"Präzises Timing zwischen beiden Händen.","alignmentCues":["Kreuze, wenn sich die Lücke öffnet.","Halte die Kreise eng."],"props":["Poi-Paar"],"commonMistakes":["Poi kollidieren mitten im Kreuzen.","Timing rutscht ins Same Time."]},"poi-buzzsaw":{"name":"Buzzsaw","description":"Die Hände aneinander gedrückt, beide Poi drehen sich wie eines, die Schnüre nebeneinander wie eine einzelne rotierende Klinge.","goodFor":"Beide Poi exakt angleichen.","alignmentCues":["Handflächen zusammen, Handgelenke locker.","Ein Kreis, zwei Köpfe."],"props":["Poi-Paar"],"commonMistakes":["Köpfe gehen auseinander.","Hände driften auseinander."]},"poi-one-hand-isolation":{"name":"Isolation mit einem Poi","description":"Die Hand kreist mit gleicher Geschwindigkeit entgegengesetzt zum Kopf, sodass die Mitte der Schnur wie festgenagelt in der Luft steht, während sich der Poi um sie dreht.","goodFor":"Die erste Illusion: ein fester Punkt im Raum.","alignmentCues":["Hand immer gegenüber dem Kopf.","Schau auf die Mitte der Schnur, nicht auf den Kopf."],"props":["ein Poi"],"commonMistakes":["Handkreis zu klein, sodass der Punkt wandert.","Oben beschleunigen."]},"poi-isolation":{"name":"Isolationen","description":"Isolationen in beiden Händen gleichzeitig, die beiden Stillpunkte nebeneinander vor dir.","goodFor":"Illusionskontrolle mit beiden Händen.","alignmentCues":["Beide Hände jeweils gegenüber dem Kopf.","Ellbogen weich, Schultern gesenkt."],"props":["Poi-Paar"],"commonMistakes":["Eine Hand verliert die Isolation.","Punkte driften nach vorne."]},"poi-split-isolation":{"name":"Split-Time-Isolationen","description":"Isolationen um eine halbe Drehung versetzt: eine Hand oben, die andere unten, die Stillpunkte bleiben stabil.","goodFor":"Isolations-Timing in Split Time.","alignmentCues":["Die Hände wechseln zwischen oben und unten.","Die Spitzen bleiben auf gleicher Höhe."],"props":["Poi-Paar"],"commonMistakes":["Die Hände finden zusammen.","Die Spitzen sinken ab."]},"poi-wheel-isolation":{"name":"Wheelplane-Isolationen","description":"Isolationen neben dir in der Wheelplane, die ruhenden Spitzen schweben an deinen Seiten.","goodFor":"Isolationen in einer zweiten Ebene.","alignmentCues":["Spitzen auf Hüfthöhe.","Die Hände kreisen parallel zu deinen Seiten."],"props":["Poi-Paar"],"commonMistakes":["Die Ebenen verdrehen sich nach außen.","Hände zu nah am Körper."]},"poi-extension":{"name":"Verlängerungen","description":"Arm und Tether bilden eine gerade Linie, die Hand kreist weit aus, sodass das Poi den größtmöglichen Kreis zeichnet.","goodFor":"Große, offene Formen und die Extension-Hälfte des Cateye.","alignmentCues":["Aus der Schulter reichen.","Hand und Poi-Kopf liegen auf einer Linie vom Zentrum aus."],"props":["Poi-Paar"],"commonMistakes":["Abknicken im Handgelenk.","Die Kreise fallen unten zusammen."]},"poi-cateye":{"name":"(ASUS)","description":"Eine Hand isoliert, die andere macht eine Extension. Die beiden Bahnen überlagern sich zu einer Mandelform – wie das Auge einer Katze.","goodFor":"Zwei verschiedene Handbahnen gleichzeitig vermischen.","alignmentCues":["Isolierende Hand eng, extendierende Hand weit.","Beide starten gemeinsam oben."],"props":["Poi-Paar"],"commonMistakes":["Beide Hände machen dasselbe.","Die Form ist schief."]},"poi-one-hand-antispin":{"name":"Antispin mit einem Poi","description":"Die Hand kreist in die eine Richtung, während das Poi entgegengesetzt spinnt – drei Spins pro Handkreis – und zeichnet so eine Blüte mit vier Blütenblättern.","goodFor":"Das Antispin-Gefühl, bevor es an die Blüten mit zwei Poi geht.","alignmentCues":["Handkreis weit und langsam.","Jede Blütenblattspitze am Rand des Handkreises."],"props":["ein Poi"],"commonMistakes":["Das Poi kippt zurück in den normalen Spin.","Die Blütenblätter sind ungleichmäßig."]},"poi-antispin-flower":{"name":"Vier-Blütenblatt-Antispin","description":"Antispin-Blüten in beiden Händen gleichzeitig – zwei Blüten mit je vier Blütenblättern blühen nebeneinander.","goodFor":"Die klassische Poi-Blüte.","alignmentCues":["Die Hände kreisen zusammen.","Die Blüten liegen in einer Linie: oben, seitlich, unten, seitlich."],"props":["ein Paar Poi"],"commonMistakes":["Eine Hand fällt in den Spin.","Die Flowers treiben nach vorn."]},"poi-split-antispin":{"name":"Split-Time-Antispin","description":"Vier-Blüten-Flowers, deren Poi um eine halbe Drehung versetzt sind – die Blüten der einen Flower füllen die Lücken der anderen.","goodFor":"Flower-Timing im Split Time.","alignmentCues":["Die Hände einander gegenüber auf ihren Kreisen.","Die Blüten greifen ineinander."],"props":["ein Paar Poi"],"commonMistakes":["Fällt in Same Time zusammen.","Die Hände kreisen unterschiedlich schnell."]},"poi-three-petal-antispin":{"name":"Drei-Blüten-Antispin","description":"Eine Drei-Blüten-Flower: zwei Antispins pro Handkreis, so dass eine dreieckige Blüte entsteht.","goodFor":"Die Blütenzahl ändert sich mit der Handgeschwindigkeit.","alignmentCues":["Schnellere Hand als bei der Vier-Blüten-Flower.","Die Blüten an drei gleichmäßig verteilten Punkten."],"props":["ein Paar Poi"],"commonMistakes":["Rutscht zurück auf vier Blüten.","Der Handkreis schrumpft."]},"poi-five-petal-antispin":{"name":"Fünf-Blüten-Antispin","description":"Vier Antispins pro Handkreis – eine Fünf-Blüten-Flower mit langsamer, weiter Hand.","goodFor":"Feine Kontrolle über das Hand-zu-Poi-Verhältnis.","alignmentCues":["Sehr langsame Hand.","Zähle vier Poi-Drehungen pro Handkreis."],"props":["ein Paar Poi"],"commonMistakes":["Die Zählung der Blüten geht verloren.","Die Hand stoppt."]},"poi-wheel-antispin":{"name":"Wheel-Plane-Antispin","description":"Antispin-Flowers mit vier Blüten neben dir in der Wheel-Plane.","goodFor":"Flowers in der Wheel-Plane.","alignmentCues":["Flowers parallel zu deinen Körperseiten.","Die Hände kreisen neben den Hüften."],"props":["ein Paar Poi"],"commonMistakes":["Die Ebenen kippen nach innen.","Die Blüten streifen die Beine."]},"poi-overhead-antispin":{"name":"Overhead-Antispin","description":"Antispin-Flowers flach über dem Kopf, die Blüten öffnen sich über dir.","goodFor":"Flowers in der Floor-Plane.","alignmentCues":["Die Hände knapp über dem Kopf.","Petals bleiben auf gleicher Höhe."],"props":["Ein Paar Poi"],"commonMistakes":["Flowers kippen nach vorn.","Schultern ermüden und sinken."]},"poi-antispin-and-spin":{"name":"Antispin und Spin","description":"Die rechte Hand zeichnet eine Antispin-Flower mit vier Petals, während die linke einen einfachen Vorwärtsspin hält.","goodFor":"Handunabhängigkeit: zwei verschiedene Formen gleichzeitig.","alignmentCues":["Spin-Hand bleibt kompakt.","Flower-Hand kreist weit."],"props":["Ein Paar Poi"],"commonMistakes":["Beide Hände kopieren sich.","Poi im Spin werden langsamer."]},"poi-inspin-flower":{"name":"Vier-Petal-Inspin","description":"Die Hand kreist langsam in dieselbe Richtung wie die Poi, fünf Spins pro Handkreis, und zeichnet dabei Schleifen, die nach innen zeigen.","goodFor":"Inspin-Flowers, das Gegenstück zum Antispin.","alignmentCues":["Hand und Poi drehen sich in dieselbe Richtung.","Petal-Schleifen zeigen zur Mitte."],"props":["Ein Paar Poi"],"commonMistakes":["Handkreis zu schnell.","Schleifen ungleichmäßig."]},"poi-three-petal-inspin":{"name":"Drei-Petal-Inspin","description":"Inspin mit vier Spins pro Handkreis, der eine Flower mit drei Schleifen zeichnet.","goodFor":"Petal-Anzahl beim Inspin variieren.","alignmentCues":["Hand etwas schneller als bei vier Petals.","Drei Schleifen, gleichmäßig verteilt."],"props":["Ein Paar Poi"],"commonMistakes":["Falsch gezählt.","Schleifen werden flacher."]},"poi-wall-wheel-hybrid":{"name":"Wall–Wheel-Hybrid","description":"Bei jeder Umdrehung wechseln die Poi die Ebene, erst vorne, dann seitlich, und drehen sich um, wenn der Kopf gerade nach unten zeigt.","goodFor":"Ebenen wechseln, ohne den Spin zu unterbrechen.","alignmentCues":["Wechsle, wenn der Poi zum Boden zeigt.","Drehe das Handgelenk, nicht den ganzen Arm."],"props":["Ein Paar Poi"],"commonMistakes":["Wechsel mitten im Kreis.","Poi wackeln zwischen den Ebenen."]},"poi-wheel-floor-hybrid":{"name":"Wheel–Floor-Hybrid","description":"Die Poi wechseln zwischen Drehungen neben dir und flachen Kreisen, immer wenn sie nach vorn zeigen.","goodFor":"Ein zweiter Hybrid mit horizontaler Ebene.","alignmentCues":["Wechsle, wenn der Poi nach vorn zeigt.","Hände auf Hüfthöhe halten."],"props":["Poi-Paar"],"commonMistakes":["Poi tauchen beim Wechsel ab.","Den Beat verlieren."]},"poi-floor-wall-hybrid":{"name":"Boden-Wand-Hybrid","description":"Von flach über Kopf zu aufrecht vor dem Körper und wieder zurück – gewechselt wird, wenn die Poi seitlich zeigen.","goodFor":"Überkopf- und Wandebeene verbinden.","alignmentCues":["Wechsle, wenn die Poi seitlich zeigen.","Hände flüssig heben und senken."],"props":["Poi-Paar"],"commonMistakes":["Poi treffen den Kopf.","Ungleichmäßige Wechsel."]},"poi-top-stall":{"name":"Stall","description":"Der Poi steigt nach oben, hält einen Moment genau über der Hand inne und fällt auf demselben Weg zurück.","goodFor":"Stoppen und Umkehren: die Grundlage für Stall-Combos und Hyperloops.","alignmentCues":["Hebe die Hand, wenn der Poi den höchsten Punkt erreicht.","Lass ihn hängen, dann führe ihn zurück."],"props":["ein Poi"],"commonMistakes":["Die Schnur wird schlaff und umwickelt.","Die Pause überstürzen."]},"poi-stalls":{"name":"Doppelte Stalls","description":"Beide Poi stallen zusammen oben und kehren Seite an Seite um.","goodFor":"Stall-Kontrolle mit beiden Händen.","alignmentCues":["Beide erreichen gleichzeitig den höchsten Punkt.","Hände heben sich zusammen."],"props":["Poi-Paar"],"commonMistakes":["Ein Poi stallt zu spät.","Poi treffen auf dem Weg nach unten aufeinander."]},"poi-side-stall":{"name":"Seitliche Stalls","description":"Die Poi stallen seitlich statt oben, jeder hält kurz auf Schulterhöhe inne, bevor er zurückschwingt.","goodFor":"Stalls an einem anderen Punkt der Kreisbahn.","alignmentCues":["Mach die Pause, wenn die Poi seitlich zeigen.","Arme locker."],"props":["Poi-Paar"],"commonMistakes":["Poi fallen, statt zu pausieren.","Timing verrutscht."]},"poi-chasing-stalls":{"name":"Verfolgungsjagd","description":"Stalls um einen halben Beat versetzt: Der eine Poi pausiert oben, während der andere noch auf dem Weg nach oben ist.","goodFor":"Stalls im Split Time.","alignmentCues":["Ein Stall, dann der andere.","Halte die Hände auf Brusthöhe."],"props":["ein Paar Poi"],"commonMistakes":["Beide Poi stallen gleichzeitig.","Der zweite Stall kommt zu schnell."]},"poi-hyperloop":{"name":"Hyperloop","description":"Ein Stall, bei dem die Ebene oben umkippt, sodass der Poi herumlooped und auf der anderen Seite der Kreisfläche wieder herunterkommt.","goodFor":"Dreidimensionale Loops aus dem Stall.","alignmentCues":["Drehe das Handgelenk am obersten Punkt des Stalls.","Halte die Schnur straff."],"props":["ein Poi"],"commonMistakes":["Überschlagen, bevor der Poi den höchsten Punkt erreicht.","Die Schnur wird schlaff."]},"poi-arm-wrap":{"name":"Arm-Wrap","description":"Der Poi windet sich um den anderen, nach vorn ausgestreckten Unterarm und dreht auf der kürzeren Schnur schneller; danach wickelt er sich wieder zu einem vollen Kreis ab.","goodFor":"Der erste Wrap – und wie Wraps den Poi schneller machen.","alignmentCues":["Halte den Postarm ruhig und waagerecht.","Halte die kreisende Hand hinter dem Postarm."],"props":["ein Poi"],"commonMistakes":["Der Postarm bewegt sich mit.","Abwickeln in die falsche Richtung."]},"poi-leg-wrap":{"name":"Bein-Wrap","description":"Hebe das Knie an und lass den Poi sich um den Oberschenkel wickeln; senke das Bein, während er sich abwickelt.","goodFor":"Wraps am Körper.","alignmentCues":["Knie hoch, wenn der Poi ankommt.","Bleib auf dem Standbein groß und aufrecht."],"props":["ein Poi"],"commonMistakes":["Das Knie kommt zu spät hoch.","Du verlierst das Gleichgewicht."]},"poi-neck-wrap":{"name":"Nacken-Wrap","description":"Führe die Hand aus dem Überkopfspin nach unten, sodass sich der Poi um den Nacken wickelt und dann wieder in den Überkopfspin zurück abwickelt.","goodFor":"Ein effektvoller Wrap, der Überkopfspins miteinander verbindet.","avoidIf":["Benutze Übungspoi mit weichen Köpfen; lerne Nacken-Wraps niemals mit Feuer."],"alignmentCues":["Kinn gerade, Nacken lang.","Führe die Schnur zum Nackenansatz."],"props":["ein Poi"],"commonMistakes":["Wickeln am Kopf.","Schnur zu schlaff."]},"poi-cord-wrap":{"name":"Schnur-Wrap","description":"Aus dem Butterfly heraus wickeln sich die beiden Schnüre unten umeinander; die Köpfe wirbeln auf kurzen Schnüren, bevor sie sich wieder abwickeln.","goodFor":"Wraps zwischen den beiden Poi.","alignmentCues":["Bring die Schnüre unten am Butterfly zusammen.","Halte die Hände ruhig, während die Poi wrappen."],"props":["ein Paar Poi"],"commonMistakes":["Hände ziehen auseinander.","Wrap verheddert sich."]},"poi-toss":{"name":"Poi-Wurf","description":"Lass den Griff los, wenn das Poi nach oben schwingt. Es dreht sich durch die Luft, und du fängst den Griff, wenn er wieder herumkommt.","goodFor":"Würfe und Fänge.","avoidIf":["Übe Würfe mit weichen Poi und genug Platz um dich herum."],"alignmentCues":["Lass beim Aufwärtsschwung los.","Schau auf den Griff, nicht auf den Kopf."],"props":["ein Poi"],"commonMistakes":["Zu spätes Loslassen.","Zur Schnur greifen statt zum Griff."]},"poi-high-toss":{"name":"Hoher Wurf","description":"Ein höherer Wurf mit einer Extra-Drehung in der Luft vor dem Fang.","goodFor":"Größere Würfe mit mehr Drehung.","alignmentCues":["Ein kräftigerer Impuls beim Loslassen.","Fang den Griff, wenn er herumkommt."],"props":["ein Poi"],"commonMistakes":["Wurf driftet nach vorne.","Ruckartiges Zugreifen beim Fang."]},"poi-double-toss":{"name":"Doppelter Wurf","description":"Beide Poi werden im Split Time geworfen, nacheinander, und wieder in den Schwung gefangen.","goodFor":"Beidhändiges Wurf-Timing.","alignmentCues":["Lass einen los, dann den anderen.","Fange in derselben Reihenfolge."],"props":["ein Paar Poi"],"commonMistakes":["Beide gleichzeitig loslassen.","Auf ein Poi schauen und das andere verlieren."]},"shake-out":{"name":"Ausschütteln","description":"Leg die Props weg und schüttle Hände und Unterarme aus. Lass die Schultern fallen.","goodFor":"Ein kurzer Reset zwischen harten Runs."},"breathe":{"name":"Pause und Reset","description":"Leg die Requisiten ab, steh locker und lass die Arme hängen. Nimm dir einen Moment vor dem nächsten Durchgang.","goodFor":"Senkt den Puls und löst Frust nach Drops."}}`),t={"warmup-mobility":{name:`Flow-Warm-up`,description:`Handgelenke, Schultern, Wirbelsäule und Hüften locker im gleichmäßigen Beat. Nutze es vor jeder Prop-Session.`,focus:`Warm-up · Mobility`},"first-throws":{name:`Erste Würfe`,description:`Ein Ball im Bogen von Hand zu Hand auf Augenhöhe, dann der Zwei-Ball-Austausch, aus dem jedes Muster wächst.`,focus:`Jonglieren · Grundlagen`},"cascade-builder":{name:`Cascade-Aufbau`,description:`Zwei-Ball-Austausch hintereinander, bis der dritte Ball dazukommt: kurze Cascade-Runs, Reset, wieder los.`,focus:`Jonglieren · Grundlagen`},"juggling-tempo-ladder":{name:`Cascade-Tempoleiter`,description:`Die Cascade in drei Tempi, jede Stufe ein paar Beats schneller. Für die schnellen Stufen die Würfe tiefer halten.`,focus:`Jonglieren · Tempo`},"siteswap-sampler":{name:`Siteswap-Sampler`,description:`Cascade in 423, 441 und 531, mit Reverse Cascade und Shower als Gaumenputzer. Jedes Muster beginnt und endet in der Cascade.`,focus:`Jonglieren · Muster`},"four-ball-session":{name:`Vier-Ball-Session`,description:`Zwei in einer Hand für jede Seite, der Vier-Ball-Fountain, dann der synchrone Fountain.`,focus:`Jonglieren · Zahlen`},"juggling-combo-flow":{name:`Jonglier-Combo-Flow`,description:`Ein langes fließendes Set: Cascade, Reverse Cascade, Mills Mess und die Siteswaps zu einem Musikstück verbunden.`,focus:`Jonglieren · Combos`},"cascade-tricks":{name:`Kaskaden-Tricks`,description:`Tennis, halber Shower und Claws – jeder Trick wird in eine laufende Kaskade eingebaut und wieder zurück.`,focus:`Jonglieren · Variationen`},"juggling-body-throws":{name:`Body Throws`,description:`Unter dem Bein, hinter dem Rücken, Chops und Penguins: die Kaskade wird um den Körper geworfen.`,focus:`Jonglieren · Body Throws`},"sync-shapes":{name:`Sync-Formen`,description:`Columns, Rainbow Cross, Box und Yo-Yo: drei Bälle, immer zwei gleichzeitig geworfen.`,focus:`Jonglieren · synchrone Muster`},"club-foundations":{name:`Keulen-Grundlagen`,description:`Einzelspins, der Zwei-Keulen-Austausch und die Drei-Keulen-Kaskade, zum Abschluss mit Flats.`,focus:`Jonglage · Keulen`},"passing-with-a-partner":{name:`Passen zu zweit`,description:`Stellt euch gegenüber und passt: erst einen Ball rüber, dann zwei pro Person, dann Sechser, Vierer und Zweier.`,focus:`Jonglieren · Passen`},"club-passing-session":{name:`Passen mit Keulen`,description:`Vierer mit Keulen zum Aufwärmen, Zweier und Dreier für den Rhythmus, dann Doppelpässe.`,focus:`Jonglieren · Passen mit Keulen`},"hoop-juggling-session":{name:`Hoop-Jonglage`,description:`Hoops in voller Größe, auf der Kante geworfen: einzelne Würfe, der Austausch, die Kaskade und ihre Umkehrung.`,focus:`Jonglage · Hoops`},"staff-first-spins":{name:`Erste Staff-Spins`,description:`Der Wheel Spin neben dem Körper, dann der Front Spin. Langsame, gleichmäßige Drehungen, eine pro Beat.`,focus:`Staff · Grundlagen`},"staff-foundations":{name:`Staff-Grundlagen`,description:`Wheel Spin, Front Spin, Figure 8 und der Hand-to-Hand Pass-Through, auf dem Beat verbunden.`,focus:`Staff · Grundlagen`},"staff-flow-weave":{name:`Staff-Flow-Weave`,description:`Figure 8 in Butterfly, One-Hand-Spins und der Helicopter, so verbunden, dass der Staff nie stehen bleibt.`,focus:`Staff · Flow`},"staff-isolation-lab":{name:`Staff-Isolation-Lab`,description:`Isolations und die Antispin Flower bei langsamerem Tempo, mit Behind-the-Back-Passes dazwischen.`,focus:`Staff · Technik`},"staff-advanced-flow":{name:`Staff Advanced Flow`,description:`Das volle Vokabular in einem langen Stück: Weaves, Wraps, Isolations und der Neck Roll.`,focus:`Staff · Flow`},"staff-both-ways":{name:`Staff in beide Richtungen`,description:`Jeden Grundspin erst vorwärts, dann rückwärts, plus den zweihändigen Helikopter über Kopf.`,focus:`Staff · Richtung und Ebenen`},"staff-contact-lab":{name:`Staff-Kontaktlabor`,description:`Mit offener Hand und am Körper: Fishtails, das Steering Wheel, Hand- und Unterarmrollen und zum Abschluss ein Wurf.`,focus:`Staff · Kontakt`},"double-staff-session":{name:`Double-Staff-Session`,description:`Ein kurzer Staff in jeder Hand: Same Time, Split Time, Wheels und Split Wheels.`,focus:`Staff · Double Staff`},"hoop-first-spins":{name:`Erste Hoop-Spins`,description:`Waist Hooping mit einem Front-Back-Push, dann den Hoop um eine Hand drehen.`,focus:`Hoop · Grundlagen`},"hoop-body-flow":{name:`Hoop On-Body Flow`,description:`Den Hoop hoch zur Brust und runter zu den Knien und zurück zur Taille bewegen, ohne anzuhalten.`,focus:`Hoop · On-Body`},"hoop-off-body":{name:`Off-Body Hoop`,description:`Hand Spins, Lasso, Wedgies und Passes, zum Abschluss Isolations, die den Hoop still im Raum halten.`,focus:`Hoop · Off-Body`},"hoop-full-flow":{name:`Hoop Full Flow`,description:`On-Body und Off-Body zusammen: Escalators, Neck Hooping und die Off-Body-Tricks in einem langen Flow.`,focus:`Hoop · Flow`},"hoop-body-zones":{name:`Hoop-Körperzonen`,description:`Taille in beide Richtungen, dann Hüfte, Oberschenkel und Brust, den Hoop dabei zwischen den Zonen heben und fallen lassen.`,focus:`Hoop · On-Body`},"hoop-tricks-session":{name:`Hoop-Tricks`,description:`Side Spins, der Coin Flip, der Weave, ein Wurf und der Drop-in zurück auf den Körper.`,focus:`Hoop · Off-Body`},"hoop-doubles-session":{name:`Hoop-Doubles`,description:`Zwei Hoops: gespiegelte und versetzte Handspins, Side Spins und ein Hoop an der Taille, dazu ein Handspin.`,focus:`Hoop · Doubles`},"poi-foundations":{name:`Poi-Grundlagen`,description:`Erst ein Poi, dann zwei: Wallplanes vorwärts und rückwärts, Wheelplanes neben dem Körper, Split Time und der Butterfly.`,focus:`Poi · erste Schwünge`},"poi-weave-session":{name:`Poi-Weaves`,description:`Vom Split Time in den 3-Beat-Weave, in beide Richtungen, dann der 2-Beat-Weave, Reels und Crossers.`,focus:`Poi · Weaves`},"poi-flower-lab":{name:`Poi-Flower-Labor`,description:`Extensions und Isolations, dann Antispin mit einem Poi und mit beiden, und zum Abschluss ein Inspin-Flower.`,focus:`Poi · Flowers`},"daily-mixed-flow":{name:`Täglicher Mixed Flow`,description:`Ein bisschen von jeder Kunst: Cascade, Staff-Spins und Hooping, mit einer Mobility-Move zwischen den Props.`,focus:`Mixed · Practice`},"poi-symmetry-lab":{name:`Poi symmetry lab`,description:`Visit vertical-axis (together-opposite), central-point (split-same) and horizontal-axis (split-opposite) patterns with catalog moves.`,focus:`Poi · geometry`},"poi-hybrid-session":{name:`Poi hybrid session`,description:`Cateye, antispin-and-spin and plane hybrids with hide-one-prop study in mind.`,focus:`Poi · hybrids`},"poi-weave-degrees":{name:`Poi weave degrees`,description:`Split foundation into three-beat and five-beat weaves — try degree-of-twist cues in Settings.`,focus:`Poi · weaves`},"staff-symmetry-lab":{name:`Staff symmetry lab`,description:`Together-opposite butterfly, split-same fountain and figure-8 weave — three cells of the timing map on one staff.`,focus:`Staff · geometry`},"staff-flower-lab":{name:`Staff flower lab`,description:`Extensions into isolations, then four-petal antispin and a slower three-petal antispin.`,focus:`Staff · flowers`},"staff-contact-session":{name:`Staff contact session`,description:`Fishtail into hand and forearm rolls, angel roll, then a calm held spin to finish.`,focus:`Staff · contact`},"hoop-plane-lab":{name:`Hoop plane lab`,description:`Visit on-body floor work, off-body wall spins and a horizontal lasso so the plane map sticks.`,focus:`Hoop · planes`},"hoop-isolation-session":{name:`Hoop isolation session`,description:`Hand spin into isolation and cateye, then weave and pass to reconnect with travel.`,focus:`Hoop · isolations`}},n=JSON.parse(`{"start-here":{"title":"Start hier: deine erste Flow-Woche","summary":"Wähle ein Prop, übe zehn Minuten am Tag auf dem Beat, und lass den Unlock Tree dir sagen, was als Nächstes kommt.","imageAlt":"3D-Figur, die einen einzelnen Jonglierball von Hand zu Hand wirft","body":["Flow Arts sehen von außen wie Magie aus: Bälle, die in der Luft hängen, ein Staff, der zu einem Wisch wird, ein Hoop, der eine Tänzerin umkreist, die sich kaum zu bewegen scheint. Von innen sind sie ein Stapel sehr kleiner Fähigkeiten, jede an einem Nachmittag lernbar, geschichtet, bis der Stapel mühelos aussieht. Deine erste Woche dreht sich um die unterste Ebene dieses Stapels.","Wähle ein Prop für den Anfang. Jonglieren lehrt Timing und Hand-Auge-Koordination; Staff lehrt Ebenen und flüssige Handwechsel; Hoop lehrt Rhythmus durch den ganzen Körper. Du kannst alle drei lernen, aber eins nach dem anderen hält deine Aufmerksamkeit dort, wo der Fortschritt ist. Der Rewards-Baum zeigt jede Bewegung für jede Kunst, vom ersten Wurf oder Spin bis zu fortgeschrittenen Patterns, und öffnet die nächsten, wenn du beherrschst, worauf sie aufbauen.","Übe wenig und oft. Zehn fokussierte Minuten am Tag schlagen eine Stunde am Sonntag, weil Koordination zwischen den Einheiten gefestigt wird, besonders im Schlaf. Eine kurze Routine von der Routines-Seite, ein Warm-up und ein paar gezählte Schritte deiner aktuellen Bewegung sind eine vollständige Practice.","Übe vom ersten Tag an auf den Beat. Jede Bewegung in SynthFlow wird in Takten zu einem Tempo gezählt, mit Musik oder generierter Perkussion, die dazu passt. Der Beat gibt dir etwas, woran du dich festhalten kannst, wenn das Prop nicht mitspielt, und er macht Fortschritt messbar: ein sauberer Run bei 90 BPM diese Woche, 100 nächste Woche.","Rechne mit Drops. Jeder lässt fallen, auch Profis im Training. Ein Drop sagt dir, welcher Wurf oder Catch Aufmerksamkeit braucht; über Talent sagt er nichts. Heb das Prop auf, warte auf den nächsten Downbeat und weiter. Am Ende der Woche hast du eine Bewegung, die du ohne Nachdenken kannst, und das ist der Moment, in dem Flow beginnt."]},"counting-and-the-beat":{"title":"Counts, Takte und der Beat","summary":"Warum jede Bewegung in Takten zu einem Tempo gezählt wird und wie du deine Würfe und Spins auf die Musik legst.","imageAlt":"3D-Figur, die eine Drei-Ball-Kaskade jongliert, mit Bögen über den Händen","body":["Musik besteht aus Beats, die in Takte gruppiert sind, meist vier Beats pro Takt. Flow-Bewegungen bestehen aus Zyklen: ein Wurf aus jeder Hand, eine halbe Drehung des Staffs, eine Umlaufbahn des Hoops. Wenn ein Zyklus auf den Beat fällt, werden Bewegung und Musik eins. Deshalb misst SynthFlow jeden Routine-Schritt in Takten statt in Sekunden, und deshalb sagt jede Bewegung, wie viele Beats ein Zyklus dauert.","In einer Drei-Ball-Kaskade fällt jeder Wurf auf einen Beat, abwechselnd rechts und links. Beim Staff-Frontspin dauert eine halbe Drehung meist einen Beat. Hooping an der Taille ist bei entspanntem Tempo üblicherweise eine Umlaufbahn pro Beat. Die Counts im Player benennen, was auf jedem Beat passiert, und die 3D-Figur bewegt sich exakt auf derselben Uhr wie das Audio, sodass du sie im Takt nachmachen kannst.","Tempo wird in Beats pro Minute (BPM) gemessen. Jede Bewegung hat einen angenehmen Bereich: langsam genug, um sauber zu bleiben, schnell genug, dass das Prop seinen Schwung behält. Unterhalb des Bereichs bleiben Spinning Props stehen und Würfe gehen so hoch, dass sie abdriften; oberhalb beginnst du zu hetzen und lässt fallen. Der Builder warnt dich, wenn ein Schritt außerhalb des Bereichs seiner Bewegung liegt.","Beginne jeden Schritt auf dem Downbeat, der „Eins“ des Takts. Der Count-in gibt dir einen Takt, um das Prop in Bewegung zu bringen, bevor die gezählten Takte beginnen. Wenn du den Beat verlierst, jage ihm nicht nach: Stopp, höre auf die nächste „Eins“ und steig wieder ein. Musiker nennen das, die Spitze des Takts finden, und für Flow Artists funktioniert es genauso.","Ein paar Einheiten lang laut mitzuzählen hilft mehr, als es scheint. „Eins, zwei, drei, vier“ zu sagen, während du jonglierst, verbindet den Rhythmus mit deinem Atem und deiner Stimme, sodass er überlebt, wenn das Pattern schwer wird. Sobald die Counts in deinem Körper leben, schalte die gesprochenen Counts in den Settings aus und lass dich von der Musik tragen."]},"tempo-ladders":{"title":"Tempo-Leitern: langsam ist flüssig, flüssig ist schnell","summary":"Steigere dich in kleinen BPM-Schritten von einem Tempo, das du sauber kannst, und geh sofort eine Stufe zurück, wenn die Form bricht.","imageAlt":"3D-Figur, die einen Staff in der Wall Plane vor dem Körper spinnt","body":["Eine Tempo-Leiter ist dieselbe Bewegung bei steigenden Tempi: acht Takte bei 80 BPM, acht bei 88, acht bei 96 und so weiter. Sie ist der zuverlässigste Weg, eine Bewegung schneller zu machen, ohne sie schlampiger zu machen, und mehrere integrierte Routinen sind darum herum aufgebaut.","Starte auf einer Sprosse, die du sauber kannst, auch wenn sie sich zu leicht anfühlt. Der Sinn der untersten Sprosse ist nicht die Herausforderung; sie ist das Einüben korrekter Form, damit genau diese Form schneller wird. Steig um einen kleinen Betrag hoch, etwa fünf bis zehn Prozent. Große Sprünge verändern die Bewegung: Würfe werden niedriger, Spins flacher, und du übst am Ende einen anderen Trick.","Hör auf zu klettern, wenn die Form bricht, nicht wenn du fallen lässt. Achte auf die frühen Anzeichen: Peaks werden ungleichmäßig, der Staff driftet aus seiner Ebene, der Hoop wandert hoch oder runter. Das sind die Signale, eine Sprosse zurückzugehen und sie erneut zu laufen. Eine Leiter mit einem sauberen Run knapp unter deinem Limit zu beenden, lehrt deinen Körper dieses Tempo; sie mit einem Crash zu beenden, lehrt den Crash.","Langsame Tempi sind für Spinning Props schwerer, als sie aussehen, weil das Prop weniger Schwung hat, um durchzukommen. Wenn ein Staff oder Hoop am unteren Ende seines Bereichs stehen bleibt, behalte das Tempo und vergrößere die Bewegung leicht, oder nimm sie in Halftime mit der Musik: ein Zyklus alle zwei Beats.","Verfolge dein höchstes sauberes Tempo für jede Bewegung in Progress. Zu sehen, wie diese Zahl über Wochen steigt, ist gute Motivation, und sie zeigt auch, wann eine Bewegung ein Plateau erreicht hat und eine andere Übung braucht statt mehr vom Gleichen."]},"siteswap-notation":{"title":"Siteswap: Jonglieren als Zahlen geschrieben","summary":"Jede Zahl sagt, wie viele Beats später ein Ball wieder geworfen wird; ungerade Zahlen kreuzen, gerade bleiben, und der Durchschnitt ist die Ballanzahl.","imageAlt":"3D-Figur, die den Siteswap 441 mit zwei hohen Würfen und einem schnellen Zip jongliert","body":["Jonglier-Patterns sind schwer in Worten und leicht in Zahlen zu beschreiben. Siteswap, Mitte der 1980er unabhängig von Jongleuren in Cambridge, am Caltech und in Santa Cruz entwickelt, schreibt ein Pattern als wiederholte Folge von Ziffern. So teilen Jongleure Patterns, prüfen, ob eine Idee funktionieren kann, und entdecken Tricks, die noch niemand versucht hat. SynthFlow nutzt es, um jedes Jonglier-Pattern aus derselben Engine zu animieren.","Stell dir vor, die Hände werfen abwechselnd auf jedem Beat: rechts, links, rechts, links. Jede Ziffer in einem Siteswap sagt, wie viele Beats von jetzt an der Ball, der auf diesem Beat geworfen wird, wieder geworfen wird. Eine 3 kommt drei Beats später zurück; weil drei ungerade ist, landet sie in der anderen Hand. Eine Drei-Ball-Kaskade ist einfach 3, 3, 3, 3 für immer, kurz geschrieben als 3. Eine 4 kommt vier Beats später in derselben Hand zurück, das ist der Vier-Ball-Fountain.","Kleine Zahlen haben besondere Bedeutungen. Eine 2 kehrt zwei Beats später in dieselbe Hand zurück, was praktisch heißt, den Ball einen Moment zu halten. Eine 1 kreuzt auf dem aller nächsten Beat zur anderen Hand, ein schneller Zip direkt rüber. Eine 0 ist eine leere Hand. Größere Zahlen sind höhere Würfe: eine 5 ist ein hoher kreuzender Wurf.","Lies ein Pattern Ziffer für Ziffer. In 441 bleiben zwei Würfe auf ihrer eigenen Seite, während ein dritter Ball darunter hinweg zippt. In 531 geht ein hoher kreuzender Wurf nach oben, während ein Kaskadenwurf und ein Zip die anderen zwei Bälle in Bewegung halten. In 423 wechseln sich ein Wurf in Fountain-Höhe, ein gehaltener Ball und ein Kaskadenwurf ab.","Das Average Theorem sagt dir, wie viele Bälle ein Pattern braucht: Addiere die Ziffern und teile durch ihre Anzahl. 441 ergibt 9 über drei Ziffern, also drei Bälle. Wenn der Durchschnitt keine ganze Zahl ist, kann die Sequenz nicht jongliert werden. Eine zweite Prüfung ist, dass keine zwei Bälle auf demselben Beat in dieselbe Hand landen dürfen, so erkennen Jongleure unmögliche Patterns, bevor sie sie versuchen.","Siteswap hat auch Notation für beide Hände, die zusammen werfen, geschrieben in Klammern wie (4,4), und für zwei Bälle aus einer Hand gleichzeitig, geschrieben in eckigen Klammern. Du brauchst nichts davon, um gut zu jonglieren, aber sobald die Zahlen klicken, beginnt jeder neue Pattern-Name, sich selbst zu erklären. Öffne das Flow-Glossar für die einzelnen Zahlen."]},"passing-basics":{"title":"Passen-Grundlagen: Jonglieren zu zweit","summary":"Stellt euch gegenüber, werft gleichzeitig mit der rechten Hand, passt gerade rüber in die linke Hand und zählt: Sechser, Vierer, Zweier.","imageAlt":"Zwei 3D-Jongleure stehen einander gegenüber und passen sich Bälle gerade hinüber.","body":["Passing ist Jonglieren zu zweit. Zwei Jonglierende stehen sich gegenüber, beide laufen eine Kaskade, und immer wieder fliegt einer der Würfe nicht zu dir zurück, sondern zum Gegenüber. Es ist eine der geselligsten Formen des Jonglierens: Keulen-Passing ist für viele der Festivalabend schlechthin, und aus Üben wird ein Gespräch.","Stellt euch für Bälle etwa zweieinhalb Meter voneinander auf, für Keulen ein Stück weiter. Ihr startet beide auf denselben Zähler, die rechten Hände werfen gleichzeitig. Der Standardpass ist gerade: Er verlässt deine rechte Hand und landet in der linken Hand deines Gegenübers, direkt gegenüber von dir. Er wird nicht aufs Gesicht geworfen. Ziele auf die linke Hüfte deines Gegenübers und gib dem Wurf einen Bogen, der auf halbem Weg zwischen euch knapp über Kopfhöhe seinen höchsten Punkt hat.","Passing-Patterns werden danach benannt, wie oft gepasst wird. Im Sechser passt du jeden sechsten Wurf, dazwischen liegen fünf Selbstwürfe, die das Muster wieder zur Ruhe bringen. Im Vierer, dem üblichen Aufwärmen, passt du auf jeden zweiten Rechtshandwurf: Pass, Self, Self, Self. Im Zweier ist jeder Rechtshandwurf ein Pass und jeder Linkshandwurf ein Self. Im Dreier wechseln die Pässe die Hände, so lernst du auch von links zu passen. Ultimates, der Einer, macht aus jedem einzelnen Wurf einen Pass.","Zählt am Anfang laut zusammen. „Pass, zwei, drei, vier“ hält euch auf demselben Beat, und sobald einer von euch aus dem Takt gerät, kommen die Pässe nicht mehr pünktlich an. SynthFlows Zählstimme sagt im Takt „Pass“ auf deinen Pässen und „Self“ auf den anderen Würfen – so kannst du das Timing allein üben, während dein Gegenüber auf dem Bildschirm mitjongliert.","Fang mit einem Ball an. Wirf ihn rüber, lass dein Gegenüber ihn von der linken in die rechte Hand nehmen und zurückwerfen. Dann nehmt ihr je zwei Bälle, passt gleichzeitig mit den rechten Händen und gebt den ankommenden Ball von links nach rechts in die Wurfhand. Erst danach kommt die Kaskade dazu. Die meisten Drops beim Passing entstehen durch Pässe, die zu lang oder zu flach sind – beides lässt sich mit einem Ball leichter korrigieren als mit sechs.","In SynthFlows Notation listet ein Passing-Pattern deine Würfe und die deines Gegenübers auf, einen pro Beat, wobei p einen Pass markiert: Der Vierer ist <3p 3 3 3|3p 3 3 3>. Die Zahlen bedeuten dasselbe wie im Siteswap. Ein 4p ist ein Doppelpass, der einen Beat später ankommt – so entstehen Patterns mit sieben Keulen."]},"planes-and-geometry":{"title":"Ebenen: Wall, Wheel und Floor","summary":"Spinning Props leben in flachen Ebenen; die Ebene sauber zu halten, ist das meiste, was einen Staff oder Hoop knackig aussehen lässt.","imageAlt":"3D-Figur, die einen Staff in einer Acht auf beiden Seiten des Körpers webt","body":["Ein spinnender Staff oder Hoop fegt über eine flache Fläche, seine Ebene. Flow Artists beschreiben drei grundlegende Ebenen relativ zum Körper. Die Wall Plane ist vor dir, wie eine Glasscheibe, gegen die du deine Handflächen drücken könntest. Die Wheel Plane ist neben dir, so wie ein Wagenrad an deiner Seite dreht. Die Floor Plane ist horizontal, parallel zum Boden, wie bei einem Overhead-Helicopter oder einem Lasso.","Saubere Ebenen sind das, was das Publikum als Skill liest. Ein Staff, der aus seiner Ebene wackelt, wirkt unsicher, auch wenn er nie fällt; ein Hoop, der bei einem Pass perfekt flach bleibt, wirkt mühelos. Der meiste frühe Practice dreht sich still um Ebenen: die Handgelenke am Verdrehen hindern, die Ellbogen am Ausstellen hindern und die Schultern das Prop bewegen lassen statt die Hände.","Viele Tricks sind durch Ebenenwechsel definiert. Ein Figure-8-Weave bewegt den Staff von der Wheel Plane auf einer Seite zur Wheel Plane auf der anderen. Ein Butterfly faltet ihn hinter die Schulter und zurück. Ein Escalator lässt einen Hoop am Körper hoch- und runterlaufen, während seine Ebene waagerecht bleibt. Zu lernen, wo jede Bewegung im Raum beginnt und endet, ist der Weg, sie zu Flow zu verbinden.","Der 3D-Viewer kann die Ebene zeichnen, während du übst. Schalte ihn ein, wenn du einen neuen Spin lernst, und vergleiche: Kippt dein Staff oben zu dir? Taucht der Hoop vorne ab? Ein Spiegel oder eine Handykamera zeigt dasselbe. Aus der Seitenansicht zu schauen, ist besonders nützlich für Wall-Plane-Bewegungen, weil Kippen von vorne unsichtbar ist.","Ebenen helfen auch bei Sicherheit und Raum. Prüfe vor einer Session, dass jede Ebene, die du nutzen wirst, frei ist: die Wand vor dir, die Wände neben dir und die Decke über dir für Floor-Plane- und Overhead-Bewegungen. Eine saubere Ebene, in der nichts ist, ist eine selbstsichere Ebene."]},"spin-and-antispin":{"title":"Spin, Antispin und Isolations","summary":"Wie sich das Prop im Vergleich zur Hand dreht, ergibt drei Familien von Bewegung: Spin, Antispin und Isolation.","imageAlt":"3D-Figur, die mit einem Staff eine vierblättrige Antispin-Blume zeichnet","body":["Wenn du ein rotierendes Prop auf einem Kreis bewegst, passieren zwei Drehungen gleichzeitig: Deine Hand wandert um einen Kreis, und das Prop dreht sich um seinen eigenen Mittelpunkt. Die Flow-Theorie benennt Bewegungen danach, wie diese beiden Drehungen zueinander stehen. Es ist dasselbe Vokabular für Staff, Hoop und Poi, weshalb Skills so gut zwischen Props übertragbar sind.","Beim Spin, manchmal Inspin genannt, dreht sich das Prop in dieselbe Richtung wie der Kreis der Hand. Das ist die natürliche Richtung; die meisten ersten Spins sind Inspin, ohne dass es jemand so nennt. Die gezeichnete Form ist eine Blume, deren Blütenblätter nach außen zeigen.","Beim Antispin dreht sich das Prop entgegen dem Kreis der Hand. Es fühlt sich zuerst seltsam an, wie sich gleichzeitig auf den Kopf klopfen und den Bauch reiben, aber es zeichnet die klassische Blütenblätter-Blume. Die Anzahl der Blütenblätter hängt davon ab, wie oft sich das Prop pro Handkreis dreht: drei Gegenrotationen pro Kreis ergeben vier Blütenblätter, was der Four-Petal Antispin im Staff-Baum ist.","Eine Isolation ist der Sonderfall, bei dem die Hand so kreist, dass ein Punkt des Props im Raum eingefroren erscheint. Beim Staff bleibt der Mittelpunkt still, während die Enden um ihn herumfegen; beim Hoop bleibt der Mittelpunkt des Rings oder ein Punkt am Rand stehen. Isolations sehen aus, als würde das Prop schweben und der Körper es umkreisen. Sie verlangen präzise Handwege, was sie zu exzellentem Training für jeden anderen Trick macht.","Lerne diese langsam und auf den Beat. Besonders Antispin profitiert von einem Tempo deutlich unter deiner normalen Spin-Geschwindigkeit, mit Zählzeiten, die benennen, wo das Prop sein sollte: oben, seitlich, unten, seitlich. Nutze den Ghost im 3D-Viewer, um die Position des nächsten Beats zu sehen, und den Trail, um zu prüfen, ob deine Blume gleichmäßige Blütenblätter hat.","Wenn sich Spin, Antispin und Isolation in einer Ebene vertraut anfühlen, probiere sie in einer anderen. Die Theorie bleibt gleich und dein Körper lernt, dass die Ebene nur eine Einstellung ist, was ein großer Schritt zum Improvisieren von Flow ist."]},"timing-and-direction":{"title":"Timing and direction: the four relationships","summary":"Together or split time, same or opposite direction — four relationships that let spinners name patterns and move between them.","imageAlt":"3D figure spinning a poi butterfly with hands close together","body":["Siteswap gives jugglers a shared language for throws. Spinners have something similar for two hands and two props: timing and direction. Timing asks whether the hands (or prop heads) reach the same place in the circle at the same moment — together — or half a turn apart — split. Direction asks whether they turn the same way around that circle or opposite ways. Combine the two and you get four basic relationships: together-same, together-opposite, split-same and split-opposite.","Together-same is the first wall spin most people learn: both poi or both staff ends travel as a pair. Split-same is the classic weave foundation, where one head is at the top when the other is at the bottom. Together-opposite looks like a butterfly when the hands sit close: the heads kiss at the top and bottom. Split-opposite is the remaining corner, with opposite directions and staggered timing.","These four states are not just labels. They form a small map. Each relationship shares two cardinal positions — top, bottom, or the far sides — with two of its neighbours. At a shared position you can reverse one hand and step into the neighbouring relationship. That is Transition Theory in everyday language: a circle of legal hops, like a musician’s circle of fifths for spinning. The hops that are forbidden are the ones with no shared position, such as jumping straight between together-opposite and split-same without an intermediate stop.","Hand-to-prop speed ratios sit on top of that map. Plain spin, where the hand and the head travel together, is often called a 1:1 CAP. A four-petal antispin flower is a 1:3 relationship: three head turns for each hand circle. A six-petal antispin (or the matching inspin) is 1:5. SynthFlow’s Timing lab lets you switch CAP presets while the 3D coach keeps the beat, so you can see the flower change without leaving offline practice.","Open Learn → Timing & Direction to explore the four cells, hide one prop to read hybrids more clearly, and drill recognition quizzes that stay on your device. The same words appear in the glossary under same time / split time, butterfly, antispin and flower. Once the map clicks, catalog move names stop feeling arbitrary — they become addresses you can travel between on purpose."]},"sequencing":{"title":"Wie Flow-Routinen aufgebaut sind","summary":"Aufwärmen, einen Fokus mit Links üben, die fließend weitergehen, Temposprünge klein halten und mit einem leichten Cool-down abschließen.","imageAlt":"3D-Figur, die einen Hoop vor dem Körper von Hand zu Hand gibt","body":["Eine gute Flow-Routine hat dieselbe Form wie ein gutes Musikset: einen Anfang, der den Raum aufwärmt, eine Mitte, die aufbaut, und ein Ende, das alle durchatmen lässt. Die integrierten Routinen von SynthFlow folgen dieser Form, und der Co-Pilot des Builders prüft deine daran.","Beginne mit einem Warm-up. Handgelenkskreise, Armkreise und Schulterrollen bringen die Gelenke, die du belasten wirst, bei sanftem Tempo durch ihren Bewegungsumfang. Zwei oder drei Minuten reichen für eine kurze Session; längere Sessions und kalte Tage verdienen mehr.","Gib dem Übungsblock einen Fokus. Wähle eine Bewegung, an der du arbeitest, und umgib sie mit Bewegungen, die hineinfließen. Der Builder zeigt, wie jeder Schritt mit dem vorherigen verbunden ist: direkt aus derselben Handposition weiterfließen, ein kleiner Umgriff, das Prop absetzen oder auf einem früheren Trick aufbauen. Routinen, die fließend weitergehen, fühlen sich wie Tanzen an; Routinen voller Absetzmomente fühlen sich wie eine Liste an.","Halte Tempoänderungen zwischen den Schritten klein. Ein Sprung von 80 auf 130 BPM setzt dein Timing zurück und lädt Drops ein. Der Co-Pilot markiert Sprünge von mehr als etwa einem Viertel und faltet halbes und doppeltes Tempo, sodass ein Hoop-Schritt bei 70 BPM neben einem Track bei 140 BPM sitzen kann.","Kehre mehr als einmal zur Fokusbewegung zurück. Wiederholung über eine Session hinweg, mit anderen Bewegungen dazwischen, baut Skill besser auf als ein langer Block, weil jede Rückkehr ein frischer Versuch von einem etwas anderen Ausgangspunkt ist.","Schließe mit einem Cool-down ab: eine leichte Bewegung bei langsamem Tempo oder eine kurze Pause mit ein paar Atemzügen. Das senkt die Herzfrequenz und gibt deiner Koordination einen ruhigen Abschluss zum Erinnern. Sieh dir die Routine vor dem Abspielen in der Vorschau an und entferne alles, was eindeutig der Ehrgeiz von gestern ist."]},"effort":{"title":"Wann du das Tempo erhöhen solltest","summary":"Erhöhe, wenn die Form hält und du frisch bist; nimm heraus, wenn Peaks wackeln, der Griff fester wird oder Drops sich häufen.","imageAlt":"3D-Figur, die fünf Bälle in einer hohen Cascade jongliert","body":["Fortschritt im Flow entsteht durch Üben an der Grenze deiner Fähigkeiten, aber die Grenze verschiebt sich. An manchen Tagen liegt sie weiter draußen als erwartet; an manchen Tagen ist sie zurückgewichen. Sie lesen zu lernen ist ein Skill, der so viel wert ist wie jeder Trick.","Erhöhe, wenn die Grundlagen halten. Wenn deine Peaks gleichmäßig sind, dein Staff in seiner Ebene bleibt, dein Hoop waagerecht bleibt und deine Atmung leicht ist, nimm die nächste Sprosse der Tempo-Leiter oder probiere die nächste Übung in der Progression. Die ersten fünfzehn Minuten einer Session nach dem Warm-up sind meist die beste Zeit für neues Material.","Nimm heraus, wenn die Qualität nachlässt. Gehäufte Drops, ein fester werdender Griff, Schultern, die zu den Ohren kriechen, und angehaltener Atem sagen alle, dass dein Nervensystem müde ist. Senke das Tempo, geh zurück zu einer Bewegung, die du beherrschst, oder beende die Session. Sich durch Müdigkeit zu pushen, probt meistens Fehler ein.","Achte auch auf körperliche Warnsignale. Wiederholtes Werfen und Spinnen belastet Handgelenke, Unterarme und Schultern. Ein Schmerz, der innerhalb eines Tages nachlässt, ist normale Anpassung. Stechender Schmerz, Schmerz, der während des Übens zunimmt, Taubheit oder Kribbeln sind Gründe zu stoppen und dich auszuruhen; anhaltende Symptome gehören zu einer Ärztin oder einem Arzt.","Nutze die Anstrengungsbewertung nach jeder Session. Der Practice Wizard liest sie: mehrere harte Sessions in Folge und er schlägt etwas Sanfteres vor, mehrere leichte und er schlägt ein wenig mehr vor. Ehrliche Bewertungen führen zu besseren Vorschlägen."]},"drops-are-data":{"title":"Drops sind Daten","summary":"Ein Drop sagt dir, welchen Wurf oder Catch du korrigieren solltest; ihn als Versagen zu behandeln, lehrt dich nur, dich zu verkrampfen.","imageAlt":"3D-Figur, die zwei Jonglierbälle zwischen den Händen austauscht","body":["Jede Jongleurin und jeder Jongleur hat irgendwann einen Boden voller Bälle. Jede Staff-Spinnerin und jeder Staff-Spinner hat das Klappern gehört. Der Unterschied zwischen Menschen, die sich weiter verbessern, und denen, die aufhören, ist selten Talent; es ist der Umgang mit dem Drop.","Ein Drop ist eine Messung. Er sagt dir, welcher Wurf schiefging, nach welchem Catch du gegriffen hast, welcher Moment des Spins seine Ebene verloren hat. Wenn derselbe Ball immer vor dir landet, driften deine Würfe nach vorn. Wenn Drops nach sechs Würfen kommen, stimmt etwas in deinem dritten oder vierten Wurf nicht. Beobachte wo und wann und wähle dann eine Sache, die du änderst.","Drops als Versagen zu behandeln, hat einen Preis. Angst verspannt die Schultern und verkürzt den Atem, und Spannung macht Bewegungen kleiner und schneller, was mehr Drops verursacht. Die ruhige Reaktion — aufheben, atmen, auf den Downbeat warten, neu starten — ist nicht nur angenehm; sie ist die technisch richtige Reaktion.","Zähle saubere Runs, nicht Drops. SynthFlow meistert eine Bewegung, wenn du genug saubere Runs und Übungsminuten hast, also sind Drops unterwegs einfach Teil der Minuten. An manchen Tagen loggst du zehn saubere Runs, an manchen zwei. Beide Tage zählen.","Lass manchmal absichtlich fallen. Wenn du einen neuen Trick lernst, übe den ersten Wurf oder den ersten halben Spin und lass ihn fallen. Füge dann den Catch hinzu. Den riskanten Moment zu isolieren, verkleinert ihn, und du lernst, dass der Boden nicht dein Feind ist. Er ist einfach dort, wo das Prop hingeht, während du lernst."]},"safety":{"title":"Sicherheit: Raum, Props und rote Flaggen","summary":"Räume deine Ebenen, wähle verzeihende Props, wärme dich auf und stoppe bei stechendem Schmerz, Taubheit oder Schwindel.","imageAlt":"3D-Figur, die einen Staff flach über dem Kopf mit klarem Raum drumherum spinnt","body":["Flow Arts sind im Vergleich zu den meisten Sportarten risikoarm, aber Props bewegen sich schnell und fliegen weiter, als du erwartest. Ein paar Gewohnheiten halten das Üben sicher für dich, die Menschen in deiner Nähe und die Möbel.","Räume deinen Raum, bevor du beginnst. Prüfe jede Ebene, die du nutzen wirst: vorn, an den Seiten und oben. Staff und Hoop brauchen mehr Platz, als du denkst, meist einen Kreis von mindestens Armspannweite plus Proplänge in jede Richtung, mit nichts Zerbrechlichem in Reichweite. Drinnen auf Deckenlampen und Ventilatoren achten; draußen auf unebenen Boden und Passanten.","Nutze verzeihende Props beim Lernen. Jonglierbälle aus Bohnensäckchen rollen nicht weg. Gepolsterte Staffs oder Staffs mit Schaumstoffenden tun weniger weh, wenn sie deinen Kopf treffen, was sie tun werden. Ein größerer, schwererer Hoop dreht langsamer und ist leichter oben zu halten. Steig auf schnellere oder auffälligere Props um, sobald die Grundlagen automatisch sitzen.","Wärme dich vor jeder Session auf und steigere das Volumen allmählich. Werfen und Spinnen sind repetitiv, und wiederholte Belastung auf kaltes Gewebe ist die übliche Ursache für schmerzende Handgelenke und Ellbogen. Wenn du plötzlich viel mehr übst, füge auch Ruhetage hinzu.","Stoppe bei roten Flaggen: stechender oder elektrischer Schmerz, Taubheit oder Kribbeln in den Händen, Schmerz, der schlimmer wird, wenn du weitermachst, Schwindel oder ein Schlag auf den Kopf mit irgendwelchen anhaltenden Symptomen. Nackenbewegungen und Contact Rolls verdienen besondere Vorsicht; lerne sie langsam mit einem gepolsterten Prop.","Diese App vermittelt Technik, keine medizinische Versorgung. Schwangerschaft, kürzliche Verletzungen, Gelenkerkrankungen und alles, was dir Sorgen macht, sind Gründe, vor zusätzlicher Belastung eine qualifizierte Fachperson zu fragen. Feuerperformance ist eine eigene Disziplin mit eigener Sicherheitsschulung; SynthFlow unterrichtet sie nicht."]},"warm-up":{"title":"Warum Aufwärmen beim Prop-Training wichtig ist","summary":"Zwei bis fünf Minuten Mobilität für Handgelenke, Arme, Schultern und Hüften machen Spins flüssiger und schonen deine Gelenke.","imageAlt":"3D-Figur macht langsame Handgelenkskreise mit nach vorn gestreckten Armen","body":["Flow-Training sieht sanft aus, verlangt aber einigen Gelenken viel ab. Jonglieren wiederholt denselben Wurf tausende Male; Staff-Spinning rollt die Handgelenke durch ihren vollen Bewegungsumfang; Hooping bewegt Wirbelsäule und Hüften bei jedem Orbit. Warmes Gewebe verträgt diese Wiederholung viel besser als kaltes.","Ein gutes Flow-Aufwärmen ist kurz und spezifisch. Handgelenkskreise in beide Richtungen bereiten die Gelenke vor, die die meiste Arbeit leisten. Armkreise und Schulterrollen wecken die Rotatorenmanschette und die Schulterblätter, die die Ebene jedes Spins kontrollieren. Hüftkreise und Rumpfdrehungen sind beim Hooping am wichtigsten. Halbe Nackenkreise, niemals volle Rollen, lösen Spannung vom Hochschauen auf ein Muster.","Bewege dich langsam und im Takt. Die Aufwärm-Schritte in SynthFlow werden wie alles andere gezählt, in entspanntem Tempo, sodass die ersten Minuten einer Session auch dein Timing stimmen. Wenn die Props herauskommen, bewegst du dich schon mit der Musik.","Beende das Aufwärmen mit dem Prop bei halber Geschwindigkeit. Ein paar langsame Würfe, ein lockerer Front Spin oder ein großer, langsamer Hoop-Orbit verbinden die Mobilitätsarbeit mit der Bewegung, die du gleich übst, und sie sagen dir, wie sich dein Körper heute anfühlt.","Aufwärmen ist auch ein mentaler Übergang. Dieselben drei Minuten zu Beginn jeder Session werden zum Signal, dass das Training begonnen hat. An vollen Tagen ist das Aufwärmen manchmal das ganze Training, und das zählt trotzdem."]},"anatomy-basics":{"title":"Der Körper hinter den Props","summary":"Unterarme greifen und lösen, Schultern steuern die Ebene, der Core hält dich still: eine einfache Karte für Flow.","imageAlt":"3D-Figur hoopet an der Taille mit entspanntem Oberkörper","body":["Du musst keine Anatomie kennen, um zu jonglieren, aber eine einfache Karte hilft dir zu verstehen, was ermüdet, was du aufwärmen und was du ausruhen solltest. Der Bereich Muskeln in Lernen hat ein interaktives Modell; dieser Artikel ist die kurze Tour.","Die Unterarme leisten die meiste Feinarbeit. Muskeln auf der Handflächenseite schließen die Finger und beugen das Handgelenk; Muskeln auf der Rückseite des Unterarms öffnen die Finger und strecken das Handgelenk. Fangen und Loslassen, einen Staff greifen und rollen lassen, all das passiert hier. Unterarmmüdigkeit ist das häufigste Gefühl nach einer langen Session, und deshalb ist entspannter Griff so ein häufiger Cue.","Die Schultern steuern. Die Deltoideus-Muskeln heben die Arme; die Rotatorenmanschette, vier kleine Muskeln um das Gelenk, hält den Oberarm während der Bewegung zentriert. Muskeln um die Schulterblätter halten das ganze System stabil. Wenn ein Staff aus seiner Ebene driftet, liegt die Ursache oft in der Schulter, nicht in der Hand.","Der Core hält dich ruhig. Beim Jonglieren verhindert ein stiller Oberkörper, dass das Muster wandert. Beim Hooping treiben Bauch- und Rückenmuskeln den Hoop mit kleinen Vor- und Zurück-Impulsen an. Hüften und Beine sind deine Basis: weiche Knie absorbieren Bewegung und lassen dich das Gewicht verlagern, ohne das Prop zu stören.","Auch Augen und Innenohr zählen. Jonglieren trainiert dich, die Scheitelpunkte zu beobachten, nicht die Hände; Spinning trainiert dein Gleichgewicht. Kurze Sessions mit Pausen lassen beide sich anpassen, ohne dass dir schwindelig wird. Behandle diese Karte als Grundwissen, nicht als Diagnose, und suche bei Schmerzen, die nicht abklingen, eine Fachperson auf."]},"biomechanics-safety":{"title":"Handgelenke, Schultern und wiederholte Belastung","summary":"Entspannter Griff, neutrale Handgelenke und allmähliche Steigerung halten die Gelenke, die alle Arbeit leisten, zufrieden.","imageAlt":"3D-Figur spinnt einen Staff mit einer Hand über dem Handrücken","body":["Flow-Verletzungen sind selten dramatisch. Sie sind fast immer Überlastung: zu viele Wiederholungen, zu viel Griff, zu wenig Ruhe. Die gute Nachricht: Dieselben wenigen Gewohnheiten verhindern die meisten davon.","Locker den Griff. Ein Jonglierball braucht nur so viel Druck, dass er in der Hand bleibt; ein Staff braucht einen lockeren Fingerring, in dem er rollen kann. Zudrücken ermüdet die Unterarmmuskeln und belastet die Sehnen am Ellbogen. Wenn deine Knöchel weiß werden oder die Unterarme nach ein paar Minuten brennen, lockere und senke das Tempo.","Halte die Handgelenke möglichst nah an neutral. Spinning führt die Handgelenke durch große Bewegungsumfänge, was in Maßen in Ordnung ist. Sie lange am Ende ihres Bereichs zu halten oder ein steifes Handgelenk zum Drehen zu zwingen, reizt sie. Lass Ellbogen und Schulter die Bewegung mit tragen.","Lass die Schultern arbeiten, aber nicht hochziehen. Große Kreise kommen aus dem Schultergelenk; eine hochgezogene Schulter klemmt und ermüdet schnell. Prüfe im Spiegel oder im Kameramodus, dass deine Schultern unten bleiben, besonders bei Überkopf-Bewegungen wie Helicopter und Lasso.","Steigere das Volumen allmählich. Wenn du normalerweise zwanzig Minuten übst, spring nicht auf zwei Stunden, weil ein Festival kommt. Erhöhe die Gesamtzeit jede Woche um einen moderaten Betrag und halte mindestens einen leichten Tag ein. Wechsle Props, um die Last zu verteilen: Hoop-Arbeit entlastet die Unterarme, die Jonglieren ermüdet.","Schmerz, der innerhalb eines Tages nachlässt, ist normale Anpassung; Schmerz, der bleibt, wächst oder mit Taubheit kommt, ist es nicht. Ruhe dich aus, reduziere das Volumen und suche professionellen Rat, wenn er anhält. Das ist Bildung, keine medizinische Beratung."]},"choosing-props":{"title":"Die ersten Props auswählen","summary":"Beanbags zum Jonglieren, ein leichter gepolsterter Staff und ein großer Erwachsenen-Hoop machen die ersten Wochen viel einfacher.","imageAlt":"3D-Figur spinnt einen Hoop um eine Hand","body":["Gute Anfänger-Props machen das Lernen schneller und weniger frustrierend. Du brauchst keine teure Ausrüstung, aber ein paar Entscheidungen sind wichtig.","Beginne beim Jonglieren mit drei Beanbag-Bällen von etwa 60 bis 130 Gramm. Beanbags springen oder rollen nicht weg, wenn sie fallen, was viel Hinterherlaufen spart. Sie sollten bequem in deine Handfläche passen. Stage Balls, die größer sind, und springende Silikonbälle sind für später. Gleiche Farben helfen dir, das Muster zu sehen; drei verschiedene Farben helfen dir, einzelne Bälle zu verfolgen, wenn du Siteswaps lernst.","Für Staff ist ein Anfänger-Spin-Staff meist etwa 1,2 bis 1,5 Meter lang, leicht, mit gepolsterten oder Gummi-Enden. Als grobe Orientierung sollte er zwischen Brust und Schulter reichen, wenn er aufrecht steht. Ein längerer, schwererer Staff dreht langsamer und flüssiger, sobald du die Grundlagen hast, aber er ist am Anfang schwieriger und tut mehr weh, wenn er dich trifft. Ein Griff in der Mitte hilft.","Beginne beim Hoop größer und schwerer, als du denkst. Ein Erwachsenen-Anfänger-Hoop reicht typischerweise etwa zwischen Taille und Brust, wenn er auf dem Boden steht. Größere Hoops drehen langsamer und geben dir Zeit, den Rhythmus für Waist Hooping zu finden. Kleinere, leichtere Hoops eignen sich für schnelle Off-Body-Tricks, sobald du dich wohlfühlst.","Was auch immer du wählst, stelle sicher, dass der Tempo-Bereich der Bewegung zum Prop passt. Schwerere Props mögen meist niedrigere Tempi. Wenn sich der komfortable Bereich der App mit deinem Prop gehetzt anfühlt, setze dein eigenes Tempo im Builder; die Counts folgen."]},"practice-at-home":{"title":"Zu Hause und im Park üben","summary":"Kurze tägliche Sessions, ein freier Platz, eine Bett- oder Sofakante zum Auffangen von Drops und eine Park-Jam, wenn du kannst.","imageAlt":"3D-Figur schüttelt zwischen Trainingsrunden die Arme aus","body":["Die meisten Flow-Artists lernen zu Hause, ein paar Minuten auf einmal. Ein wenig Vorbereitung macht Heimtraining leichter zu beginnen und leichter durchzuhalten.","Finde deinen Platz. Beim Jonglieren bedeutet Stehen vor einem Bett oder Sofa, dass fallende Bälle auf Taillenhöhe landen, statt unter Möbel zu rollen, und es hält dich auch davon ab, nach vorn zu laufen. Für Staff und Hoop finde den größten freien Platz, den du hast, prüfe die Decke und räume alles Zerbrechliche weg. Ein Garten oder Park ist besser für große Spins.","Halte die Props sichtbar. Bälle auf dem Schreibtisch werden während Calls und Teepausen jongliert; ein Hoop an der Tür wird benutzt. Je weniger Aufwand es braucht anzufangen, desto öfter wirst du es tun. Eine Fünf-Minuten-Routine zählt, und mehrere kurze Sessions am Tag summieren sich schnell.","Nutze die App als Struktur. Wähle eine Routine oder lass dir vom Assistenten eine vorschlagen, spiele sie durch und protokolliere deinen Aufwand. Kurze Programme wie Zero to Cascade geben jeder Woche ein klares Ziel, damit du nicht zwischen Tricks umhertreibst.","Übe mit anderen, wenn du kannst. Jonglierclubs, Zirkusschulen und Park-Flow-Jams gibt es in vielen Städten. Jemandem zuzusehen, der einen Schritt voraus ist, löst oft etwas, das ein Tutorial nicht konnte, und jemandem etwas beizubringen, der einen Schritt hinter dir ist, macht deine eigene Technik klarer. Bring deine Props mit, frag, woran die Leute arbeiten, und teile, was dir die Counts beigebracht haben."]},"learning-with-the-app":{"title":"Lernen mit dem 3D-Coach","summary":"Verlangsame es, spiegle es, schalte Ghost und Trails ein, wechsle die Kamera und nutze den Kameramodus für Feedback.","imageAlt":"3D-Figur führt eine Staff-Isolation aus, mit einem Trail, der den Weg zeigt","body":["Jede Bewegung in SynthFlow wird in 3D von derselben Uhr wie die Musik animiert, sodass die Figur immer genau auf dem Beat ist. Gut genutzt ist der Viewer ein geduldiger Lehrer, der nie müde wird, dir denselben Wurf zu zeigen.","Verlangsame es zuerst. Die Progressionsleiter bei jeder Bewegung beginnt mit langsamen und teilweisen Versionen, dann nur Hände, dann die vollständige Bewegung auf dem Beat. Halbes Tempo bewahrt die Timing-Beziehungen und gibt deinen Augen Zeit zu folgen.","Spiegle die Figur, wenn du besser lernst, wenn du einem Lehrer gegenüberstehst, und wechsle die Kamera, wenn eine Ansicht etwas verdeckt. Seitenansichten zeigen Staff-Neigung und Wurf-Drift; Draufsichten zeigen Hoop-Ebenen und Helikopter-Bahnen. Die Trails zeichnen auf, wo jeder Prop gewesen ist, was einen Blur in eine Form verwandelt, die du studieren kannst. Der Ghost zeigt, wo der Prop beim nächsten Beat sein wird.","Achte auf die häufigen Fehler. Jede Bewegung kann ihre typischen Fehler zeigen, wie nach vorne driften, ungleiche Höhen oder hetzen, absichtlich falsch an der Figur vorgeführt, mit dem Cue, der sie behebt. Einen Fehler am Modell zu erkennen, macht es viel leichter, ihn im eigenen Körper zu spüren.","Der Kameramodus gibt dir Feedback über dich. Mit Erlaubnis verfolgt er deine Hände und deinen Körper während du übst und vergleicht dein Timing mit dem Beat. Die Verarbeitung findet auf deinem Gerät statt. Es ist nicht perfekt, und gutes Licht hilft, aber selbst grobes Feedback darüber, ob du zu früh oder zu spät bist, ist wertvoll.","Schließe den Viewer schließlich manchmal. Übe nur mit Musik und vertraue den Counts. Das Ziel ist eine Bewegung, die du ausführen kannst, ohne überhaupt etwas anzusehen."]},"music-for-flow":{"title":"Musik finden, die passt","summary":"Gemessene Tempi, Halb- und Doppelzeit, generierte Percussion und deine eigenen Tracks halten die Counts ehrlich.","imageAlt":"3D-Figur hoopt auf Brusthöhe mit erhobenen Armen","body":["Musik verwandelt Übung in Flow, aber nur, wenn der Beat in der Musik der Beat in den Counts ist. Ein Track mit 118 BPM unter einer 120-BPM-Routine driftet innerhalb einer Minute auseinander, und du kämpfst am Ende gegen die Musik, statt sie zu reiten.","SynthFlows mitgelieferte Tracks haben gemessene Tempi und Downbeats, sodass der Player jeden Schritt auf der „Eins“ der Musik starten und die Counts ausgerichtet halten kann. Der Builder listet zuerst Tracks auf, die zum Tempo eines Abschnitts passen, einschließlich Tracks mit halbem oder doppeltem Tempo: Ein 140-BPM-Track trägt einen 70-BPM-Hoop-Schritt problemlos.","Generierte Percussion funktioniert bei jedem Tempo. Wähle ein Kit für einen Abschnitt, und der Player synthetisiert einen Beat, der genau passt, egal ob du eine Tempo-Leiter oder eine langsame Drill machst. Es ist auch die beste Option, wenn du den Puls willst, ohne dass eine Melodie deine Aufmerksamkeit zieht.","Du kannst Tracks von deinem eigenen Gerät analysieren. Die App schätzt Tempo und Downbeat und lässt dich sie durch Mitklopfen überprüfen. Tracks mit einem gleichmäßigen elektronischen oder akustischen Puls funktionieren am besten; Musik mit Tempoänderungen, Rubato oder langen Intros ist schwerer zu messen und schwerer zum Üben.","Video-Streaming ist während gezählter Übung ausgeschaltet, weil sein Timing nicht präzise kontrolliert werden kann. Nutze es stattdessen für Warm-ups oder freies Spielen, wo nichts übereinstimmen muss."]},"plateaus":{"title":"Plateaus und die lange Mitte","summary":"Jeder Flow-Artist erlebt Wochen, in denen nichts besser wird; ändere die Drill, das Tempo oder den Prop, bevor du das Ziel änderst.","imageAlt":"3D-Figur jongliert Mills Mess mit gekreuzten Armen","body":["Der Anfang des Flow ist wunderbar: jede Session etwas Neues. Dann, oft etwa zu der Zeit, in der du eine stabile Cascade jonglieren oder einen Hoop unbegrenzt oben halten kannst, scheint der Fortschritt zu stoppen. Diese lange Mitte ist der Punkt, an dem die meisten aufhören, und wo das interessanteste Lernen stattfindet.","Plateaus sind meistens Konsolidierung. Dein Nervensystem reorganisiert die Bewegung, damit sie weniger Aufmerksamkeit braucht, was sich nicht als neue Tricks zeigt. Oft taucht eine Fähigkeit, die sich zwei Wochen festgefahren anfühlte, plötzlich eines Morgens auf. Übe weiter durch den flachen Teil hindurch.","Ändere die Drill, nicht das Ziel. Wenn die Cascade nicht schneller wird, übe sie bei niedrigerem Tempo mit perfekten Peaks, dann mit den Augen auf einem Punkt über dem Muster, dann nur mit einer Hand. Wenn eine Staff-Bewegung nicht kommt, teile sie in ihre Hälften und drille jede auf den Beat. Neue Drills geben deinem Gehirn neue Informationen über dieselbe Fähigkeit.","Cross-Training. Einen zweiten Prop zu lernen, entsperrt oft den ersten. Hooping verbessert den Rhythmus hinter dem Jonglieren; Staff-Arbeit lehrt die Ebenen, die Hoop-Tricks sauber machen. Der Rewards-Baum für jede Kunst ist unabhängig, also kostet Vielfalt nie Fortschritt.","Sei freundlich zu dir. Vergleiche dich mit dem letzten Monat, nicht mit Performern online, die zehn Jahre geübt haben. Die Progress-Seite führt eine ehrliche Aufzeichnung von Minuten, Top-Tempi und gemeisterten Bewegungen. In einer flachen Woche schau sie an und sieh, wie weit die Linie bereits geklettert ist."]},"history-of-juggling":{"title":"Eine kurze Geschichte des Jonglierens","summary":"Von einem ägyptischen Grabmal über mittelalterliche Jongleure, Varietétheater und moderne Mathematik.","imageAlt":"3D-Figur jongliert eine Three-Ball-Shower im Kreis","body":["Jonglieren ist sehr alt. Eines der frühesten bekannten Bilder ist eine Wandmalerei in einem Grab des Mittleren Reiches in Beni Hasan in Ägypten, etwa viertausend Jahre alt, die Frauen beim Ballwerfen zeigt. Berichte und Bilder aus China, Griechenland, Rom und dem Pazifik deuten darauf hin, dass Menschen in vielen Kulturen zum Werfen und Fangen zur Schau und zum Spiel gefunden haben.","Im mittelalterlichen Europa beschrieb das Wort Jongleur, von dem „Juggler“ stammt, reisende Unterhalter, die sangen, Geschichten erzählten, Akrobatik vorführten und Gegenstände warfen. Jonglieren war eine Fähigkeit unter vielen, Teil des Werkzeugkastens eines Performers statt eine eigene Kunst.","Die Varietétheater und Zirkusse des neunzehnten und frühen zwanzigsten Jahrhunderts machten Jonglieren zur Hauptattraktion. Performer spezialisierten sich: Gentleman-Jongleure mit Hüten und Stöcken, Club-Jongleure und Numbers-Jongleure, die zu sieben, acht und mehr Bällen strebten. Enrico Rastelli im frühen zwanzigsten Jahrhundert wird noch heute oft als einer der Größten genannt.","Ab den 1970er Jahren wuchs eine Hobby-Jonglierkultur rund um Clubs, Festivals und Conventions, in der Menschen Tricks frei teilten. Die Mathematik kam in den 1980er Jahren dazu, als die Siteswap-Notation Jongleuren eine Möglichkeit gab, Muster als Zahlen zu schreiben, was zu neuen Tricks führte, die auf dem Papier entdeckt wurden, bevor sie jemand warf.","Heute liegt Jonglieren am Treffpunkt von Zirkus, Sport, Tanz und Mathematik. Manche Jongleure treten in Numbers und Ausdauer an, andere führen Choreografien zu Musik auf, andere erkunden Muster um ihrer selbst willen. Jeder Weg beginnt mit demselben Austausch von zwei Bällen, den du diese Woche lernen kannst."]},"history-of-staff":{"title":"Staff-Spinning: von der Waffe zum Flow","summary":"Kampfkunst-Staffs, Baton Twirling und Feuerperformance haben alle den modernen Spin-Staff genährt.","imageAlt":"3D-Figur führt einen Staff-Butterfly hinter den Schultern aus","body":["Ein Staff ist eines der ältesten Werkzeuge überhaupt, und einen zu spinnen ist eine alte Fähigkeit. Viele Kampftraditionen trainieren mit einem langen Staff, darunter der okinawanische Bō, das chinesische Gun und der europäische Quarterstaff-Kampf, und ihre Drills umfassen schnelle Spins und Handwechsel sowohl zur Verteidigung als auch zur Schau.","Performance-Spinning hat auch andere Wurzeln. Baton Twirling entwickelte sich im zwanzigsten Jahrhundert zu einer Wettkampfdisziplin, mit Würfen, Rolls und Spins, die Spinner noch heute borgen. Theater, Paraden und Straßenperformance auf der ganzen Welt nutzten gedrehte Stöcke und Stangen lange bevor jemand es Flow nannte.","Die moderne Flow-Staff-Szene entstand im späten zwanzigsten Jahrhundert zusammen mit Feuerperformance und Festival-Kultur. Feuer-Staffs mit Dochten an beiden Enden machten das Spinnen im Dunkeln sichtbar und drängten die Kunst zu fließenden, kontinuierlichen Bewegungen statt Schlägen. LED-Staffs brachten dieselben Visuals später in den Innenraum.","Etwa zur selben Zeit begannen Flow-Artists, das Spinnen mit gemeinsamer Theorie zu beschreiben: Ebenen, Spin und Antispin, Isolations, Timing und Richtung. Vieles davon wurde in der Poi-Community entwickelt und auf Staff, Hoop und andere Props übertragen, weshalb dieselben Begriffe in dieser App überall auftauchen.","Contact Staff, bei dem der Staff über den Körper rollt statt gegriffen zu werden, entwickelte sich zu einem eigenen Stil mit Rolls über Nacken, Schultern und Arme. Heute reicht Staff-Spinning von martialischer Demonstration bis zu langsamem, meditativem Contact Flow, alles aufgebaut auf demselben ersten Wheel Spin."]},"history-of-hoop":{"title":"Der Hoop: vom antiken Spielzeug zur Flow-Kunst","summary":"Hoops sind seit Jahrtausenden Spielzeug und Werkzeug; ein Trend der 1950er und ein Festival-Revival machten Hoop Dance zur Kunst.","imageAlt":"3D-Figur, die einen spinnenden Hoop am Körper hochführt","body":["Hoops gehören zu den ältesten Spielzeugen. Kinder im alten Ägypten, in Griechenland und Rom werden beschrieben oder abgebildet, wie sie Hoops mit Stöcken rollen und um den Körper spinnen, und Hoop-Spiele tauchen seitdem in vielen Kulturen auf.","Hoops tragen in manchen Traditionen auch tiefe kulturelle Bedeutung. Der Hoop Dance, der in vielen Native-American-Communities aufgeführt wird, nutzt mehrere Hoops, um Formen wie Tiere und die Erde zu bilden und Geschichten durch Bewegung zu erzählen. Er ist eine lebendige Tradition für sich, verschieden von der modernen Flow-Szene, und es lohnt sich, von ihren eigenen Praktizierenden darüber zu lernen.","Der Plastik-Hula-Hoop-Trend der späten 1950er, angetrieben von massenproduzierten Hoops in den Vereinigten Staaten, brachte fast über Nacht einen Hoop in Millionen Haushalte. Jahrzehntelang danach galt der Hoop meist als Kinderspielzeug und Fitness-Gadget.","Ab den späten 1990ern und 2000ern begannen erwachsene Hooper auf Festivals und in Online-Communities, den Hoop als Tanzpartner zu behandeln. Größere, schwerere handgemachte Hoops machten On-Body-Hooping für Erwachsene einfacher, während kleinere Hoops schnelle Off-Body-Tricks eröffneten. Geteilte Videos verbreiteten Vokabular wie Isolations, Wedgies und Escalators weit über eine einzelne Stadt hinaus.","Moderner Hoop Dance leiht sich Theorie von Staff und Poi und Rhythmus aus jeder Art von Musik. Er ist zugänglich, freudvoll und tief: Ein Anfänger findet den Hüftrhythmus an einem Tag, und ein Experte kann Jahre damit verbringen, eine einzige Isolation zu verfeinern."]},"fire-and-led":{"title":"Feuer-, LED- und Performance-Props","summary":"Performance-Props verändern Gewicht, Geschwindigkeit und Risiko; lerne jede Bewegung zuerst mit Übungs-Props und trainiere Feuer separat.","imageAlt":"3D-Figur, die einen Hoop flach über dem Kopf wie ein Lasso kreisen lässt","body":["Einen Feuer-Staff oder einen LED-Hoop bei Nacht zu sehen, ist oft das, was Menschen zum Flow bringt. Performance-Props sind wunderbar, aber sie sind nicht dasselbe wie Übungs-Props, und der Umstieg auf sie verdient einen Plan.","LED-Props sind wegen Batterien und Elektronik meist schwerer als ihre Übungsversionen. Das verändert den Impuls: Spins tragen weiter, Throws fühlen sich anders an, und die Handgelenke arbeiten härter. Lerne jede Bewegung zuerst mit deinem Übungs-Prop und rechne dann mit einer kurzen Umstellungsphase auf LED. Senke das Tempo für die ersten Sessions.","Feuerperformance ist eine eigene Disziplin. Umgang mit Brennstoff, sichere Spin-Bereiche, Safety-Spotters mit Feuerlöschdecken, geeignete Kleidung und lokale Regeln sind alle wichtig, und man lernt sie am besten persönlich von erfahrenen Feuer-Performern. SynthFlow unterrichtet kein Feuer, und nichts in der App sollte mit brennenden Props geübt werden.","Eine gute Regel, die in vielen Flow-Communities gilt, ist: Führe eine Bewegung erst dann mit einem Performance-Prop aus, wenn du sie zuverlässig viele Male hintereinander mit einem Übungs-Prop kannst. Unter Lichtern oder Flammen ist kein Raum für Experimente.","Performance verändert auch, wie du sequenzierst. Publikum liest große Ebenen, saubere Übergänge und klare Momente der Stille. Baue Performance-Routinen im Builder wie jede andere, sieh sie dir in der Vorschau an und probt sie jedes Mal zur selben Musik, damit die Counts zur Choreografie werden."]},"cap-notation":{"title":"Speed ratios and CAP-style notation","summary":"Read hand:head speed ratios and the Θ1 Θ2 ; ρ1 ρ2 shorthand used in community CAP papers — without confusing speed ratio with assembly CAPs.","imageAlt":"3D figure drawing a four-petal antispin flower with poi","body":["Spinners share two related languages that are easy to mix up. The first is a simple speed ratio: how many times the prop head turns for each hand circle. Plain forward spin is 1:1. A three-petal antispin flower is often 1:2, a four-petal flower is 1:3, and a six-petal flower is 1:5. SynthFlow’s Timing lab and viewer chip show this as a speed ratio so you can compare flowers without memorising petal counts alone.","The second language comes from community papers on Continuous Assembly Patterns. A pattern is written as two harmonic turns and two length moduli: Theta1 Theta2 ; Rho1 Rho2. Theta1 is usually the arm’s turn rate; Theta2 is the relative turn of the head. Rho1 and Rho2 are relative lengths of the arm path and the tether path. When the two lengths match, Rho1 equals Rho2, and the curve is a rosette — the familiar even flower. When the lengths are tuned so tip and hand appear to move at the same audience speed, the curve is a cycloid. SynthFlow shows a derived readout such as 1 −3 ; 1 1 for four-petal antispin; it does not yet let you free-edit Rho while keeping petal math intact.","Hybrid and assembly CAP are different ideas that both use the word CAP in older writing. A hybrid here means two hands running different elementary patterns in parallel — for example one hand isolating while the other extends (a cateye). An assembly CAP means chaining elementary patterns in series on one prop into one longer cycle. SynthFlow’s catalog already ships many parallel hybrids; serial assembly remains a future explorer. Quizzes ask you to tell those ideas apart so the vocabulary stays sharp.","Use the Timing lab Notation panel while you change speed-ratio presets. Watch the Θ2 sign flip for antispin, stay positive for inspin, and land on 1 1 for plain spin. Link that picture to the Transition Theory map: the same flower can sit in together-same or split-same, and legal hops still follow shared cardinals. For deeper reading, community HTML references are linked from Credits and from the Timing page footer — SynthFlow ships original coaching copy offline and does not bundle third-party PDFs.","Practice tip: pick one speed ratio for a whole practice block. Name it out loud on the downbeat — “one to three” — before you change petals. When the ratio is stable, change timing or direction instead. That separation of concerns is what makes the four-cell map and the flower language work together instead of fighting in your head."]},"spinning-geometry":{"title":"Spinning geometry: symmetry to timing and direction","summary":"Choose a symmetry — central point, vertical axis, or horizontal axis — and land on the matching timing and direction cell.","imageAlt":"3D figure in a poi butterfly, opposite direction same time","body":["One way to invent poi patterns is to start from geometry instead of from move names. Pick a shape that has a clear symmetry, then ask which rotation of the hands respects that symmetry. Community writing (often summarised as a “symmetry method”) maps three everyday symmetries onto the same Timing and Direction grid SynthFlow already uses.","Central-point symmetry means the pattern looks the same if you rotate it around a centre in the plane. That configuration lands on same direction with split time — the split-same cell, the foundation under weaves and chase patterns. Vertical-axis symmetry mirrors left and right across a vertical line through the body; that wants opposite direction with same (together) time — the butterfly family. Horizontal-axis symmetry mirrors across a waist-high line and wants opposite direction with split time — the remaining opposite corner of the map.","Together-same, the first wall spin many people learn, is not forced by those three symmetries alone. It still matters as a neighbour on the transition map: you can hop into it from together-opposite at the top or bottom, or from split-same at the sides. Thinking in symmetries does not replace Transition Theory; it gives you a reason to visit three of the four cells on purpose.","Open Learn → Timing → Symmetry and tap each symmetry while watching the coach. Hide one prop if the picture is busy. Then take the built-in poi-symmetry-lab routine and visit vertical, central, and horizontal cells with catalog moves you already own. The quiz bank asks both directions: given a clip, name the symmetry; given a symmetry label, recognise the timing and direction.","When you improvise, try one constraint per phrase: “this phrase is vertical-axis only.” Stay in together-opposite until the phrase ends, then hop legally into a neighbour. Geometry becomes a compositional tool instead of a trivia fact, and your transitions stay clean because you already know which cardinals you share with the next cell."]},"hybrid-math":{"title":"Hybrid drivers: spin, isolation, extension, cateye","summary":"Treat each hand as a driver on a unit circle where poi length matches an isolation diameter, then mix same and split timing.","imageAlt":"3D figure performing a poi cateye hybrid","body":["A hybrid in this sense is two hands doing different elementary jobs at once. One hand may spin while the other isolates; one may extend while the other draws a cateye almond; both may isolate in split time. Community hybrid maths treat those jobs as drivers on a shared configuration space. A useful picture is a unit circle where the poi length is about the diameter of an isolation — the hand path of a cateye or extension variant sits on that scale so the two shapes can nest cleanly.","SynthFlow already encodes many of these pairs. Petal tuples such as [4, 0] mean the right hand draws a four-petal antispin while the left keeps plain spin. Extension flags and isolation petals build cateyes and iso–spin pairs. Plane hybrids swap wall, wheel and floor mid-cycle. The Hybrids tab in the Timing lab lays a small grid of timing (same or split) against drivers (spin, isolation, extension, cateye) so you can see the live coach without hunting the catalog first.","Hide one prop when the pattern is asymmetric. Your eyes need a clean read of each driver’s path before you put both back. Count slowly. Name the right hand’s job on the odd beats and the left hand’s job on the even beats until the labels stick. Then restore both props and keep the same names — the hybrid is still two simple patterns, not one mysterious blob.","Quizzes ask which hand is isolating versus spinning, and whether the timing is same or split. The poi-hybrid-session routine and the progression week after antispin start give you a practice path that stays offline. For plane-change hybrids such as wall-to-wheel, remember the switch wants a shared line between planes; for driver hybrids, the switch is about roles, not planes.","Keep vocabulary honest: parallel hybrids are not the same as serial assembly CAPs. If you are chaining stalls into flowers on one hand over time, that is assembly thinking. If both hands run different drivers in the same cycle, that is hybrid thinking. The glossary entries for hybrid, assembly CAP, and speed ratio keep those three ideas separated so coaching cues stay short."]},"degrees-and-weaves":{"title":"Degree of twist and weave counts","summary":"Count weaves in beats or in degree-of-twist labels such as −1_0_+1 for three-beat and −2…+2 for five-beat patterns.","imageAlt":"3D figure in a three-beat poi weave","body":["Weaves sit on split timing: one poi is high when the other is low, and the planes trade sides of the body. The classic three-beat weave crosses after three beats of that split foundation; the two-beat weave crosses faster; the five-beat weave stays longer on each side. SynthFlow already ships these as catalog moves. Degree-of-twist language adds another counting layer without changing how long a beat is.","In that language a three-beat phrase can be written with labels that step through minus one, zero, and plus one — compactly −1_0_+1. A five-beat phrase stretches to −2_-1_0_+1_+2. The signs describe facing and twist relative to the body line: facing inside versus facing outside, outswing versus inswing. Advanced inversions and introversions belong in the glossary as future vocabulary; this pass does not add new inversion generators to the catalog.","In Settings → Timing you can choose weave count style: beats (the default spoken one–two–three) or degrees (the pattern index spoken while the degree labels are what the theory names). The beat clock length does not change — only the cue mapping. Use degrees when you are studying notation; use beats when you are linking to music phrases.","Practice the poi-weave-degrees routine after you own the three-beat weave. Add the five-beat week on the weave ladder progression when the longer side stays clean. On the Timing lab, remember that weaves live in the split-same neighbourhood of the map; legal hops out of a weave still want shared cardinals, just like any other split-same pattern.","Quiz items ask you to match a notation string or a weave clip to two-beat, three-beat or five-beat families. Say the degree string once before you spin, then spin without talking. When the string and the body agree, you can improvise crossings without losing the split foundation underneath."]},"staff-vtg":{"title":"Staff theory: two ends, timing and direction","summary":"How Vulcan Tech Gospel timing and direction apply when both ends of a staff are visible, plus snapshots and speed ratios.","imageAlt":"3D figure drawing a four-petal antispin flower with a staff","body":["Siteswap gives jugglers digits for throws. Staff spinners share a different language with poi and clubs: timing and direction. Timing asks whether the two ends (or two hands on double staff) reach matching places in the circle together or half a turn apart. Direction asks whether they turn the same way or opposite ways. Those four relationships — together-same, together-opposite, split-same, split-opposite — are the backbone of community spin theory often summarised as Vulcan Tech Gospel.","A staff shows both ends at once. When you isolate the centre, one end extends while the other draws the complementary path. Clubs show only one end, so isolation and extension feel like separate moves even when the underlying geometry is the same. In the Timing lab, switch the prop to staff and watch both tips leave trails; that picture is the snapshot idea — a still of arms and props across an axis that you can compare between patterns.","Speed ratios sit on top of the map. Plain spin is 1:1. Four-petal antispin is a 1:3 relationship; six-petal is 1:5. SynthFlow’s lab presets flip those ratios while the beat clock stays steady. Legal transitions still hop only between cells that share a cardinal — top, bottom, or the sides — just as in the poi Timing map.","Double staff borrows the same four cells with one short staff in each hand. Same-time wheels and split-time wheels are addresses on that map, not separate mysteries. Choreography systems such as The Kinetic Alphabet write sequences as pictographs on this geometry; SynthFlow links out for that sheet-music layer and does not ship letter charts.","Open Learn → Timing, choose staff, and drill the quiz in staff mode. Then take a flower or symmetry routine from the catalog. Name the cell out loud before you change petals. When the map and the ends agree, improvisation stops feeling like a list of trick names and starts feeling like travel between addresses."]},"contact-staff-map":{"title":"Contact staff: rolls, wraps and open hands","summary":"A map of contact classes — fishtail, rolls, angel, palm — by body point and plane, without inventing a siteswap for contact.","imageAlt":"3D figure performing a staff fishtail on the open hand","body":["Contact staff means the prop travels across skin and clothing instead of living in a tight grip. There is no community-wide digit system like siteswap for contact. What teachers share is a taxonomy: what kind of contact (roll, wrap, stall, fishtail), where on the body it happens, and which plane the staff sits in while it travels.","Fishtails keep the staff pivoting on an open hand or wrist while the ends draw linked circles front and back. Hand rolls and forearm rolls send the staff across a surface without a catch in the middle. Angel rolls carry that idea across the upper back from arm to arm. Palm spins and steering-wheel turns keep contact but stay more held. Neck and shoulder rolls need padding and clear space — learn them slowly with a soft staff.","Entries and exits matter as much as the middle. Many contact phrases start from a held spin, open the hand at a known beat, ride the roll, then catch again. SynthFlow’s contact explorer lets you preview catalog contacts by class and plane offline so you can see the family before you drill. The quiz asks you to name the family from a short clip.","Treat contact as a second language beside tech spinning. Timing and direction still describe held patterns; contact adds body points and roll direction. Do not force one notation to cover both. Community research notes and forum taxonomies are linked from Credits for operators; the app ships original coaching copy only.","Practice tip: pick one contact class for a week. Fishtail until both hands feel even, then add a hand roll on the same plane. Use the staff-contact-session routine after foundations. Stop when the staff chatters or your wrists tighten — contact rewards soft hands more than ambition."]},"hoop-on-off-body":{"title":"Hoop map: on-body, off-body and planes","summary":"Hoop has no siteswap. Learn the teaching map — on-body versus off-body, horizontal versus vertical planes, and the transitions between them.","imageAlt":"3D figure waist hooping with a relaxed upper body","body":["Juggling has siteswap. Staff and poi share timing and direction. Hoop dance’s closest “theory” is a map, not a digit string. The first axis is on-body versus off-body: is the hoop riding a body zone (waist, chest, knees) or spinning in the hands away from the torso? The second axis is plane: horizontal work parallel to the floor (lasso, vortex, waist orbits) versus vertical work in the wall or wheel plane (weaves, hand spins, many isolations).","Most beginner curricula walk that map on purpose. Waist hooping both ways, then hips and chest, builds on-body rhythm. Off-body vertical weaves and hand spins free the torso. Horizontal tricks above the head open a second plane. Transitions such as escalators, spirals and hinges are the roads between cells — not decorations.","SynthFlow’s Hoop lab lays those axes over live catalog moves. Pick on-body or off-body, pick a plane, pick a family, and watch the coach. Quizzes ask you to classify a clip. Routines such as hoop-plane-lab force you to visit more than one cell in a session so the map sticks in your body as well as your head.","Unit-circle thinking from spinning props still helps. A hoop cateye nests isolation and extension-like paths so the rim draws an almond; the same isolation diameter idea appears in poi hybrids. You do not need equations to use the picture — keep the hoop’s path size matched when you combine floating isolations with open extensions.","Further reading lives on community curriculum sites linked from Credits. SynthFlow does not ship paid course video. Use the lab offline, then take one transition — waist to escalator, or weave to lasso — and repeat it until the change feels boring. Boring transitions are the ones you can dance with."]},"hoop-isolations-and-breaks":{"title":"Hoop isolations and breaks","summary":"Isolations make the hoop look frozen or floating; breaks intentionally interrupt spin to change direction or plane.","imageAlt":"3D figure holding a hoop isolation in the wall plane","body":["An isolation is the illusion that one point of the hoop stays still in space while the rest of the rim turns. Linear isolations slide that freeze point along a line; circular or centred isolations keep the float in one place. Cateyes close the rim toward the audience so the hoop reads as a narrow almond before it opens again. Ghosting traces with the free hand to sell the float.","A break is different. Instead of keeping continuous spin, you interrupt the hoop’s path — a paddle, a pinch, a shoulder break — so direction, plane or body zone can change. Off-body breaks train timing with the hands first; on-body breaks ask the core and shoulders to catch the same idea. Reversals flip the spin direction without dropping the phrase.","In SynthFlow, isolation and cateye modes already exist on the hoop generator. The Hoop lab groups them under the isolation family next to body spins, weaves, escalators and passes. Quizzes ask isolation-versus-spin and family identification. The hoop-isolation-session routine drills float before you stack breaks.","Keep cues short. For isolations: “freeze the far point, walk the hands.” For breaks: “stop the circle on purpose, then choose the next plane.” Tempo should drop when you first learn either skill; momentum hides mistakes until the hoop falls behind the beat.","Link isolations to the shared geometry article trail — hoop cateye and poi/staff isolation diameter are cousins. Link breaks to sequencing: a break is a punctuation mark in a counted phrase. Once both feel clean, on–off-body transitions stop being scary because you already own the ways to interrupt and restart the hoop’s story."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Der Tag, an dem die Cascade klickte","summary":"Drei Wochen lang Bällen hinterherjagen endeten in dem Moment, als ich aufhörte, meine Hände zu beobachten, und anfing zu zählen.","body":["Drei Wochen lang hielt meine Drei-Ball-Cascade genau vier Würfe. Rechts, links, rechts, und dann war der dritte Ball irgendwo hinter dem Sofa. Ich schaute Videos, ich wurde langsamer, ich wurde schneller. Ich stellte mich vors Bett, wie jedes Tutorial sagt. Nichts änderte sich, außer meinem Vokabular.","Die Lösung, als sie kam, war peinlich einfach. Ich legte einen Track mit 90 BPM auf und sagte die Counts laut: eins, zwei, drei, vier, ein Wurf auf jeden Beat. Plötzlich hatten die Würfe einen Ort, an dem sie sein mussten. Statt zu werfen, wenn die Hand sich bereit fühlte, was bedeutete, wann immer die Panik es befahl, wartete jeder Wurf auf seinen Beat. Das Muster wurde langsamer, höher und ruhiger.","Die zweite Lösung war, wohin ich schaute. Ich hatte auf meine Hände gestarrt, was so ist, als würde man ein Buch lesen, indem man seine Augenlider beobachtet. Als ich meinen Blick zu den Peaks hob, den zwei Punkten oben an den Bögen, fingen meine Hände an, von selbst zu fangen. Die Peaks sagten mir, ob die Würfe gleichmäßig waren; die Hände brauchten keine Aufsicht.","Zwölf Würfe wurden zwanzig, dann fünfzig. Eines Abends jonglierte ich einen ganzen Acht-Takt-Step ohne Drop durch und grinste wie ein Idiot an die Decke. Die App nannte es einen Clean Run. Ich nannte es das erste Mal, dass sich Jonglieren wie Musik anfühlte statt wie ein Kampf.","Wenn du bei vier Würfen feststeckst, probiere, was bei mir funktioniert hat: laut zählen, auf den Beat werfen, auf die Peaks schauen. Und drop ohne Drama. Der Boden ist der Ort, an dem jede Cascade beginnt."]},"why-we-count-in-bars":{"title":"Warum wir in Takten zählen, nicht in Sekunden","summary":"Eine vierzigsekündige Hold ergibt Sinn für eine Dehnung; ein Jongliermuster lebt auf einem Beat, also messen wir Übung in Takten.","body":["Als wir anfingen, SynthFlow zu bauen, war die erste große Entscheidung, wie man einen Routine-Step misst. Unsere Schwester-App SynthYoga zählt Holds in Sekunden und Atemzügen. Das funktioniert für eine Pose, die du hältst. Es funktioniert nicht für ein Muster, das sich auf einem Beat wiederholt.","Ein Jonglierwurf, eine Staff-Halbdrehung und eine Hoop-Umlaufbahn sind alle Zyklen. Wenn die Musik mit 100 BPM läuft und deine Cascade mit 103, jonglierst du nicht zur Musik; du jonglierst daneben, und innerhalb einer Minute bist du einen Beat hinterher. Steps in Takten bei einem Tempo zu messen bedeutet, dass Musik, Counts, die 3D-Figur und der nächste Step alle auf demselben Downbeat starten.","Takte machen Fortschritt auch konkret. „Jongliere eine Minute“ ist vage: eine Minute wovon, bei welcher Geschwindigkeit? „Acht Takte Cascade bei 96 BPM“ ist eine spezifische, wiederholbare Herausforderung. Wenn du sie sauber schaffst, kann die nächste Session 104 verlangen. So funktionieren Tempo-Leitern, und deshalb hängt Mastery in der App von Clean Runs ab, nicht nur von Zeit.","Es brauchte ernsthaftes Engineering. Jede Animation wird von derselben Audiouhr wie die Musik angetrieben und im Voraus geplant, damit nichts stockt. Mitgelieferte Tracks haben gemessene Tempi und Downbeats. Generierte Percussion füllt jedes Tempo, das du wählst. Tracks von deinem Gerät werden analysiert und mit einem Tap-Test geprüft. Streaming-Video ist im gezählten Üben ausgeschaltet, weil wir es nicht auf dem Beat halten können.","Das Ergebnis ist, dass der Beat zum Lehrer wird. Wenn du driftest, hörst du es. Wenn du einrastest, fühlst du es. Das Zählen in Takten entpuppte sich als die wichtigste Designentscheidung, die wir getroffen haben."]},"staff-hit-me-in-the-head":{"title":"Der Staff traf mich am Kopf (und andere Lektionen)","summary":"Jeder Staff-Spinner wird mal bonkt; Polsterung, Ebenen und Geduld machen aus den Bonks Fortschritt.","body":["Meine erste Acht endete damit, dass der Staff von meinem Schädel abprallte und der Hund den Raum verließ. Meine zweite endete genauso, minus Hund. Wenn du Staff lernst, wirst du getroffen. Die Frage ist, wie hart, und was du daraus lernst.","Lektion eins: Polsterung ist keine Feigheit. Ein Übungs-Staff mit weichen Enden machte aus Bonks Schulterzucken. Schulterzucken ist wichtig, denn Angst lässt dich zusammenzucken, und ein zusammenzuckendes Handgelenk zieht den Staff aus seiner Ebene, was den nächsten Bonk verursacht.","Lektion zwei: Die meisten Treffer kommen von gekippten Ebenen. Als ich mich von der Seite filmte, konnte ich sehen, wie der Staff sich bei jeder Drehung oben zu meinem Gesicht neigte. Meine Handgelenke rollten nach innen. Das Ebenen-Overlay im 3D-Viewer zeigte die saubere Version: der Staff in einer flachen Fläche neben dem Körper, nie nach innen geneigt. Das Handgelenk zu korrigieren, korrigierte die Bonks.","Lektion drei: Langsam und gezählt schlägt schnell und hoffnungsvoll. Ich senkte das Tempo auf das untere Ende des Bereichs der Acht und zählte „rechte Seite, linke Seite“ mit der Musik. Bei diesem Tempo konnte ich den Handwechsel spüren und die Ebene flach halten. Eine Woche später konnte ich wieder hochgehen.","Lektion vier: Lache. Staff-Spinning ist lächerlich und wunderbar. Die Bonks gehören zur Geschichte, die jeder in der Szene teilt. Trag einen Hut, wenn du musst, räum die Deckenlichter frei und spinne weiter."]},"hooping-for-people-who-cant-hoop":{"title":"Hooping für Menschen, die denken, sie können nicht hoopen","summary":"Die meisten Erwachsenen, die „nicht hoopen können“, hatten einen reifengroßen Spielzeug-Hoop; ein größerer Reifen und ein Vor-und-zurück-Impuls lösen das meiste.","body":["„Ich kann nicht hoopen“ hören Hoop-Lehrer ständig, meist von jemandem, der es zuletzt mit einem Kinder-Spielzeugreifen versucht hat. Kleine, leichte Reifen drehen schnell und fallen schnell. Sie verlangen schnelle, hektische Hüften. Erwachsene mit einem Reifen in Erwachsenengröße finden es oft viel handhabbarer.","Fang groß an. Ein Reifen, der auf dem Boden stehend etwa zwischen Taille und Brust reicht, dreht langsam genug, dass du den Rhythmus spüren kannst. Schwerere Reifen tragen auch mehr Schwung. Du kannst später kleiner gehen für Tempo und Off-Body-Tricks.","Impuls, nicht Kreis. Der häufigste Fehler ist der Versuch, große Kreise mit den Hüften zu machen. Waist Hooping ist meist ein kleines Vor-und-zurück-Wippen oder ein Seit-zu-Seit, im Takt mit dem Reifen. Ein Fuß leicht vorne hilft. Der Reifen berührt deine Vorder- und Rückseite; du schiebst sanft, wenn er herumkommt.","Zähl mit. Ein entspanntes Tempo, eine Umlaufbahn pro Beat, gibt deinem Körper einen Rhythmus, in den er sich einfinden kann. Die App startet Waist Hooping langsam und lässt dich dann steigern. Wenn der Reifen sinkt, gib etwas mehr Tempo in deinen Impuls, nicht eine größere Bewegung.","Erwarte, dass er in ein paar Sessions oft fällt und dann plötzlich nicht mehr. Hooping ist eine dieser Fähigkeiten, die klick machen. Wenn es klickt, wartet eine ganze Welt von On-Body- und Off-Body-Flow, und vieles davon braucht nicht mal die Taille."]},"unlocking-is-not-a-race":{"title":"Freischalten ist kein Wettrennen","summary":"Der Belohnungsbaum öffnet schwierigere Bewegungen, während du ihre Grundlagen meisterst; der Punkt sind die Grundlagen.","body":["SynthFlows Belohnungen sind Bewegungen. Meistere die Cascade und die Reverse Cascade öffnet sich; meistere den Front Spin und die Figure-8 erscheint. Es ist befriedigend, den Baum aufleuchten zu sehen, und wir haben es genau so designt. Aber jedes Freischalt-System hat eine Falle, und es lohnt sich, sie zu benennen.","Die Falle ist, Meisterschaft als abzuhakendes Kästchen zu behandeln. Du kannst an einem guten Tag technisch die Clean Runs für eine Bewegung loggen, die nächste freischalten und mit einer Grundlage weitermachen, die nur funktioniert, wenn alles gut läuft. Dann fühlen sich die schwierigeren Bewegungen unmöglich an, weil sie davon ausgehen, dass die Grundlage funktioniert, wenn etwas schiefgeht.","Meisterschaft im Flow bedeutet, dass die Bewegung Ablenkung übersteht: etwas Müdigkeit, ein anderes Tempo, jemand, der vorbeigeht. Deshalb verlangt Meisterschaft Clean Runs über mehrere Sessions, nicht nur in einer. Und deshalb empfehlen wir, regelmäßig zu gemeisterten Bewegungen zurückzukehren. Die Cascade ist kein Level, das du abschließt; sie ist der Boden, auf dem der ganze Jonglierbaum steht.","Gesperrte Bewegungen haben trotzdem Seiten. Du kannst über sie lesen, sie in 3D anschauen und sehen, was sie brauchen. Vorausschauen motiviert. Vorausüben ohne die Grundlagen ist meist frustrierend.","Genieß also die Unlocks, aber miss dich daran, wie leicht sich deine ältesten Bewegungen anfühlen. Wenn die Cascade langweilig ist, bist du bereit für Mills Mess. Wenn Mills Mess langweilig ist, hat der Baum mehr zu bieten."]},"practice-in-ten-minutes":{"title":"Eine echte Practice in zehn Minuten","summary":"Warm-up, eine Fokus-Bewegung, ein Link, ein kurzer Tempo-Anstieg und ein Cool-down: zehn Minuten, jeden Tag.","body":["Der häufigste Grund, den Leute fürs Nicht-Üben nennen, ist Zeit. Die Wahrheit ist, dass Flow-Skills brillant auf kurze, häufige Sessions reagieren. Hier ist die Zehn-Minuten-Form, die wir selbst nutzen.","Minute eins bis zwei: Warm-up. Handgelenkskreise, Armkreise, Schulterrollen, ein paar Hüftkreise, wenn du hoopst. Gezählt, in entspanntem Tempo, damit dein Timing mit deinen Gelenken aufwacht.","Minute drei bis fünf: deine Fokus-Bewegung. Eine Bewegung, an der du arbeitest, in einem Tempo, das du sauber schaffst. Mehrere kurze gezählte Steps statt einem langen, mit einem Atemzug dazwischen.","Minute sechs bis sieben: ein Link. Kombiniere die Fokus-Bewegung mit etwas, in das sie hinein- oder aus dem sie herausfließt. Cascade zu Reverse Cascade. Front Spin zu Figure-8. Waist zu Chest. Links sind das, was Practice wie Flow statt Drill wirken lässt.","Minute acht bis neun: ein kleiner Tempo-Anstieg. Zwei oder drei Stufen, ein paar BPM jeweils, aufhören bevor die Form bricht. End auf einer sauberen Stufe.","Minute zehn: Cool-down. Eine langsame, leichte Bewegung oder eine kurze Pause. Log deine Anstrengung. Fertig.","Zehn Minuten am Tag sind über eine Stunde fokussierte Practice pro Woche, verteilt auf die Art, die Koordination am liebsten mag. Der Practice Wizard baut Sessions dieser Größe, wenn du ihm sagst, dass du wenig Zeit hast, und die eingebauten kurzen Routinen folgen derselben Form."]},"antispin-broke-my-brain":{"title":"Antispin hat mein Gehirn zerstört (für eine Woche)","summary":"Den Staff gegen den Kreis der Hand zu drehen fühlt sich unmöglich an, bis die Counts jedem Petal einen Beat geben.","body":["Antispin ist der Punkt, an dem sich Staff Spinning wie Geometrie-Hausaufgaben anfühlt. Deine Hand zeichnet einen Kreis in die eine Richtung, während sich der Staff in die andere dreht, und die Enden ziehen eine Blume. Beim ersten Versuch produzierte ich eher etwas wie einen verwelkten Löwenzahn.","Was half, war, die Form zählbar zu machen. Ein vierblättriges Antispin hat vier Momente, in denen ein Ende direkt aus dem Kreis zeigt. Ich gab jedem einen Beat: oben, Seite, unten, Seite. Dann drehte ich die Musik weit unter mein normales Spin-Tempo und zielte einfach auf die Positionen auf den Beats.","Der Ghost im 3D-Viewer, der zeigt, wo der Staff auf dem nächsten Beat sein sollte, war diese Woche mein bester Freund. Genauso wie der Trail, der meine Blume zeichnete, sodass ich sehen konnte, wann die Petals ungleichmäßig waren. Meist war das untere Petal gestaucht, weil ich das untere Ende des Kreises überhastete.","Nach etwa einer Woche verschob sich etwas. Ich hörte auf, Hand und Staff als zwei Dinge zu denken, und begann, die Blume als eine Form zu fühlen. Das Tempo kam von selbst zurück.","Wenn Antispin dein Gehirn zerstört, soll es das. Gib jedem Petal einen Beat, verlangsame die Musik und lass deinen Körper es herausfinden. Es ist eines der besten Gefühle im Flow, wenn es klappt."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps für Mathe-Scheue","summary":"Du musst Mathe nicht mögen, um Siteswap zu nutzen; du musst nur wissen, dass größere Zahlen höher gehen.","body":["Siteswap-Notation hat den Ruf, Leute abzuschrecken. Jongleure sagen fröhlich „probier 531“, als würde das etwas erklären. Tut es auch, aber erst, wenn du ein paar Dinge weißt, und diese Dinge sind einfacher, als sie aussehen.","Hier ist fast alles, was du brauchst. Jede Zahl ist ein Throw. Größere Zahlen gehen höher. Ungerade Zahlen kreuzen zur anderen Hand; gerade Zahlen kommen zur selben Hand zurück. Eine 3 ist ein normaler Cascade-Throw. Eine 1 ist ein schneller Zip rüber. Eine 2 ist meist einfach den Ball halten.","Das reicht, um 441 zu lesen: zwei höhere Throws, die auf ihrer eigenen Seite bleiben, dann ein Zip rüber. Du kannst es jetzt versuchen, ohne ein weiteres Wort zu lesen. Throw, Throw, Zip, auf den Beat.","Wenn du noch ein Stück willst: Addiere die Zahlen und teile durch ihre Anzahl, und du bekommst die Ballanzahl. 4 + 4 + 1 = 9, geteilt durch 3 ist 3 Bälle. Wenn die Antwort keine ganze Zahl ist, kann das Pattern nicht jongliert werden. Das ist das ganze berühmte Average Theorem.","In SynthFlow hat jede Jonglier-Bewegung ein Siteswap, und die 3D-Engine animiert direkt daraus. Das heißt, die Figur wirft immer genau die Höhen, die die Zahlen beschreiben, auf den exakten Beats. Ein Siteswap langsam animiert zu sehen, ist der schnellste Weg, den wir kennen, damit die Zahlen Sinn ergeben. Kein Mathe-Abschluss nötig."]},"music-that-fights-you":{"title":"Wenn die Musik gegen dich kämpft","summary":"Ein Track, der gegen die Counts driftet, macht jede Bewegung schwerer; gemessene Tempos und generierte Beats lösen das.","body":["Du hast es wahrscheinlich gespürt: ein Song, den du liebst, eine Bewegung, die du kennst, und irgendwie fühlt sich alles falsch an. Du überhastest, du droppst, du gibst dir die Schuld. Oft liegt das Problem nicht bei dir. Es ist, dass das Tempo des Songs nicht zur Bewegung passt.","Jede Flow-Bewegung hat einen angenehmen Tempo-Bereich. Darunter stocken die Props; darüber werden Würfe flach und hektisch. Ein Track mit 128 BPM unter einer Hoop-Bewegung, die 90 mag, zwingt dich, zwischen Musik und Hoop zu wählen. Die gute Nachricht: Half Time und Double Time helfen – 128 kann eine Bewegung bei 64 tragen, ein Zyklus alle zwei Beats.","Drift ist das subtilere Problem. Wenn die Musik 120 sagt, die Counts aber 116, gleiten beide über eine Minute auseinander, und dein Körper kann nicht beiden folgen. Deshalb nutzt SynthFlow gemessene Tempi für die mitgelieferten Tracks, erzeugt Percussion in jedem exakten Tempo und prüft Tracks von deinem Gerät mit einem Tap-Test.","Wenn ein Track gegen dich arbeitet, kämpfe nicht zurück. Wechsle für die Step zum generierten Beat oder lass dir vom Builder einen Track im richtigen Bereich vorschlagen. Behalte die Songs, die du liebst, fürs freie Spielen, wo nichts zusammenpassen muss.","Musik sollte sich wie ein Partner anfühlen. Wenn sie sich wie ein Gegner anfühlt, wechsle die Musik, nicht deine Bewegung."]},"learning-alongside-my-kid":{"title":"Jonglieren lernen – zusammen mit meinem Kind","summary":"Zwei Anfänger, eine Tasche voller Bälle und eine Regel: Wir feiern Drops genauso laut wie Catches.","body":["Meine Tochter wollte Jonglieren lernen, und mir fiel auf, dass ich es selbst nicht konnte. Also lernten wir zusammen, zehn Minuten nach dem Abendessen, mit je drei Beanbags und einer Regel: Wir jubeln bei Drops genauso laut wie bei Catches.","Die Regel klingt albern. Sie entpuppte sich als der wichtigste Teil. Kinder und Erwachsene verkrampfen, wenn sie einen Fehler für peinlich halten. Verkrampfung macht Würfe schlechter. Bei jedem Drop zu jubeln machte den Boden zum Teil des Spiels und hielt uns beide locker.","Wir begannen mit einem Ball, warfen ihn im Takt von Hand zu Hand, auf Augenhöhe. Es fühlte sich etwa drei Einheiten lang zu leicht an und wurde dann plötzlich wichtig, denn Zwei-Ball-Exchanges funktionieren nur, wenn diese einzelnen Würfe konstant sind. Sie hatte den Exchange vor mir drauf und war unerträglich stolz darauf.","Die gezählte Musik half uns, zusammen zu üben. Gleiches Tempo, gleicher Downbeat, zwei Leute werfen im Takt. Wenn einer von uns das Muster verlor, machte der andere weiter, und der Dropper stieg beim nächsten „eins“ wieder ein.","Nach vier Wochen haben wir beide eine wackelige Cascade. Wichtiger noch: Wir haben eine Gewohnheit, auf die wir uns beide freuen. Wenn du ein Kind hast, das etwas lernen will, lerne es mit ihm. Zusammen Anfänger zu sein wird unterschätzt."]},"why-your-throws-drift-forward":{"title":"Warum deine Würfe nach vorne driften","summary":"Wenn du jede Cascade drei Schritte von deinem Startpunkt entfernt beendest, lehnen sich deine Würfe von dir weg. So holst du sie zurück.","body":["Jeder Jongleur kennt das Laufen. Du startest die Cascade in der Mitte des Raums und beendest sie mit der Nase an der Wand, während du dem Muster Schritt für Schritt hinterherjagst. Es fühlt sich an, als würden die Bälle dich ziehen. Tun sie nicht. Du wirfst sie nach vorne, ein paar Zentimeter auf einmal, und läufst dann hinterher, um aufzuholen.","Die Ursache sind fast immer die Ellbogen. Wenn du angespannt wirst, kippen die Unterarme nach vorne und die Hände lassen den Ball etwas vor dem Körper los. Jeder Wurf landet ein Stück weiter draußen, also findet der nächste Catch weiter draußen statt, also startet der nächste Wurf weiter draußen. Das summiert sich schnell.","Die Korrektur, die ich zuerst unterrichte, ist das Anlegen der Ellbogen. Halte die Ellbogen nah an den Rippen, die Unterarme ungefähr waagerecht, und wirf die Bälle gerade nach oben an deinen Augen vorbei statt nach vorne aus dir heraus. Es fühlt sich einen Tag lang eng an. Dann fühlt es sich ruhig an.","Die zweite Korrektur ist eine Wand. Stell dich mit etwa einem Unterarm Abstand davor und jongliere. Wenn die Würfe driften, sagt dir die Wand das sofort und laut. Zehn Minuten Wandtraining bringen dem Körper schneller bei, wie sich ein aufrechtes Muster anfühlt, als alles, was ich sagen kann.","Der Kameramodus von SynthFlow achtet ebenfalls auf Drift. Er verfolgt, wie viel größer dein Oberkörper für die Kamera über einen Schritt hinweg wirkt, was bedeutet, dass du auf sie zugehst, und stupst dich mit einem kurzen Hinweis an. Der 3D-Coach kann dir auch den Geist eines Vorwärtswurfs neben dem sauberen zeigen, damit du den Unterschied siehst, statt nur davon zu hören.","Drift ist kein Charakterfehler. Es ist eine Spannungsgewohnheit, und Gewohnheiten ändern sich durch Wiederholung. Leg die Ellbogen an, wirf nach oben statt nach außen, und lass die Wand dich ehrlich halten."]},"practising-to-a-click":{"title":"Üben zum Klick","summary":"Ein Metronom klingt nach der langweiligsten Sache der Welt. Es stellte sich als das heraus, was meinen Flow wie Tanzen wirken ließ.","body":["Ich habe mich jahrelang gegen den Klick gewehrt. Musik war für mich der Sinn der Flow Arts, und ein Metronom fühlte sich wie Hausaufgaben an. Dann sah eine Freundin, die Schlagzeug spielt, mir beim Jonglieren zu und sagte freundlich, dass ich jedes Mal schneller wurde, wenn ich mich freute, und langsamer, wenn ich Angst bekam. Sie hatte recht, und ich hatte keine Ahnung.","Also probierte ich eine Woche lang Üben zu nichts als einem Klick. Die erste Entdeckung war, dass ein gleichmäßiger Puls schwerer ist, als er klingt. Mein Two-in-One-Hand-Muster wollte hetzen. Mein Staff-Figure-8 wollte auf der schwachen Seite schleppen. Dem Klick war egal, wie ich mich fühlte; er hielt einfach die Zeit.","Die zweite Entdeckung war, dass der Klick Musik einfacher machte. Nach einer Woche, als ich wieder echte Tracks auflegte, konnte ich fühlen, wo der Beat im Klang saß. Ich hörte auf, gegen Songs mit lockerem Timing anzukämpfen, und begann, mir auszusuchen, an welchem Teil des Grooves ich mich festhake.","Die generierte Percussion von SynthFlow ist eine freundlichere Version des Klicks. Du wählst ein Kit, von einem schlichten Klick bis zu Handtrommeln, und es spielt in jedem Tempo, sodass ein Muster genau in der Geschwindigkeit leben kann, die du halten kannst. Es kann auch leise unter einem Musiktrack als Guide laufen. Ich nutze es immer noch allein für die ersten paar Minuten jeder Session.","Wenn du das ausprobieren willst, wähle ein Muster und ein Tempo, das sich etwas zu langsam anfühlt. Zähle vier Takte laut mit, dann hör auf zu zählen und höre einfach zu. Wenn sich Muster und Klick wie ein Klang anfühlen, erhöhe um vier BPM. Das ist die ganze Methode."]},"staff-in-a-small-apartment":{"title":"Staff in einer kleinen Wohnung","summary":"Ein 1,4 Meter langer Staff und eine 2,4 Meter hohe Decke können zusammenleben. Du musst nur deine Ebenen wählen.","body":["Meine Wohnung hat niedrige Decken, eine Lampe, die ich mag, und einen Nachbarn unten, der nachts arbeitet. Nichts davon ist ideal für Staff-Spinning. Ich habe ein Jahr lang in Parks geübt, bevor ich herausfand, dass der größte Teil meines Trainings doch drinnen stattfinden konnte.","Der Trick sind die Ebenen. Wheel-Plane-Spins, die großen neben dem Körper, brauchen die volle Höhe des Staffs über deinem Kopf. Wall-Plane-Arbeit vor dem Körper braucht Breite, aber weniger Höhe. Floor-Plane-Spins wie der Helicopter brauchen Platz über deinem Kopf, aber nichts um deine Schienbeine. Jeder Raum unterstützt andere Moves.","In meinem Wohnzimmer kann ich Isolations, Front Spins und langsame Figure-8s mit tiefen Armen machen. Im Flur kann ich gar nichts machen, also ist der Flur für Handgelenk-Aufwärmen. Das Schlafzimmer hat die höchste Decke, also findet dort Wheel-Plane-Arbeit statt, langsam, mit abgenommener Lampe, die in einer Schublade verstaut ist.","Kurze Staffs helfen auch. Ein Übungsstaff, der eine Handlänge kürzer ist als mein Performance-Staff, verwandelte viele Beinahe-Unfälle in einfachen Freiraum. Das Timing ändert sich ein wenig, also checke ich meinen Staff in voller Länge einmal pro Woche draußen.","Für die Nachbarn: Übungsmatten und Staffs mit weichen Enden. Ein Drop auf eine Yogamatte ist ein dumpfes Poltern statt ein Knall. Ich halte Indoor-Sessions auch auf gezählte Routinen von zehn Minuten, was den Lärm kurz und das Üben fokussiert hält.","Mit SynthFlow kannst du Bewegungen, die du zu Hause nicht machen kannst, als unerwünscht markieren, damit der Generator sie aus Indoor-Routinen weglässt. Kleine Räume stoppen den Fortschritt nicht. Sie machen dich nur sehr gut in Isolations."]},"hooping-after-40":{"title":"Hooping nach 40","summary":"Ich habe mit 43 zum ersten Mal einen Hoop in die Hand genommen. Mein Rücken, meine Knie und mein Stolz hatten alle eine Meinung. Folgendes hat funktioniert.","body":["Ich habe meinen ersten Erwachsenen-Hoop spontan nach einem Festival gekauft, überzeugt, dass ich furchtbar sein würde. Ich war furchtbar. Und trotzdem habe ich innerhalb eines Monats ganze Songs lang am Bauch gehoopt und nach sechs Monaten einfache Off-Body-Moves gemacht. Das Alter hat mich nicht aufgehalten. Es hat nur verändert, wie ich üben musste.","Die große Lektion war, richtig aufzuwärmen. Hip Circles, Torso Twists und sanfte Knee Bounces dauern drei Minuten und lassen den ersten Hoop der Session geschmeidig statt knarzig wirken. SynthFlow setzt Warm-ups aus gutem Grund an den Anfang jeder Routine, und nach einem steifen Morgen habe ich aufgehört, sie zu überspringen.","Die zweite Lektion war die Hoop-Größe. Ein größerer, etwas schwererer Hoop dreht langsamer, was dir mehr Zeit gibt und weniger vom unteren Rücken verlangt. Ich habe mit einem Hoop angefangen, der im Stehen zwischen Taille und Brust reichte, und ich nutze ihn immer noch für lange Practice-Sessions.","Drittens: pulsiere, kreise nicht. Anfänger schwingen die Hüften oft in einem Kreis, was die Wirbelsäule stärker verdreht als nötig. Ein Pulse nach vorne und hinten, oder seitlich, wenn der Hoop sich bei dir so dreht, hält den Hoop mit weniger Belastung oben. Der 3D-Coach zeigt das deutlich, wenn du auf die Hüften statt auf den Hoop schaust.","Und schließlich: kurz und oft schlägt lang und selten. Zehn Minuten viermal pro Woche haben mir mehr gebracht als eine Stunde am Sonntag. Mein Körper hat sich zwischen den Sessions erholt, und die Moves blieben hängen.","Wenn du über 40 bist und neugierig, fang an. Der Hoop weiß nicht, wie alt du bist."]},"fire-and-the-beginner":{"title":"Feuer und der Anfänger","summary":"Fire Spinning ist der sichtbarste Teil der Flow Arts und der Teil, nach dem Anfänger am häufigsten fragen. Die ehrliche Antwort ist: noch nicht, und nicht allein.","body":["Jede Woche fragt uns jemand, wann SynthFlow Feuer unterrichten wird. Das ist eine berechtigte Frage. Feuer ist schön, und viele Spinner sind in die Szene gekommen, nachdem sie nachts einen Fire Circle gesehen haben. Aber wir werden niemanden dazu coachen, ein Prop anzuzünden, und dieser Beitrag erklärt, warum.","Feuer bringt Gefahren mit sich, die nichts mit Können zu tun haben: Umgang mit Brennstoff, Kleidung, Wind, Zuschauer, Verbrennungen und Löschen. Das lernt man von erfahrenen Leuten persönlich, mit einer ausgebildeten Safety-Person und richtiger Ausrüstung bereit. Eine App kann nicht deinen Fuel Dump, deine Baumwollkleidung oder dein Safety-Towel prüfen.","Was die App tun kann, ist, dir die Skills aufzubauen, die Feuer braucht, bevor du dich ihm überhaupt näherst. Das bedeutet Moves, die du zuverlässig einen ganzen Song lang bei gleichmäßigem Tempo ohne Drops schaffst. Wenn ein Pattern dich zu Hause mit einem Practice-Prop noch überrascht, ist es nicht bereit für Feuer.","Ein nützlicher Test aus der Feuer-Community: Kannst du die Routine mit halb geschlossenen Augen im Dunkeln machen, während jemand mit dir spricht? Feuer ist hell, heiß und laut und nimmt deine Aufmerksamkeit. Dein Körper muss die Moves ohne Aufsicht kennen.","LED-Props sind ein großartiger Zwischenschritt. Sie geben dir den Night-Time-Look, die Trails und die Reaktion des Publikums ohne das Risiko. SynthFlows LED-Style-Pack zeigt, wie deine Patterns beleuchtet aussehen, was auch eine gute Möglichkeit ist, unsaubere Planes zu erkennen.","Wenn du bereit bist, such dir einen lokalen Fire Jam, stell dich vor und bitte darum, zuerst Safety zu lernen. Übe bis dahin mit Practice-Props. Das Feuer wird noch da sein."]},"four-balls-taught-me-patience":{"title":"Vier Bälle haben mir Geduld beigebracht","summary":"Von drei auf vier Bälle zu kommen hat länger gedauert als drei überhaupt zu lernen, und es hat verändert, wie ich über Üben denke.","body":["Drei Bälle haben fünf Wochen gebraucht. Vier haben fünf Monate gebraucht. Niemand hat mich gewarnt, also warne ich dich: Vier Bälle sind nicht drei Bälle plus einer. Es ist ein völlig anderes Pattern, und dein Körper muss es von Grund auf lernen.","In einer Four-Ball Fountain jongliert jede Hand zwei Bälle für sich, und die Bälle kreuzen sich nie. Die Hände wechseln sich meist ab, aber es gibt überhaupt keinen Austausch zwischen ihnen. Alles, was ich darüber gelernt hatte, einen Ball von der anderen Hand zu fangen, war plötzlich nutzlos.","Also ging ich zurück zu einer Hand. Zwei Bälle in der rechten Hand, in Columns, dann Circles, bis ich fünfzig Würfe ohne Nachdenken schaffte. Dann die linke Hand, die dreimal so lange brauchte. Dann beide Hände zusammen, erst synchron, dann alternierend. Die Tempo-Leiter in SynthFlow hat hier geholfen: Ich habe jede Woche unten im Bereich der Fountain angefangen und bin erst nach einem sauberen Run höher gegangen.","Die Geduldslektion kam von den Plateaus. In manchen Wochen verbesserte sich nichts. Ich habe trotzdem Drops und saubere Runs aufgezeichnet, und der Graph zeigte langsamen Fortschritt, auch wenn es sich nach keinem anfühlte. Die Daten machten die langweiligen Wochen erträglich.","Die andere Lektion handelte von Erholung. Vier Bälle ermüdeten meine Unterarme auf eine Weise, wie drei es nie taten. Als ich jeden Tag übte, wurde ich schlechter. Als ich jeden zweiten Tag übte, wurde ich besser. Griffmuskeln brauchen Erholung wie alle anderen.","Wenn du zwischen drei und vier feststeckst, teile das Problem auf, vertrau den langsamen Wochen und gönn deinen Unterarmen einen Tag Pause. Es kommt."]},"the-escalator-and-hand-traffic":{"title":"Der Escalator und die Kunst des Hand-Verkehrs","summary":"Hoop-Hand-Moves sehen wie Magie aus, bis man sieht, dass sie nur sorgfältiges Verkehrsmanagement zwischen zwei Händen sind.","body":["Als ich das erste Mal einen Escalator sah, schien der Hoop die Arme der Hooperin hochzuklettern und wieder herunterzuschweben, endlos, ohne erkennbaren Griff. Ich nahm an, dass es Jahre des Übens braucht. Es brauchte etwa drei Wochen, nachdem ich verstanden hatte, dass es nur ein Muster von Handoffs ist.","Fast jeder Off-Body-Hoop-Move dreht sich darum, welche Hand den Hoop hält, wann sie loslässt und wo die andere Hand ihn trifft. Wenn das Timing zwischen den Händen unscharf ist, wackelt der Hoop aus seiner Plane und der Move fällt auseinander. Wenn das Timing sauber ist, sieht es aus, als würde der Hoop sich von selbst bewegen.","Also fing ich an, Handoffs zu benennen. Über SynthFlows Count sagte ich die Hände laut statt der Zahlen: rechts, links, rechts, links, eine auf jedem Beat. Sie mit der Musik zu sagen, zwang mich zu bemerken, wenn meine linke Hand zu früh griff. Zu frühes Greifen war die Quelle fast jedes Wackelns.","Der zweite Schlüssel war, den Hoop in seiner Plane zu halten. Eine Hand, die sich beim Greifen verdreht, kippt den Hoop, und ein gekippter Hoop ist eine halbe Sekunde später ein gefallener Hoop. Das Plane-Overlay hilft hier, und Üben vor einem Spiegel mit langsamen Tempi ebenso.","Als der Escalator zuverlässig war, kamen andere Hand-Moves schneller. Isolations, Passes und Lassos nutzen dieselbe Idee: klare Handoffs, flache Planes, gleichmäßiges Timing. Die Magie ist nur Verkehrsmanagement."]},"behind-the-back-without-fear":{"title":"Hinter dem Rücken ohne Angst","summary":"Staff-Passes hinter dem Rücken sind die Stelle, an der die meisten Spinner hängen bleiben. Das Problem ist meist nicht das Können, sondern der Drang hinzuschauen.","body":["Monatelang war mein Behind-the-Back-Pass ein Front Pass mit hoffnungsvollem Twist. Ich startete den Move, geriet in Panik, als der Staff aus meinem Blickfeld verschwand, und brachte ihn wieder nach vorne. Der Staff ging nie wirklich hinter meinen Rücken. Mein Gehirn ließ es nicht zu.","Der Durchbruch kam, als ich akzeptierte, dass ich den Move nicht sehen kann. Einen Behind-the-Back-Pass kann man nicht beobachten. Du musst fühlen, wo der Staff ist, von der Hand, die loslässt, und der wartenden Hand vertrauen.","Ich trainierte dieses Gefühl in Zeitlupe. Ohne überhaupt zu spinnen, gab ich den Staff hinter meinem Rücken von Hand zu Hand, mit Blick nach vorne. Dann mit einer langsamen halben Drehung zuerst. Dann unten im Tempo-Bereich des Moves, gezählt. Jeder Schritt fühlte sich albern an. Jeder Schritt funktionierte.","Der 3D-Coach war überraschend nützlich, weil ich die Ansicht drehen und den Move von hinten betrachten konnte. Zu sehen, wo die Hände sich treffen und wie der Staff in der Wall Plane bleibt, während er herumgeht, gab meinem Körper eine Karte, die er von vorne nicht bekommen konnte.","Die zweite Angst war, mich zu treffen. Ein Practice-Staff mit weichen Enden und viel freier Raum haben das gelöst. Als ich wusste, dass ein Fehler nur einen sanften Stups statt eines blauen Flecks kostet, hörte ich auf zu zucken, und das Zucken hatte die Fehler verursacht.","Wenn Behind the Back dir noch Angst macht, verlangsame es stark, nimm den Spin raus und halte den Blick nach vorne. Deine Hände wissen mehr, als du denkst."]},"why-reverse-feels-wrong":{"title":"Warum sich die Reverse Cascade falsch anfühlt","summary":"Die Reverse Cascade nutzt dieselben Hände, dieselben Bälle und denselben Rhythmus wie die Cascade. Warum fühlt es sich also an, als würde man neu anfangen?","body":["Als ich die Reverse Cascade lernte, erwartete ich, dass sie einen Nachmittag dauern würde. Es sind dieselben drei Bälle, dieselben alternierenden Hände und dasselbe Tempo wie bei der Cascade. Sie hat drei Wochen gedauert, und ich konnte nicht herausfinden, warum.","Die Antwort ist die Richtung. In einer normalen Cascade wird jeder Ball von der Innenseite des Musters geworfen und außen gefangen. In einer Reverse Cascade wird der Ball von außen über den ankommenden Ball hinweg geworfen und innen gefangen. Deine Hände machen denselben Rhythmus, aber völlig andere Formen.","Die neue Form bringt dein Timing durcheinander. In der Cascade wirfst du genau in dem Moment, in dem der ankommende Ball zu fallen beginnt. In der Reverse Cascade musst du etwas früher werfen, damit dein Ball über den anderen hinwegkommt. Wirfst du zum alten Zeitpunkt, kollidieren die Bälle.","Ich habe es zuerst mit zwei Bällen hinbekommen. Zwei Bälle, Reverse-Richtung, auf den Beat gezählt, bis es automatisch lief. Dann drei Bälle in langsamem Tempo, während ich die Zählzeiten laut ausgesprochen habe. SynthFlows Ghost-Overlay zeigte mir einen typischen Fehler – einen zu niedrigen Wurf, der den anderen Ball streift – und ich konnte sehen, dass ich genau das tat.","Als es Klick machte, hat es viel freigeschaltet. Cascade und Reverse zu mischen ist die Grundlage vieler Tricks, und die Reverse-Form taucht wieder in Mills Mess auf. Drei Wochen schlecht darin zu sein hat sich gelohnt."]},"making-a-prop-stand-still":{"title":"Isolations: ein Prop scheinbar stillstehen lassen","summary":"Eine Isolation ist eine Bewegung, bei der das Prop scheinbar an einem Ort bleibt, während du dich darum herum bewegst. Es ist die befriedigendste Illusion in den Flow Arts.","body":["Als ich zum ersten Mal eine Staff-Isolation hinbekam, fragte mich mein Freund, wie der Staff schwebt. Er schwebte natürlich nicht. Meine Hände bewegten sich in einem sorgfältigen Kreis, sodass ein Punkt auf dem Staff fest in der Luft blieb. Aber von außen sah es unmöglich aus, und dieses Gefühl ist der Grund, warum ich Isolations liebe.","Jede Isolation funktioniert gleich. Wähle einen Punkt auf dem Prop, meist die Mitte oder ein Ende, und halte diesen Punkt still, während sich der Rest des Props dreht. Deine Hände müssen sich genau entgegengesetzt zu der Richtung bewegen, in die das Prop will. Es ist kontraintuitiv und leicht hypnotisch.","Das Schwierigste ist, dass sich dein Körper mitbewegt. Die Hüften verschieben sich, die Schultern drehen sich, und jede kleine Bewegung zeigt sich als Wackeln im fixierten Punkt. Ich habe vor einem Spiegel geübt, mit einem Stück Klebeband auf dem Glas, das markierte, wo der fixierte Punkt sein sollte. Wenn die Mitte des Props das Klebeband verließ, wusste ich es.","Hoop-Isolations folgen derselben Idee. In SynthFlow schalte ich die Trails im 3D-Viewer ein und beobachte den Coach: Bei einer sauberen Isolation bleibt der Trail um den fixierten Punkt winzig. Als ich das Tempo stark verlangsamte und es nachmachte, konnte ich spüren, wie meine Hände oben in jedem Kreis abdrifteten.","Isolations bauen auch Kontrolle auf, die allem anderen hilft. Sobald du ein Prop stillhalten kannst, kannst du es überall platzieren, wo du willst. Ebenen werden flacher, Übergänge sauberer, und dein Flow wirkt zunehmend beabsichtigt statt zufällig.","Fang langsam an, markiere den fixierten Punkt und beobachte ihn wie ein Falke. Dann zeig es einem Freund und genieße sein Gesicht."]}}`),i={"zero-to-cascade":{name:`Von null zur Cascade in 4 Wochen`,description:`Ein Ball, dann zwei, dann kommt der dritte dazu. Eine kurze Einheit pro Tag reicht: Schließe die Routine jeder Woche ab, um ihre Bewegung zu meistern und die nächste freizuschalten.`,weeks:[{label:`Woche 1 · Ein Ball`},{label:`Woche 2 · Zwei Bälle`},{label:`Woche 3 · Der dritte Ball`},{label:`Woche 4 · Cascade`}]},"beyond-the-cascade":{name:`Jenseits der Kaskade`,description:`Vier Wochen Abwechslung mit drei Bällen: erst Tennis und Claws, dann Körperwürfe, dann Synchro-Muster, immer zwei Bälle gleichzeitig.`,weeks:[{label:`Woche 1 · Tennis und Claws`},{label:`Woche 2 · Halbschauer`},{label:`Woche 3 · Körperwürfe`},{label:`Woche 4 · Säulen`}]},"first-clubs":{name:`Erste Keulen`,description:`Von einer einzelnen rotierenden Keule zu einer stabilen Drei-Keulen-Kaskade, dann Doubles für Wurfhöhe und Drehkontrolle.`,weeks:[{label:`Woche 1 · Eine Keule`},{label:`Woche 2 · Austausch`},{label:`Woche 3 · Kaskade`},{label:`Woche 4 · Doubles`}]},"passing-with-a-partner":{name:`Passing zu zweit`,description:`Zwei Jonglierende, Gesicht zu Gesicht. Erst ein Ball rüber, dann je zwei Bälle auf gemeinsamem Beat, dann Sechser, Vierer und Zweier mit je drei Bällen.`,weeks:[{label:`Woche 1 · Ein Ball rüber`},{label:`Woche 2 · Je zwei Bälle`},{label:`Woche 3 · Sechser und Vierer`},{label:`Woche 4 · Zweier`}]},"staff-foundations":{name:`Staff-Grundlagen`,description:`Wheel Spin und Front Spin, die Figure 8 und der Pass-through: die vier Moves, aus denen fast jeder Staff-Flow entsteht.`,weeks:[{label:`Woche 1 · Wheel Spin`},{label:`Woche 2 · Front Spin`},{label:`Woche 3 · Figure 8`},{label:`Woche 4 · Pass-through`}]},"staff-contact":{name:`Staff-Kontakt`,description:`Lockere deinen Griff Woche für Woche: Steering Wheel und Fishtail, dann Handrollen, dann der Staff, der sich auf dem Unterarm dreht.`,weeks:[{label:`Woche 1 · Steering Wheel`},{label:`Woche 2 · Fishtail`},{label:`Woche 3 · Handrolle`},{label:`Woche 4 · Unterarmrolle`},{label:`Week 5 · Angel / session`}]},"double-staff-start":{name:`Double-Staff-Start`,description:`Von zwei Stäben im Gleichschlag zu Split Time und Wheels auf beiden Seiten.`,weeks:[{label:`Woche 1 · Same Time`},{label:`Woche 2 · Split Time`},{label:`Woche 3 · Wheels`},{label:`Woche 4 · Split Wheels`}]},"hoop-body-ladder":{name:`Hoop-Body-Ladder`,description:`Hooping an der Taille in beide Richtungen, dann runter zu Hüften und Oberschenkeln und wieder hoch zur Brust.`,weeks:[{label:`Woche 1 · Beide Richtungen`},{label:`Woche 2 · Hüfte`},{label:`Woche 3 · Oberschenkel`},{label:`Woche 4 · Chest Lift`}]},"hoop-doubles-start":{name:`Hoop-Doubles-Start`,description:`Ein Hoop in jeder Hand: gespiegelte Spins, versetzte Spins, Seitwärtsspins, dann einer an der Taille und einer in der Hand.`,weeks:[{label:`Woche 1 · Gespiegelte Spins`},{label:`Woche 2 · Versetzte Spins`},{label:`Woche 3 · Seitwärtsspins`},{label:`Woche 4 · Taille und Hand`}]},"off-body-hoop":{name:`Off-body Hoop`,description:`Vom Hoop-Spin auf einer Hand über Lassos, Passes, Wedgies und die Isolation, die den Hoop scheinbar schweben lässt.`,weeks:[{label:`Woche 1 · Hand Spin`},{label:`Woche 2 · Lasso und Pass`},{label:`Woche 3 · Wedgie`},{label:`Woche 4 · Isolation`},{label:`Week 5 · Planes + on↔off`}]},"first-poi":{name:`Dein erstes Poi`,description:`Erst ein Poi, dann ein Paar: Wallplane-Spins in beide Richtungen, Wheelplane an den Seiten, danach Split Time.`,weeks:[{label:`Woche 1 · Ein Poi`},{label:`Woche 2 · Wallplane`},{label:`Woche 3 · Wheelplane`},{label:`Woche 4 · Split Time`}]},"poi-weave-ladder":{name:`Poi-Weave-Leiter`,description:`Vom Chase the Sun zum 3-Beat-Weave in beide Richtungen, dann zum schnelleren 2-Beat-Weave.`,weeks:[{label:`Woche 1 · Chase the Sun`},{label:`Woche 2 · 3-Beat-Weave`},{label:`Woche 3 · Reverse-Weave`},{label:`Woche 4 · 2-Beat-Weave`},{label:`Week 5 · Five-beat / degrees`}]},"poi-antispin-start":{name:`Einstieg ins Antispin`,description:`Zuerst Extensions und Isolationen, dann Antispin mit einem Poi und die vierblättrige Flower mit beiden.`,weeks:[{label:`Woche 1 · Extensions`},{label:`Woche 2 · Isolation`},{label:`Woche 3 · Antispin mit einem Poi`},{label:`Woche 4 · Antispin-Flower`},{label:`Week 5 · Hybrids`}]},"staff-tech-map":{name:`Staff tech map`,description:`Timing cells and flowers: symmetry lab, then isolation and antispin flower work.`,weeks:[{label:`Week 1 · Symmetry cells`},{label:`Week 2 · Figure 8`},{label:`Week 3 · Isolation`},{label:`Week 4 · Antispin flower`}]},"hoop-isolation-ladder":{name:`Hoop isolation ladder`,description:`Float isolations and cateyes, then reconnect with weave and pass.`,weeks:[{label:`Week 1 · Isolation`},{label:`Week 2 · Cateye`},{label:`Week 3 · Weave`},{label:`Week 4 · Pass link`}]}},a={"sf-ambient-70":{name:`Langsamer Orbit`},"sf-world-75":{name:`Marktschritte`},"sf-ambient-80":{name:`Laternen-Drift`},"sf-world-85":{name:`Wüstenrad`},"sf-handdrum-90":{name:`Kreistrommel`},"sf-funk-95":{name:`Lose Handgelenke`},"sf-handdrum-100":{name:`Feuerlicht-Hände`},"sf-world-105":{name:`Flussglocken`},"sf-funk-110":{name:`Taschen-Kaskade`},"sf-handdrum-115":{name:`Innenhof-Groove`},"sf-electronic-120":{name:`Neon-Staff`},"sf-funk-125":{name:`Bounce-Pattern`},"sf-electronic-130":{name:`Pixel-Hoop`},"sf-handdrum-135":{name:`Sonnenuntergang-Djembe`},"sf-electronic-140":{name:`LED-Spuren`},"sf-funk-145":{name:`Spin-Zyklus`},"sf-electronic-150":{name:`Strobe-Flow`},"sf-handdrum-155":{name:`Schnelle Handflächen`},"sf-electronic-160":{name:`Nacht-Spinner`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};